-- ============================================================
-- Sekai Data Object 全量数据初始化（自动构建 2026-08-10）
-- 番剧 200 部 / 台词 5777 条 / 覆盖 108 部番剧
-- ============================================================
CREATE DATABASE IF NOT EXISTS sekai_friend DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE sekai_friend;
DELETE FROM sekai_dataobject_anime_quote;
DELETE FROM sekai_dataobject_anime_character;
DELETE FROM sekai_dataobject_anime_series;
DELETE FROM sekai_dataobject_anime_user WHERE username <> 'admin';
ALTER TABLE sekai_dataobject_anime_quote AUTO_INCREMENT = 1;
ALTER TABLE sekai_dataobject_anime_character AUTO_INCREMENT = 1;
ALTER TABLE sekai_dataobject_anime_series AUTO_INCREMENT = 1;
CREATE TABLE IF NOT EXISTS sekai_dataobject_anime_series (
    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '番剧ID',
    title VARCHAR(100) NOT NULL COMMENT '番剧官方中文名称',
    original_title VARCHAR(100) DEFAULT NULL COMMENT '番剧原名（日文/英文）',
    type VARCHAR(50) DEFAULT NULL COMMENT '类型：TV/剧场版/OVA/网络动画',
    studio VARCHAR(100) DEFAULT NULL COMMENT '制作公司',
    release_date DATE DEFAULT NULL COMMENT '首播日期',
    total_episodes INT DEFAULT NULL COMMENT '总集数',
    score DECIMAL(3,1) DEFAULT NULL COMMENT '官方评分',
    synopsis TEXT DEFAULT NULL COMMENT '剧情简介（官方）',
    cover_url VARCHAR(1000) DEFAULT NULL COMMENT '封面图片地址',
    tags VARCHAR(255) DEFAULT NULL COMMENT '标签，用逗号分隔',
    official_url VARCHAR(1000) DEFAULT NULL COMMENT '官网链接',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间'
) COMMENT='番剧表';

CREATE TABLE IF NOT EXISTS sekai_dataobject_anime_character (
    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '人物ID',
    series_id BIGINT DEFAULT NULL COMMENT '所属番剧ID',
    name VARCHAR(100) NOT NULL COMMENT '人物官方中文名',
    original_name VARCHAR(100) DEFAULT NULL COMMENT '人物原名（日文名）',
    role VARCHAR(50) DEFAULT NULL COMMENT '人物定位（主角/配角/反派）',
    voice_actor VARCHAR(100) DEFAULT NULL COMMENT '声优（CV）',
    description TEXT DEFAULT NULL COMMENT '人物官方简介',
    image_url VARCHAR(1000) DEFAULT NULL COMMENT '人物立绘/图片地址',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) COMMENT='人物表';

CREATE TABLE IF NOT EXISTS sekai_dataobject_anime_quote (
    id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '台词ID',
    series_id BIGINT DEFAULT NULL COMMENT '所属番剧ID',
    character_id BIGINT DEFAULT NULL COMMENT '人物ID',
    character_name VARCHAR(100) DEFAULT NULL COMMENT '说出台词的角色名',
    content VARCHAR(1000) NOT NULL COMMENT '台词原文（官方台词）',
    episode INT DEFAULT NULL COMMENT '台词所在集数',
    time_point DECIMAL(8,1) DEFAULT NULL COMMENT '台词出现时间点（秒）',
    audio_url VARCHAR(1000) DEFAULT NULL COMMENT '台词原音频地址（上传的原音频）',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) COMMENT='台词表';

INSERT INTO sekai_dataobject_anime_series (title, original_title, type, studio, release_date, total_episodes, score, synopsis, cover_url, tags, official_url) VALUES
('星际牛仔 天国之扉', 'カウボーイビバップ', 'TV', 'Sunrise', '1998-01-01', '26', '8.6', 'Enter a world in the distant future, where Bounty Hunters roam the solar system. Spike and Jet, bounty hunting partners, set out on journeys in an ever struggling effort to win bounty rewards to survive. While traveling, they meet up with other very interesting people. Could Faye, the beautiful and ridiculously poor gambler, Edward, the computer genius, and Ein, the engineered dog be a good addition to the group?', '/uploads/images/s_1.jpg', 'Space,Crime,Episodic,Ensemble Cast,Primarily Adult Cast,Philosophy,Tragedy,Travel', 'https://anilist.co/anime/1'),
('怪物', 'MONSTER', 'TV', 'MADHOUSE', '2004-01-01', '74', '8.8', 'Dr. Kenzo Tenma is a renowned Japanese brain surgeon working at a leading hospital in Germany. One night, Dr. Tenma risks his reputation and career to save the life of a critically wounded young boy over that of the town mayor who had been planning to support the hospital financially. A string of mysterious murders begin to occur soon after the operation, and Dr. Tenma emerges as the primary suspect despite no incriminating evidence. A doctor is taught to believe that all life is equal; however, when another series of murders occur in the surgeon''s vicinity, Dr. Tenma''s beliefs are shaken as his actions that night are shown to have much broader consequences than he could have imagined. Leaving behind his life as a surgeon he embarks on a journey across the country to unravel the mystery of the boy he saved.', '/uploads/images/s_19.jpg', 'Crime,Seinen,Detective,Philosophy,Ensemble Cast,Fugitive,Primarily Adult Cast,Memory Manipulation', 'https://anilist.co/anime/19'),
('火影忍者 动画开播20周年纪念PV「ROAD OF NARUTO」', 'NARUTO -ナルト-', 'TV', 'Studio Pierrot', '2002-01-01', '220', '8.0', 'Naruto Uzumaki, a hyperactive and knuckle-headed ninja, lives in Konohagakure, the Hidden Leaf village. Moments prior to his birth, a huge demon known as the Kyuubi, the Nine-tailed Fox, attacked Konohagakure and wreaked havoc. In order to put an end to the Kyuubi''s rampage, the leader of the village, the 4th Hokage, sacrificed his life and sealed the monstrous beast inside the newborn Naruto. Shunned because of the presence of the Kyuubi inside him, Naruto struggles to find his place in the village. He strives to become the Hokage of Konohagakure, and he meets many friends and foes along the way. (Source: MAL Rewrite)', '/uploads/images/s_20.jpg', 'Ninja,Shounen,Coming of Age,Male Protagonist,Criminal Organization,Orphan,Super Power,Revenge', 'https://anilist.co/anime/20'),
('航海王：打倒！海贼强萨克！', 'ONE PIECE', 'TV', 'Toei Animation', '1999-01-01', '0', '8.7', 'Gold Roger was known as the Pirate King, the strongest and most infamous being to have sailed the Grand Line. The capture and death of Roger by the World Government brought a change throughout the world. His last words before his death revealed the location of the greatest treasure in the world, One Piece. It was this revelation that brought about the Grand Age of Pirates, men who dreamed of finding One Piece (which promises an unlimited amount of riches and fame), and quite possibly the most coveted of titles for the person who found it, the title of the Pirate King. Enter Monkey D. Luffy, a 17-year-old boy that defies your standard definition of a pirate. Rather than the popular persona of a wicked, hardened, toothless pirate who ransacks villages for fun, Luffy’s reason for being a pirate is one of pure wonder; the thought of an exciting adventure and meeting new and intriguing people, along with finding One Piece, are his reasons of becoming a pirate. Following in the footsteps of his childhood hero, Luffy and his crew travel across the Grand Line, experiencing crazy adventures, unveiling dark mysteries and battling strong enemies, all in order to reach One Piece. *This includes the following special episodes: - Chopperman to the Rescue! Protect the TV Station by the Shore! (Episode 336) - The Strongest Tag-Team! Luffy and Toriko''s Hard Struggle! (Episode 492) - Team Formation! Save Chopper (Episode 542) - History''s Strongest Collaboration vs. Glutton of the Sea (Episode ', '/uploads/images/s_21.jpg', 'Pirates,Travel,Shounen,Ensemble Cast,Super Power,Found Family,Male Protagonist,Ships', 'https://anilist.co/anime/21'),
('新世纪福音战士', '新世紀エヴァンゲリオン', 'TV', 'Gainax', '1995-01-01', '26', '8.3', 'In the year 2015, the Angels, huge, tremendously powerful, alien war machines, appear in Tokyo for the second time. The only hope for Mankind''s survival lies in the Evangelion, a humanoid fighting machine developed by NERV, a special United Nations agency. Capable of withstanding anything the Angels can dish out, the Evangelion''s one drawback lies in the limited number of people able to pilot them. Only a handful of teenagers, all born fourteen years ago, nine months after the Angels first appeared, are able to interface with the Evangelion. One such teenager is Shinji Ikari, whose father heads the NERV team that developed and maintains the Evangelion. Thrust into a maelstrom of battle and events that he does not understand, Shinji is forced to plumb the depths of his own inner resources for the courage and strength to not only fight, but to survive, or risk losing everything. (Source: AniDB) Note: Later releases include edited versions of Episodes 21-24 called the "Director''s Cut" with some visual editing and adding extra scenes that appeared in the theatrical recap ''Death''.', '/uploads/images/s_30.jpg', 'Philosophy,Coming of Age,Tragedy,Super Robot,Dystopian,Meta,Post-Apocalyptic,Angels', 'https://anilist.co/anime/30'),
('新世纪福音战士剧场版 Air/真心为你', '新世紀エヴァンゲリオン劇場版 Air/まごころを、君に', '剧场版', 'Gainax', '1997-01-01', '1', '8.5', 'NERV faces a brutal attack from SEELE, but with Asuka in a coma, and Shinji in a nervous breakdown, things soon turn into the surreal. This movie provides a concurrent ending to the final two episodes of the show Neon Genesis Evangelion. (Source: IMDb)', '/uploads/images/s_32.jpg', 'Philosophy,Tragedy,Coming of Age,Post-Apocalyptic,Meta,Denpa,Dystopian,Gods', 'https://anilist.co/anime/32'),
('钢之炼金术师 叹息之丘的圣星', '鋼の錬金術師', 'TV', 'bones', '2003-01-01', '51', '7.9', 'The rules of alchemy state that to gain something, one must lose something of equal value. Alchemy is the process of taking apart and reconstructing an object into a different entity, with the rules of alchemy to govern this procedure. However, there exists an object that can bring any alchemist above these rules, the object known as the Philosopher''s Stone. The young Edward Elric is a particularly talented alchemist who through an accident years back lost his younger brother Alphonse and one of his legs. Sacrificing one of his arms as well, he used alchemy to bind his brother''s soul to a suit of armor. This lead to the beginning of their journey to restore their bodies, in search for the legendary Philosopher''s Stone. Note: Episodes 11, 12 and 37 were adapted from the light novel "Fullmetal Alchemist: The Land of Sand."', '/uploads/images/s_121.jpg', 'Alchemy,Philosophy,Magic,Tragedy,Male Protagonist,Military,Conspiracy,Coming of Age', 'https://anilist.co/anime/121'),
('命运石之门 负荷领域的既视感', 'もののけ姫', '剧场版', 'Studio Ghibli', '1997-01-01', '1', '8.5', 'A calm village residing in the mountains comes under attack from a demon-possessed boar one day. Ashitaka, a young man and prince of the tribe, engages the creature in an attempt to save his village. During the battle, the boar bites him on the arm, leaving it blackened and cursed. Following his village''s traditions, Ashitaka is exiled and becomes a wanderer, looking for a solution to the curse before it engulfs him. Iron Town is a fortress under the leadership of Lady Eboshi. Through the clearing of the surrounding forests, Iron Town produces large amounts of Ironsand, used for gunpowder and other machinery. However, because of the forests destruction, nearby animal clans seek revenge led by a human girl of the Wolf clan called San. When Ashitaka comes to Iron Town, he discovers the area consumed in battle. Horrified, he attempts to create peace and befriend the Wolf Clan. However, after the forest''s eradication and the ongoing war between Human and Beast, will the Spirit of the Forest be forgiving and accept Ashitaka''s request to expel his curse? [Written by MAL Rewrite]', '/uploads/images/s_164.jpg', 'Environmental,Mythology,Animals,Philosophy,War,Eco-Horror,Gods,Rural', 'https://anilist.co/anime/164'),
('千与千寻', '千と千尋の神隠し', '剧场版', 'Studio Ghibli', '2001-01-01', '1', '8.6', 'On the way to their new home, 10-year-old Chihiro Ogino''s family stumbles upon a deserted theme park. Intrigued, the family investigates the park, though unbeknownst to them, it is secretly inhabited by spirits who sleep by day and appear at night. When Chihiro''s mother and father eat food from a restaurant in the street, angry spirits turn them into pigs. Furthermore, a wide sea has appeared between the spirit world and the human one, trapping Chihiro, the sole human, in a land of spirits. Luckily for her though, a mysterious boy named Haku appears, claiming to know her from the past. Under his instructions, Chihiro secures a job in the bathhouse where Haku works. With only her courage and some new found friends to aid her, Chihiro embarks on a journey to turn her parents back to their original forms and return home.', '/uploads/images/s_199.jpg', 'Female Protagonist,Youkai,Coming of Age,Curses,Magic,Shapeshifting,Mythology,Work', 'https://anilist.co/anime/199'),
('混沌武士', 'サムライチャンプルー', 'TV', 'Manglobe', '2004-01-01', '26', '8.4', 'Let''s break it down. Mugen''s a reckless sword-slinger with a style that''s more b-boy than Shaolin. He''s got a nasty streak that makes people want to stick a knife in his throat. Then there''s Jin, a deadbeat ronin who speaks softly but carries a big blade. He runs game old-school style, but he can make your blood spray with the quickness. When these roughnecks bring the ruckus, it ain''t good for anybody, especially them. Enter Fuu, the ditzy waitress who springs her new friends from a deadly jam. All she wants in return is help solving a riddle from her past. She and the boys are tracking the scent, but there''s 99 ways to die between them and the sunflower samurai. (Source: Funimation)', '/uploads/images/s_205.png', 'Travel,Swordplay,Samurai,Rural,Assassins,Historical,Martial Arts,Orphan', 'https://anilist.co/anime/205'),
('妖精的旋律', 'エルフェンリート', 'TV', 'ARMS', '2004-01-01', '13', '6.8', 'The Diclonius, a mutated homosapien that is said to be selected by God and will eventually become the destruction of mankind, possess two horns on their heads and have a "sixth sense" which gives them telekinetic abilities. Due to this dangerous power, they have been captured and isolated in laboratories by the government. Lucy, a young and psychotic Diclonius, manages to break free of her confines and brutally murders most of the guards in the laboratory where she is being held, only to be shot in the head as she makes her escape. She survives, falling off a cliff into the ocean and manages to drift along to a beach where two teenagers, Kouta and Yuka, discover her. Having lost her memories, she was named after the only thing that she can now say, "Nyuu," and the two allow her to stay at Kouta''s home. However, it appears that the psychotic side of Lucy is not dead just yet... (Source: ANN - Revised)', '/uploads/images/s_226.jpg', 'Gore,Fugitive,Super Power,Amnesia,Monster Girl,Tragedy,Dissociative Identities,Urban Fantasy', 'https://anilist.co/anime/226'),
('死神', 'BLEACH', 'TV', 'Studio Pierrot', '2004-01-01', '366', '7.9', 'Ichigo Kurosaki is a rather normal high school student apart from the fact he has the ability to see ghosts. This ability never impacted his life in a major way until the day he encounters the Shinigami Kuchiki Rukia, who saves him and his family''s lives from a Hollow, a corrupt spirit that devours human souls. Wounded during the fight against the Hollow, Rukia chooses the only option available to defeat the monster and passes her Shinigami powers to Ichigo. Now forced to act as a substitute until Rukia recovers, Ichigo hunts down the Hollows that plague his town.', '/uploads/images/s_269.jpg', 'Swordplay,Shounen,Super Power,Afterlife,Ghost,Male Protagonist,Exorcism,Urban Fantasy', 'https://anilist.co/anime/269'),
('玲音', 'serial experiments lain', 'TV', 'Triangle Staff', '1998-01-01', '13', '8.0', 'We''re all connected... There is the world around us, a world of people, tactile sensation, and culture. There is the wired world, inside the computer, of images, personalities, virtual experiences, and a culture all of its own. The day after a classmate commits suicide, Lain, a 14-year-old girl, discovers how closely the two worlds are linked when she receives an e-mail from the dead girl: I just abandoned my body. I still live here... Has the line between the real world and the wired world begun to blur? (Source: Geneon Entertainment)', '/uploads/images/s_339.jpg', 'Denpa,Virtual World,Philosophy,Dissociative Identities,Augmented Reality,Female Protagonist,Memory Manipulation,Artificial Intelligence', 'https://anilist.co/anime/339'),
('哈尔的移动城堡', 'ハウルの動く城', '剧场版', 'Studio Ghibli', '2004-01-01', '1', '8.5', 'Sophie, a quiet girl working in a hat shop, finds her life thrown into turmoil when she is literally swept off her feet by a handsome but mysterious wizard named Howl. The vain and vengeful Witch of the Waste, jealous of their friendship, puts a spell on Sophie. In a life-changing adventure, Sophie climbs aboard Howl''s magnificent flying castle and enters a magical world on a quest to break the spell. (Source: Disney)', '/uploads/images/s_431.jpg', 'Magic,Female Protagonist,Steampunk,Witch,Elderly Protagonist,Found Family,War,Shapeshifting', 'https://anilist.co/anime/431'),
('龙猫', 'となりのトトロ', '剧场版', 'Studio Ghibli', '1988-01-01', '1', '8.1', 'Follow the adventures of Satsuki and her four-year-old sister Mei when they move into a new home in the countryside. To their delight they discover that their new neighbor is a mysterious forest spirit called Totoro who can be seen only through the eyes of a child. Totoro introduces them to extraordinary characters, including a cat that doubles as a bus, takes them on a journey through the wonders of nature. (Source: Disney)', '/uploads/images/s_523.jpg', 'Family Life,Primarily Child Cast,Rural,Youkai,Wilderness,Female Protagonist,Urban Fantasy,Kids', 'https://anilist.co/anime/523'),
('龙珠Z 神与神', 'ドラゴンボールZ', 'TV', 'Toei Animation', '1989-01-01', '291', '8.0', 'Goku is back with his new son, Gohan, but just when things are getting settled down, the adventures continue. Whether he is facing enemies such as Freeza, Cell, or Boo, Goku is proven to be an elite of his own and discovers his race, Saiyan. He meets many new people, gaining allies as well as enemies, as he still finds time to raise a family and be the happy-go-lucky Saiyan he is. (Source: Anime News Network)', '/uploads/images/s_813.jpg', 'Shounen,Super Power,Martial Arts,Henshin,Male Protagonist,Cultivation,Aliens,Space', 'https://anilist.co/anime/813'),
('樱兰高校男公关部', '桜蘭高校ホスト部', 'TV', 'bones', '2006-01-01', '26', '8.1', 'Fujioka Haruhi wins a scholarship to attend Ouran Academy, a school reserved for only the most rich and prestigious. Despite what other students may think of her, she cares little for physical appearances or the fact that she is a commoner. Unfortunately for Haruhi, her high school days take a sudden turn when she stumbles upon the Host Club, an elite club filled with super rich and beautiful boys who use their specific traits and charms to entertain young ladies. Even worse, Haruhi accidentally breaks an 8-million yen vase in the club. Since she is unable to repay her debt with money, Haruhi finds herself with no choice but to work for the Host Club, becoming a male host herself.', '/uploads/images/s_853.jpg', 'School Club,Shoujo,Crossdressing,Parody,Surreal Comedy,School,Male Harem,Female Protagonist', 'https://anilist.co/anime/853'),
('新剧场版 银魂 -吉原大炎上-', '銀魂', 'TV', 'Sunrise', '2006-01-01', '201', '8.5', 'Life isn''t easy in feudal Japan... especially since the aliens landed and conquered everything! Oh sure, the new health care is great, but the public ban on the use of swords has left a lot of defeated samurai with a difficult decision to make concerning their future career paths! This is especially true if, as in the case of Gintoki Sakata, they''re not particularly inclined towards holding a day job, which is why Gintoki''s opted for the freelance route, taking any job that''s offered to him as long as the financial remuneration sounds right. Unfortunately, in a brave new world filled with stray bug-eyed monsters, upwardly mobile Yakuza and overly ambitious E.T. entrepreneurs, those jobs usually don''t pay as well as they should for the pain, suffering and indignities endured! (Source: Sentai Filmworks)', '/uploads/images/s_918.jpg', 'Parody,Ensemble Cast,Samurai,Found Family,Slapstick,Meta,Male Protagonist,Surreal Comedy', 'https://anilist.co/anime/918'),
('死亡笔记', 'DEATH NOTE', 'TV', 'MADHOUSE', '2006-01-01', '37', '8.4', 'Light Yagami is a genius high school student who is about to learn about life through a book of death. When a bored shinigami, a God of Death, named Ryuk drops a black notepad called a Death Note, Light receives power over life and death with the stroke of a pen. Determined to use this dark gift for the best, Light sets out to rid the world of evil… namely, the people he believes to be evil. Should anyone hold such power? The consequences of Light’s actions will set the world ablaze. (Source: VIZ Media)', '/uploads/images/s_1535.jpg', 'Crime,Detective,Anti-Hero,Male Protagonist,Fugitive,Police,Philosophy,Primarily Adult Cast', 'https://anilist.co/anime/1535'),
('Code Geass 反叛的鲁路修R2', 'コードギアス 反逆のルルーシュ', 'TV', 'Sunrise', '2006-01-01', '25', '8.5', 'On August 10th of the year 2010 the Holy Empire of Britannia began a campaign of conquest, its sights set on Japan. Operations were completed in one month thanks to Britannia''s deployment of new mobile humanoid armor vehicles dubbed Knightmare Frames. Japan''s rights and identity were stripped away, the once proud nation now referred to as Area 11. Its citizens, Elevens, are forced to scratch out a living while the Britannian aristocracy lives comfortably within their settlements. Pockets of resistance appear throughout Area 11, working towards independence for Japan. Lelouch, an exiled Imperial Prince of Britannia posing as a student, finds himself in the heart of the ongoing conflict for the island nation. Through a chance meeting with a mysterious girl named C.C., Lelouch gains his Geass, the power of the king. Now endowed with absolute dominance over any person, Lelouch may finally realize his goal of bringing down Britannia from within! (Source: Bandai Entertainment)', '/uploads/images/s_1575.jpg', 'Anti-Hero,War,Military,Politics,Class Struggle,Revenge,Super Power,Conspiracy', 'https://anilist.co/anime/1575'),
('火影忍者疾风传', 'NARUTO -ナルト- 疾風伝', 'TV', 'Studio Pierrot', '2007-01-01', '500', '8.2', 'Naruto: Shippuuden is the continuation of the original animated TV series Naruto. The story revolves around an older and slightly more matured Uzumaki Naruto and his quest to save his friend Uchiha Sasuke from the grips of the snake-like Shinobi, Orochimaru. After 2 and a half years Naruto finally returns to his village of Konoha, and sets about putting his ambitions to work, though it will not be easy, as he has amassed a few (more dangerous) enemies, in the likes of the shinobi organization; Akatsuki. (Source: Anime News Network)', '/uploads/images/s_1735.jpg', 'Ninja,Shounen,Criminal Organization,Male Protagonist,Super Power,Revenge,Tragedy,Orphan', 'https://anilist.co/anime/1735'),
('天元突破 红莲螺岩', '天元突破グレンラガン', 'TV', 'Gainax', '2007-01-01', '27', '8.5', 'In a far away future, mankind lives underground in huge caves, unknowing of a world above with a sky and stars. In the small village of Jiha, Simon, a shy boy who works as a digger discovers a strange glowing object during excavation. The enterprising Kamina, a young man with a pair of rakish sunglasses and the passion of a firey sun, befriends Simon and forms a small band of brothers, the Gurren Brigade, to escape the village and break through the ceiling of the cave to reach the surface, which few believe exist. The village elder won''t hear of such foolishness and punishes the Brigade. However, when disaster strikes from the world above and the entire village is in jeopardy, it''s up to Simon, Kamina, a girl with a big gun named Yoko, and the small yet sturdy robot, Lagann, to save the day. The new friends journey to the world above and find that the surface is a harsh battlefield, and it''s up to them to fight back against the rampaging Beastmen to turn the tide in the humans'' favor! Pierce the heavens, Gurren Lagann!', '/uploads/images/s_2001.jpg', 'Super Robot,Coming of Age,Found Family,Male Protagonist,Post-Apocalyptic,Dystopian,Space Opera,Philosophy', 'https://anilist.co/anime/2001'),
('CLANNAD', 'ＣＬＡＮＮＡＤ -クラナド-', 'TV', 'Animation Do', '2007-01-01', '23', '7.7', 'Tomoya is a bitter, third year high school student. His mother passed away, causing his father to resort to alcohol and gambling. Tomoya is distant with his father and has become a delinquent in the years since his mother''s death. Walking to school, he meets Nagisa Furukawa who is a year older but is repeating the grade due to illness. She is alone, as most of her friends have moved on. The two begin hanging out, and as time goes by, Tomoya finds his life shifting in a new direction. (Source: Sentai Filmworks)', '/uploads/images/s_2167.jpg', 'Coming of Age,School,Ensemble Cast,Family Life,Urban Fantasy,Male Protagonist,Heterosexual,Primarily Teen Cast', 'https://anilist.co/anime/2167'),
('Code Geass 反叛的鲁路修R2', 'コードギアス 反逆のルルーシュ R2', 'TV', 'Sunrise', '2008-01-01', '25', '8.7', 'A year has passed since "The Black Rebellion" and the remaining Black Knights have vanished into the shadows, their leader and figurehead, Zero, executed by the Britannian Empire. Area 11 is once more squirming under the Emperor''s oppressive heel as the Britannian armies concentrate their attacks on the European front. But for the Britannians living in Area 11, life is back to normal. On one such normal day, a Britannian student, skipping his classes in the Ashford Academy, sneaks out to gamble on his chess play. But unknown to this young man, several forces are eying him from the shadows, for soon, he will experience a shocking encounter with his own obscured past, and the masked rebel mastermind Zero will return.', '/uploads/images/s_2904.jpg', 'Anti-Hero,War,Military,Class Struggle,Revenge,Politics,Philosophy,Super Power', 'https://anilist.co/anime/2904'),
('噬魂师', 'ソウルイーター', 'TV', 'bones', '2008-01-01', '51', '7.7', 'Set in the Shinigami technical school for weapon meisters, the series revolves around 3 groups of each a weapon meister and a human weapon. Trying to make the latter a "Death Scythe" which is the highest title for a weapon and thus fit for use by the Shinigami, they must collect the souls of 99 evil humans and 1 witch. Maka & Soul Eater, Black Star & Tsubaki, and Death the Kid with Patty and Liz Thompson are the characters Soul Eater revolves around. Besides taking the time to gather souls, these students of Shibusen defend Death City from some of the most powerful of creatures while still attending school and trying to become stronger.', '/uploads/images/s_3588.jpg', 'Super Power,Ensemble Cast,Shounen,Magic,School,Female Protagonist,Witch,Henshin', 'https://anilist.co/anime/3588'),
('龙与虎', 'とらドラ！', 'TV', 'J.C.STAFF', '2008-01-01', '25', '7.8', 'Ryuuji Takasu is a gentle high school student with a love for housework; but in contrast to his kind nature, he has an intimidating face that often gets him labeled as a delinquent. On the other hand is Taiga Aisaka, a small, doll-like student, who is anything but a cute and fragile girl. Equipped with a wooden katana and feisty personality, Taiga is known throughout the school as the "Palmtop Tiger." One day, an embarrassing mistake causes the two students to cross paths. Ryuuji discovers that Taiga actually has a sweet side: she has a crush on the popular vice president, Yuusaku Kitamura, who happens to be his best friend. But things only get crazier when Ryuuji reveals that he has a crush on Minori Kushieda—Taiga''s best friend! Toradora! is a romantic comedy that follows this odd duo as they embark on a quest to help each other with their respective crushes, forming an unlikely alliance in the process.', '/uploads/images/s_4224.jpg', 'Tsundere,Love Triangle,Primarily Teen Cast,Male Protagonist,School,Heterosexual,Unrequited Love,Female Protagonist', 'https://anilist.co/anime/4224'),
('黑执事 -寄宿学校篇-', '黒執事', 'TV', 'A-1 Pictures', '2008-01-01', '24', '7.3', 'In Victorian-era Europe, a young boy loses everything he once held near and dear to a vicious plot. In his moment of death, he strikes a deal with a demon: his soul, in exchange for revenge. Ciel Phantomhive is now the head of the Phantomhive corporation, handling all business affairs as well as the underground work for the Queen of England. His new partner is a demon butler, Sebastian Michaelis, whose powers as a butler is only surpassed by his strength as a demon. The story follows the two along with their other servants, as they work to unravel the plot behind Ciel''s parents'' murder, and the horrendous tragedies that befell Ciel in the month directly after.', '/uploads/images/s_4898.jpg', 'Butler,Crime,Tragedy,Demons,Revenge,Historical,Anti-Hero,Detective', 'https://anilist.co/anime/4898'),
('化物语', '化物語', 'TV', 'Shaft', '2009-01-01', '15', '8.2', 'First season of the Monogatari Series, part 1/6. Contains the arcs Hitagi Crab, Mayoi Snail, Suruga Monkey, Nadeko Snake, and Tsubasa Cat from the Bakemonogatari light novels. Thanks to Meme Oshino, Koyomi Araragi, a high school student, is able to remain a human after coming across a female vampire... However, since the incident, Koyomi seems to meet girls who have an apparition-related issue. Hitagi Senjougahara doesn’t weigh anything, Suruga Kanbaru’s right arm becomes like that of a monkey’s, and a young girl, Mayoi, cannot find her way home no matter how many times she tries. Koyomi, a Mr. Nice Guy, ends up helping each and every girl solve her problem with the help of Meme Oshino. (Source: Aniplex) Note: Only the first 12 episodes were broadcast on television; the remaining three episodes were distributed on the anime''s website between November 3, 2009, and June 25, 2010.', '/uploads/images/s_5081.jpg', 'Youkai,Ensemble Cast,Urban Fantasy,Surreal Comedy,Male Protagonist,Philosophy,Kuudere,Coming of Age', 'https://anilist.co/anime/5081'),
('钢之炼金术师 FULLMETAL ALCHEMIST', '鋼の錬金術師 FULLMETAL ALCHEMIST', 'TV', 'bones', '2009-01-01', '64', '9.0', '"In order for something to be obtained, something of equal value must be lost." Alchemy is bound by this Law of Equivalent Exchange—something the young brothers Edward and Alphonse Elric only realize after attempting human transmutation: the one forbidden act of alchemy. They pay a terrible price for their transgression—Edward loses his left leg, Alphonse his physical body. It is only by the desperate sacrifice of Edward''s right arm that he is able to affix Alphonse''s soul to a suit of armor. Devastated and alone, it is the hope that they would both eventually return to their original bodies that gives Edward the inspiration to obtain metal limbs called "automail" and become a state alchemist, the Fullmetal Alchemist. Three years of searching later, the brothers seek the Philosopher''s Stone, a mythical relic that allows an alchemist to overcome the Law of Equivalent Exchange. Even with military allies Colonel Roy Mustang, Lieutenant Riza Hawkeye, and Lieutenant Colonel Maes Hughes on their side, the brothers find themselves caught up in a nationwide conspiracy that leads them not only to the true nature of the elusive Philosopher''s Stone, but their country''s murky history as well. In between finding a serial killer and racing against time, Edward and Alphonse must ask themselves if what they are doing will make them human again... or take away their humanity. (Source: MAL Rewrite)', '/uploads/images/s_5114.jpg', 'Alchemy,Conspiracy,Military,War,Tragedy,Shounen,Politics,Male Protagonist', 'https://anilist.co/anime/5114'),
('轻音少女', 'けいおん!', 'TV', 'Kyoto Animation', '2009-01-01', '13', '7.8', 'Hirasawa Yui, a young, carefree girl entering high school, has her imagination instantly captured when she sees a poster advertising the ‘Light Music Club’. Being the carefree girl that she is, she quickly signs up. However, Yui has a problem, she is unable to play an instrument. When Yui goes to the clubroom to explain, she''s greeted by the other members: Ritsu, Mio and Tsumugi. Although disheartened at Yui’s lack of musical know-how, they still try to convince her to stay to prevent the club’s disbandment. After playing Yui a short piece which re-ignites her imagination, they succeed in keeping their new member and guitarist. Along with the tasks of school and homework, Yui begins to learn the guitar with the help of the other band members, experiencing many mishaps along the way. However, with the school-festival drawing near and Yui getting stuck with her practice, will the Light Music Club be ready in time for their debut? (Source: MAL Rewrite)', '/uploads/images/s_5680.png', 'Cute Girls Doing Cute Things,School Club,Band,Primarily Female Cast,Female Protagonist,School,Primarily Teen Cast,Iyashikei', 'https://anilist.co/anime/5680'),
('天使的心跳', 'Angel Beats!', 'TV', 'P.A.WORKS', '2010-01-01', '13', '7.7', 'Otonashi wakes up in the afterlife to find out he has no memories of his life before death. Desperate to survive in a war that could yield another unfortunate fate, he joins the SSS in the battle against Angel, whose very mission is to destroy all inhabitants of this afterlife. As Otonashi struggles to recover his memory and learn more about this world, he finds that not all is as it had seemed. (Source: Funimation)', '/uploads/images/s_6547.jpg', 'Afterlife,Tragedy,School,Amnesia,Primarily Teen Cast,Kuudere,Coming of Age,Memory Manipulation', 'https://anilist.co/anime/6547'),
('妖精的尾巴 欢迎来到 Fairy Hills!!', 'FAIRY TAIL', 'TV', 'Satelight', '2009-01-01', '175', '7.2', 'Across the Fiore kingdom, wizards join guilds and make their pay by filling magical needs—but one guild has a reputation as the roughest, rowdiest, most dangerous of all: Fairy Tail! When four young Fairy Tail members unite, their bond is forged by a power found in neither muscle nor magic and grows stronger with every mission. Whatever you do, don''t mess with these friends or you''ll get a taste of Natsu''s flaming fist or Gray''s ice hammer, suffer a painful blow from one of Lucy''s celestial spirits or catch the edge of Erza''s mighty blade! Whether they''re stopping demons from devastating the world or wrestling in the mess hall, this mystical team manages to inflict as much damage to their rivals as they do to the surrounding area! (Source: Funimation)', '/uploads/images/s_6702.jpg', 'Magic,Shounen,Fairy Tale,Found Family,Ensemble Cast,Male Protagonist,Female Protagonist,Dragons', 'https://anilist.co/anime/6702'),
('无头骑士异闻录', 'デュラララ!!', 'TV', 'Brain''s Base', '2010-01-01', '24', '7.9', 'In Tokyo''s downtown district of Ikebukuro, amidst many strange rumors and warnings of anonymous gangs and dangerous occupants, one urban legend stands out above the rest—the existence of a headless "Black Rider" who is said to be seen driving a jet-black motorcycle through the city streets. Ryuugamine Mikado has always longed for the excitement of the city life, and an invitation from a childhood friend convinces him to move to Tokyo. Witnessing the Black Rider on his first day in the city, his wishes already seem to have been granted. But as supernatural events begin to occur, ordinary citizens like himself, along with Ikebukuro''s most colorful inhabitants, are mixed up in the commotion breaking out in their city. (Source: MAL Rewrite)', '/uploads/images/s_6746.png', 'Urban Fantasy,Gangs,Urban,Ensemble Cast,Dullahan,Delinquents,Achronological Order,Crime', 'https://anilist.co/anime/6746'),
('会长是女仆大人', '会長はメイド様!', 'TV', 'J.C.STAFF', '2010-01-01', '26', '7.8', 'Being the first female student council president isn''t easy, especially when your school just transitioned from an all boys high school to a co-ed one. Aptly nicknamed "Demon President" by the boys for her strict disciplinary style, Misaki Ayuzawa is not afraid to use her mastery of Aikido techniques to cast judgment onto the hordes of misbehaving boys and defend the girls at Seika High School. Yet even the perfect Ayuzawa has an embarrassing secret—she works part-time as a maid at a maid café to help her struggling family pay the bills. She has managed to keep her job hidden from her fellow students and maintained her flawless image as a stellar student until one day, Takumi Usui, the most popular boy in school, walks into the maid café. He could destroy her reputation with her secret... or he could twist the student council president around his little finger and use her secret as an opportunity to get closer to her. (Source: MAL Rewrite)', '/uploads/images/s_7054.png', 'Shoujo,Female Protagonist,School,Maids,Work,Tsundere,Unrequited Love,Urban', 'https://anilist.co/anime/7054'),
('学园默示录 HIGHSCHOOL OF THE DEAD', '学園黙示録HIGHSCHOOL OF THE DEAD', 'TV', 'MADHOUSE', '2010-01-01', '12', '6.7', 'The lockers are splattered with blood, the student bodies are piling up and that''s not mystery meat they''re eating in the cafeteria… it''s the faculty! And that''s just the start of the worst day of school ever when a nightmarish virus is unleashed, turning humans into flesh eating zombies and converting Fujimi High School into a literal hell on Earth. Now it''s a crash course in survival, and the only test or skill that matters is the ability to keep moving, breathing and fighting. Because if nerds, jocks and the surviving staff can''t find a way to work together to escape this carnal house of education, they''re all going to end up on the menu. And that''s assuming there''s anyplace safe left to escape to. (Source: Sentai Filmworks)', '/uploads/images/s_8074.png', 'Zombie,Survival,Pandemic,Gore,Conspiracy,Primarily Teen Cast,Urban Fantasy,Ensemble Cast', 'https://anilist.co/anime/8074'),
('命运石之门 负荷领域的既视感', 'シュタインズ・ゲート', 'TV', 'WHITE FOX', '2011-01-01', '24', '8.9', 'Self-proclaimed mad scientist Okabe Rintarou lives in a small room in Akihabara, where he invents "future gadgets" with fellow lab members Shiina Mayuri, his air-headed childhood friend, and Hashida Itaru, an otaku hacker. The three pass the time by tinkering with their latest creation, a "Phone Microwave" that can be controlled through text messages. The lab members soon face a string of mysterious incidents that lead to a game-changing discovery: the Phone Microwave can send emails to the past and thus alter history. Adapted from the critically acclaimed visual novel by 5pb. and Nitroplus, Steins;Gate takes Okabe to the depths of scientific theory and human despair as he faces the dire consequences of changing the past.', '/uploads/images/s_9253.jpg', 'Time Manipulation,Alternate Universe,Time Loop,Conspiracy,Tragedy,Memory Manipulation,Denpa,Male Protagonist', 'https://anilist.co/anime/9253'),
('魔法纪录 魔法少女小圆外传 2nd SEASON -觉醒前夜-', '魔法少女まどか☆マギカ', 'TV', 'Shaft', '2011-01-01', '12', '8.3', 'One night, 14-year-old Madoka Kaname has a terrible nightmare - against the backdrop of a devastated city, she witnesses a girl fight a losing battle against a dreadful being lingering above, while a cat-like magical creature tells Madoka the only way to change such tragic outcome is for her to make a contract with him and become a magical girl. The next day, the teen''s dream seemingly becomes reality as the girl she saw in her dream - Homura - arrives at Mitakihara Middle School as a transfer student, mysteriously warning Madoka to stay just the way she is; but when later on she and her best friend Sayaka encounter the same cat-like magical creature from her dream - who introduces himself as Kyubey - the pair discovers that magical girls are real, and what''s more, they can choose to become one. All they must do is sign a contract with Kyubey and agree to take on the duty to fight abstract beings called ''witches'' that spread despair to the human world, and in return, each one of them will be granted any single wish they desire. However, as Homura''s omen suggests, there might be far more to becoming a magical girl than Madoka and Sayaka realize... Notes: - Due to the 2011 Tōhoku earthquake and tsunami, the broadcasts of episodes 11 and 12 were delayed and were later aired as a double feature on April 21, 2011.', '/uploads/images/s_9756.jpg', 'Magic,Tragedy,Female Protagonist,Cosmic Horror,Witch,Primarily Female Cast,Time Manipulation,Time Loop', 'https://anilist.co/anime/9756'),
('青之驱魔师', '青の祓魔師', 'TV', 'A-1 Pictures', '2011-01-01', '25', '7.3', 'This world consists of two dimensions joined as one, like a mirror. The first is the world in which the humans live, Assiah. The other is the world of demons, Gehenna. Ordinarily, travel between the two, and indeed any kind of contact between the two, is impossible. However the demons can pass over into this world by possessing anything that exist within it. Satan the god of demons, but there''s one thing that he doesn''t have, and that''s a substance in the human world that is powerful enough to contain him!! For that purpose he created Rin, his son from a human woman, but will his son agree to his plans? Or will he become something else...? An exorcist?', '/uploads/images/s_9919.jpg', 'Demons,Shounen,Super Power,Youkai,Male Protagonist,Twins,Exorcism,Religion', 'https://anilist.co/anime/9919'),
('我们仍未知道那天所看见的花的名字。', 'あの日見た花の名前を僕達はまだ知らない。', 'TV', 'A-1 Pictures', '2011-01-01', '11', '8.0', 'Jinta Yadomi and his group of childhood friends have become estranged after a tragic accident split them apart. Now in their high school years, a sudden surprise forces each of them to confront their guilt over what happened that day and come to terms with the ghosts of their past. (Source: NIS America)', '/uploads/images/s_9989.jpg', 'Coming of Age,Tragedy,Ghost,Rehabilitation,Hikikomori,Love Triangle,Male Protagonist,Rural', 'https://anilist.co/anime/9989'),
('Fate/Zero 命运长夜前传', 'Fate/Zero', 'TV', 'ufotable', '2011-01-01', '13', '8.1', 'With the promise of granting any wish, the omnipotent Holy Grail triggered three wars in the past, each too cruel and fierce to leave a victor. In spite of that, the wealthy Einzbern family is confident that the Fourth Holy Grail War will be different; namely, with a vessel of the Holy Grail now in their grasp. Solely for this reason, the much hated "Magus Killer" Kiritsugu Emiya is hired by the Einzberns, with marriage to their only daughter Irisviel as binding contract. Kiritsugu now stands at the center of a cutthroat game of survival, facing off against six other participants, each armed with an ancient familiar, and fueled by unique desires and ideals. Accompanied by his own familiar, Saber, the notorious mercenary soon finds his greatest opponent in Kirei Kotomine, a priest who seeks salvation from the emptiness within himself in pursuit of Kiritsugu. Based on the light novel written by Gen Urobuchi, Fate/Zero depicts the events of the Fourth Holy Grail War—10 years prior to Fate/stay night. Witness a battle royale in which no one is guaranteed to survive. (Source: MAL Rewrite) Note: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', '/uploads/images/s_10087.jpg', 'Battle Royale,Magic,Mythology,Tragedy,Ensemble Cast,Anti-Hero,Death Game,Urban Fantasy', 'https://anilist.co/anime/10087'),
('未来日记', '未来日記', 'TV', 'Asread', '2011-01-01', '26', '6.9', 'This psychological thriller, based on the manga written and illustrated by Sakae Esuno, is about Yuki, a loner who''s not very good with people. He prefers to write a diary on his cell phone and talk to his imaginary friend, Deus Ex Machina – The God of Time and Space. However, Yuki soon learns that Deus is more than a figment of his imagination when he makes Yuki participate in a battle royale with eleven others. The contestants are given special diaries that can predict the future, each diary possessing unique features that give it both advantages and disadvantages. Within the next 90 days, the contestants must try to survive until there is only one left standing. The winner will become the new God of Time and Space. (Source: FUNimation)', '/uploads/images/s_10620.jpg', 'Battle Royale,Death Game,Survival,Yandere,Tragedy,Alternate Universe,Psychosexual,Body Horror', 'https://anilist.co/anime/10620'),
('猎人', 'HUNTER×HUNTER (2011)', 'TV', 'MADHOUSE', '2011-01-01', '148', '8.9', 'A new adaption of the manga of the same name by Togashi Yoshihiro. A Hunter is one who travels the world doing all sorts of dangerous tasks. From capturing criminals to searching deep within uncharted lands for any lost treasures. Gon is a young boy whose father disappeared long ago, being a Hunter. He believes if he could also follow his father''s path, he could one day reunite with him. After becoming 12, Gon leaves his home and takes on the task of entering the Hunter exam, notorious for its low success rate and high probability of death to become an official Hunter. He befriends the revenge-driven Kurapika, the doctor-to-be Leorio and the rebellious ex-assassin Killua in the exam, with their friendship prevailing throughout the many trials and threats they come upon taking on the dangerous career of a Hunter.', '/uploads/images/s_11061.jpg', 'Shounen,Super Power,Male Protagonist,Tragedy,Travel,Ensemble Cast,Martial Arts,Philosophy', 'https://anilist.co/anime/11061'),
('替身', 'アナザー', 'TV', 'P.A.WORKS', '2012-01-01', '12', '7.1', 'When Kouichi Sakakibara transfers to a new school, he senses a frightening atmosphere in his new class, a secret none of them will talk about. At the center is the beautiful Mei Misaki. Kouichi is immediately drawn to her mysterious aura, but he begins to realize that no one else in the class is aware of her presence. Soon after his arrival, what is known as the Calamity begins, and it claims the lives of many students. (Source: Sentai Filmworks)', '/uploads/images/s_11111.jpg', 'Tragedy,Primarily Teen Cast,School,Gore,Memory Manipulation,Survival,Urban Fantasy,Curses', 'https://anilist.co/anime/11111'),
('恶魔高校DXD DX OAD', 'ハイスクールD×D', 'TV', 'TNK', '2012-01-01', '12', '6.9', 'Issei Hyodo is your average perverted high school student whose one wish in life is to have his own harem, but he''s got to be one of the unluckiest guys around. He goes on his first date with a girl only to get brutally attacked and killed when it turns out the girl is really a vicious fallen angel. To top it all off, he''s later reincarnated as a devil by his gorgeous senpai who tells him that she is also a devil and now his master! One thing''s for sure, his peaceful days are over. In a battle between devils and angels, who will win? (Source: FUNimation)', '/uploads/images/s_11617.jpg', 'Nudity,Female Harem,Urban Fantasy,Primarily Female Cast,Male Protagonist,Heterosexual,Shounen,Magic', 'https://anilist.co/anime/11617'),
('刀剑神域外传 Gun Gale Online 第二季', 'ソードアート・オンライン', 'TV', 'A-1 Pictures', '2012-01-01', '25', '7.0', 'In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now... (Source: Crunchyroll)', '/uploads/images/s_11757.jpg', 'Virtual World,Death Game,Video Games,Male Protagonist,Swordplay,Heterosexual,Primarily Teen Cast,Isekai', 'https://anilist.co/anime/11757'),
('黑子的篮球', '黒子のバスケ', 'TV', 'Production I.G', '2012-01-01', '25', '7.8', 'Teikou Junior High School''s basketball team is crowned champion three years in a row thanks to five outstanding players who, with their breathtaking and unique skills, leave opponents in despair and fans in admiration. However, after graduating, these teammates, known as "The Generation of Miracles", go their separate ways and now consider each other as rivals. At Seirin High School, two newly recruited freshmen prove that they are not ordinary basketball players: Taiga Kagami, a promising player returning from the US, and Tetsuya Kuroko, a seemingly ordinary student whose lack of presence allows him to move around unnoticed. Although Kuroko is neither athletic nor able to score any points, he was a member of Teikou''s basketball team, where he played as the "Phantom Sixth Man," who easily passed the ball and assisted his teammates. Kuroko no Basket follows the journey of Seirin''s players as they attempt to become the best Japanese high school team by winning the Interhigh Championship. To reach their goal, they have to cross pathways with several powerful teams, some of which have one of the five players with godlike abilities, whom Kuroko and Taiga make a pact to defeat. (Source: MAL Rewrite)', '/uploads/images/s_11771.jpg', 'Basketball,Male Protagonist,Shounen,Primarily Male Cast,School Club,Tomboy,Ensemble Cast,Primarily Teen Cast', 'https://anilist.co/anime/11771'),
('冰菓', '氷菓', 'TV', 'Kyoto Animation', '2012-01-01', '22', '7.9', 'Energy-conservative high school student Houtarou Oreki ends up with more than he bargained for when he signs up for the Classic Literature Club at his sister''s behest—especially when he realizes how deep-rooted the club''s history really is. Begrudgingly, Oreki is dragged into an investigation concerning the 45-year-old mystery that surrounds the club room. Accompanied by his fellow club members, the knowledgeable Satoshi Fukube, the stern but benign Mayaka Ibara, and the ever-curious Eru Chitanda, Oreki must combat deadlines and lack of information with resourcefulness and hidden talent, in order to not only find the truth buried beneath the dust of works created years before them, but of other side cases as well. Based on the award-winning Koten-bu light novel series, and directed by Yasuhiro Takemoto of Suzumiya Haruhi no Shoushitsu, Hyouka shows that normal life can be full of small mysteries, be it family history, a student film, or even the withered flowers that make up a ghost story. (Source: MAL Rewrite)', '/uploads/images/s_12189.jpg', 'School Club,Detective,School,Primarily Teen Cast,Male Protagonist,Coming of Age,Episodic,Classic Literature', 'https://anilist.co/anime/12189'),
('心理测量者 新编集版', 'PSYCHO-PASS サイコパス', 'TV', 'Production I.G', '2012-01-01', '22', '8.1', 'Justice, and the enforcement of it, has changed. In the 22nd century, Japan enforces the Sibyl System, an objective means of determining the threat level of each citizen by examining their mental state for signs of criminal intent, known as their Psycho-Pass. Inspectors uphold the law by subjugating, often with lethal force, anyone harboring the slightest ill-will; alongside them are Enforcers, jaded Inspectors that have become latent criminals, granted relative freedom in exchange for carrying out the Inspectors'' dirty work. Into this world steps Akane Tsunemori, a young woman with an honest desire to uphold justice. However, as she works alongside veteran Enforcer Shinya Kougami, she soon learns that the Sibyl System''s judgments are not as perfect as her fellow Inspectors assume. With everything she has known turned on its head, Akane wrestles with the question of what justice truly is, and whether it can be upheld through the use of a system that may already be corrupt. (Source: MAL Rewrite) Note: In the Summer 2014 season, Psycho-Pass was rebroadcast and re-edited to fit into an hour time-slot, ending up in 11 one-hour episodes. This edit included added scenes at the beginning and middle of the episodes, as well as fixing and improving animation.', '/uploads/images/s_13601.jpg', 'Detective,Police,Dystopian,Crime,Cyberpunk,Philosophy,Primarily Adult Cast,Urban', 'https://anilist.co/anime/13601'),
('樱花庄的宠物女孩', 'さくら荘のペットな彼女', 'TV', 'J.C.STAFF', '2012-01-01', '24', '7.8', 'The first time he saw her, it was love at first sight. Unfortunately for Sorata Kanda, "she" was a cat named Hikari and his school''s rules forbid keeping pets in the regular dorms. As a result, Sorata is banished to the infamous Sakura Hall alongside other troublesome and unusual students like Jin, overzealous playboy, Ryuunosuke, the reclusive hermit, and Mashiro, a brilliant artist who''s so unfocused and clueless about the real world that dorm supervisor Ms. Sengoku assigns Sorata the task of taking care of her along with his ever-growing collection of stray cats! (Source: Sentai Filmworks)', '/uploads/images/s_13759.jpg', 'Kuudere,School,Heterosexual,Coming of Age,Found Family,Ensemble Cast,Love Triangle,Work', 'https://anilist.co/anime/13759'),
('邻座的怪同学', 'となりの怪物くん', 'TV', 'Brain''s Base', '2012-01-01', '13', '7.2', 'Standoffish, reclusive Shizuku Mizutani cares far more about earning stellar grades than cultivating friendships. But her opinions on friendship and relationships begin to change when she meets habitual truant Haru Yoshida, who happens to have a rather fearsome reputation. Like Shizuku, Haru’s reputation has made it difficult to make friends. And yet through their budding friendship and stirrings of attraction the unlikely pair learns to understand one another, the world around them, and the tenor of their own emotions. (Source: Sentai Filmworks)', '/uploads/images/s_14227.jpg', 'School,Shoujo,Female Protagonist,Primarily Teen Cast,Kuudere,Heterosexual,Tsundere,Love Triangle', 'https://anilist.co/anime/14227'),
('JOJO的奇妙冒险 黄金之风', 'ジョジョの奇妙な冒険 (TV)', 'TV', 'david production', '2012-01-01', '26', '7.7', 'Beginning its tale in 19th century England, young aristocrat Jonathan Joestar finds himself locked in bitter rivalry with Dio Brando, a low-born boy who Jonathan''s father took under his wing after the death of Dio''s father. Discontent with his station in life, Dio''s fathomless lust to reign over all eventually leads him to seek the supernatural powers of an ancient Aztec stone mask in the Joestar''s possession—an artifact that will forever change the destiny of Dio and Jonathan for generations to come. Fifty years later, in 1938 New York City, Jonathan''s grandson Joseph Joestar must take up his grandfather''s mission and master the abilities necessary to destroy the stone mask and its immensely powerful creators who threaten humanity''s very existence, the Pillar Men. (Source: Anime News Network)', '/uploads/images/s_14719.jpg', 'Male Protagonist,Super Power,Primarily Male Cast,Urban Fantasy,Vampire,Time Skip,Shounen,Cultivation', 'https://anilist.co/anime/14719'),
('中二病也要谈恋爱！', '中二病でも恋がしたい!', 'TV', 'Kyoto Animation', '2012-01-01', '12', '7.6', 'Everybody has had that stage in their life where they have thought themselves to be special, different from the masses of ordinary humans. They might go as far as seeing themselves capable of wielding mystical powers, or maybe even believe themselves to have descended from a fantasy realm. This "disease" is known as "chuunibyou" and is often the source of some of the most embarrassing moments of a person''s life. For Yuuta Togashi, the scars that his chuunibyou has left behind are still fresh. Having posed as the "Dark Flame Master" during his middle school years, he looks back at those times with extreme embarrassment, so much so that he decides to attend a high school far away where nobody will recognize him. Putting his dark history behind him, he longs to live a normal high school life. Unfortunately, he hasn''t escaped his past yet: enter Rikka Takanashi, Yuuta''s new classmate and self-declared vessel of the "Wicked Eye." As this eccentric young girl crashes into Yuuta''s life, his dream of an ordinary, chuunibyou-free life quickly crumbles away. In this hilarious and heartwarming story of a boy who just wants to leave his embarrassing memories behind, the delusions of old are far from a thing of the past. (Source: MAL Rewrite)', '/uploads/images/s_14741.jpg', 'Chuunibyou,Coming of Age,Primarily Teen Cast,School,School Club,Heterosexual,Slapstick,Disability', 'https://anilist.co/anime/14741'),
('我的青春恋爱物语果然有问题 完', 'やはり俺の青春ラブコメはまちがっている。', 'TV', 'Brain''s Base', '2013-01-01', '13', '7.8', 'This romantic comedy revolves around an antisocial high school student named Hikigaya Hachiman with a distorted view on life and no friends or girlfriend. When he sees his classmates talking excitedly about living their adolescent lives, he mutters: "They''re a bunch of liars." When he is asked about his future dreams, he responds: "Not working." A teacher gets Hachiman to join the ''Volunteer Service'' club, which happens to have the school''s prettiest girl: Yukinoshita Yukino. (Source: Anime News Network)', '/uploads/images/s_14813.jpg', 'School,School Club,Primarily Teen Cast,Male Protagonist,Philosophy,Anti-Hero,Heterosexual,Love Triangle', 'https://anilist.co/anime/14813'),
('打工吧！魔王大人', 'はたらく魔王さま!', 'TV', 'WHITE FOX', '2013-01-01', '13', '7.5', 'Devil King Sadao is only one step away from conquering the world when he is beaten by Hero Emilia and forced to drift to the other world: modern-day Tokyo. As "conquering the world" are the only skills the Devil King possesses—and are obviously unnecessary in his new situation—he must work as a freeter to pay for his living expenses!', '/uploads/images/s_15809.jpg', 'Reverse Isekai,Demons,Work,Male Protagonist,Restaurant,Urban,Magic,Urban Fantasy', 'https://anilist.co/anime/15809'),
('进击的巨人', '進撃の巨人', 'TV', 'WIT STUDIO', '2013-01-01', '25', '8.5', 'Several hundred years ago, humans were nearly exterminated by titans. Titans are typically several stories tall, seem to have no intelligence, devour human beings and, worst of all, seem to do it for the pleasure rather than as a food source. A small percentage of humanity survived by walling themselves in a city protected by extremely high walls, even taller than the biggest of titans. Flash forward to the present and the city has not seen a titan in over 100 years. Teenage boy Eren and his foster sister Mikasa witness something horrific as the city walls are destroyed by a colossal titan that appears out of thin air. As the smaller titans flood the city, the two kids watch in horror as their mother is eaten alive. Eren vows that he will murder every single titan and take revenge for all of mankind. (Source: MangaHelpers)', '/uploads/images/s_16498.jpg', 'Kaiju,Revenge,Tragedy,Military,Henshin,Primarily Teen Cast,Male Protagonist,Post-Apocalyptic', 'https://anilist.co/anime/16498'),
('青春纪行', 'ゴールデンタイム', 'TV', 'J.C.STAFF', '2013-01-01', '24', '7.5', 'Due to a tragic accident, Banri Tada is struck with amnesia, dissolving the memories of his hometown and past. However, after befriending Mitsuo Yanagisawa, he decides to move on and begin a new life at law school in Tokyo. But just as he is beginning to adjust to his college life, the beautiful Kouko Kaga dramatically barges into Banri''s life, and their chance meeting marks the beginning of an unforgettable year. After having a glimpse of college life, Banri learns that he is in a new place and a new world—a place where he can be reborn, to have new friends, fall in love, makes mistakes and grow. And as he begins to discover who he was, the path he has chosen leads him towards a blindingly bright life that he will never want to forget.', '/uploads/images/s_17895.jpg', 'Amnesia,Memory Manipulation,College,Male Protagonist,Love Triangle,Dissociative Identities,Primarily Adult Cast,Tragedy', 'https://anilist.co/anime/17895'),
('境界的彼方', '境界の彼方', 'TV', 'Kyoto Animation', '2013-01-01', '12', '7.4', 'They should never have met. They shouldn''t even exist. But when they come together, the entire world will change. The last surviving member of her clan, Mirai Kuriyama is cursed with the terrifying ability to control and manipulate blood, a power so heretical that she is shunned even by those with the ability to understand her "gift". Akihito Kanbara is only half human, but while the monstrous other half of his lineage seems to have doomed him to a life alone, it has also given him near invulnerability in the form of rapid healing. Alone, their futures seem bleak, but when a chance encounter brings them together, it becomes clear that they share more than just an unexpected bond. Together they share a destiny and a mission that only the two of them together may be strong enough to survive. (Source: Sentai Filmworks)', '/uploads/images/s_18153.png', 'Super Power,Urban Fantasy,Demons,School,Primarily Teen Cast,Heterosexual,Female Protagonist,Male Protagonist', 'https://anilist.co/anime/18153'),
('杀动画', 'キルラキル', 'TV', 'TRIGGER', '2013-01-01', '24', '7.9', 'After the murder of her father, Ryuuko Matoi has been wandering the land in search of his killer. Following her only lead—the missing half of his invention, the Scissor Blade—she arrives at the prestigious Honnouji Academy, a high school unlike any other. The academy is ruled by the imposing and cold-hearted student council president Satsuki Kiryuuin alongside her powerful underlings, the Elite Four. In the school''s brutally competitive hierarchy, Satsuki bestows upon those at the top special clothes called "Goku Uniforms," which grant the wearer unique superhuman abilities.', '/uploads/images/s_18679.jpg', 'Henshin,Female Protagonist,Revenge,Nudity,Surreal Comedy,Class Struggle,Parody,Dystopian', 'https://anilist.co/anime/18679'),
('伪恋', 'ニセコイ', 'TV', 'Shaft', '2014-01-01', '20', '7.3', 'As a child, Raku Ichijo made a secret promise with his childhood sweetheart, keeping a pendant as a memento while his love took the key. He dreams of one day meeting his past love, but years later, reality smashes his hopes when Chitoge Kirisaki accidentally knees him in the face... Though Raku''s a normal high schooler, his family heads the notorious yakuza gang the Shuei-Gumi faction! And he''s dragged into family affairs when he''s forced into a relationship with Chitoge, the daughter of a rival gang''s boss! Despite their constant spats, the two somehow fool everyone with their false relationship. Raku then discovers that Chitoge has a mysterious key from her past, which she can''t remember... Plus, two other girls appear with keys as well—Kosaki Onodera and Marika Tachibana! Caught in the midst of this love maelstrom, even more complications arise for Raku when his class decides on Romeo and Juliet as the class''s play for the school festival. Can the two false lovebirds pull off the impossible and make the play a success? (Source: VIZ Media)', '/uploads/images/s_18897.jpg', 'Love Triangle,Female Harem,Male Protagonist,Tsundere,School,Slapstick,Primarily Female Cast,Heterosexual', 'https://anilist.co/anime/18897'),
('Fate/stay night 无限剑制', 'Fate/stay night [Unlimited Blade Works]', 'TV', 'ufotable', '2014-01-01', '13', '8.0', 'Fuyuki City - a city surrounded by the sea and mountains becomes the setting for an ancient ritual. Seven masters are given control of heroic spirits in order to realize the mythical Holy Grail, which is said to grant its owner any wish. These heroic spirits or servants represent legendary heroes of various classes: "Saber," "Lancer," "Archer," "Rider," "Caster," "Assassin," and "Berserker." Each master will enter into a contract with their chosen servant and battle the others to the death until only one pair remains... This is the "Holy Grail War." The young and capable mage, Rin Tohsaka, prepares for her long-awaited Fifth Holy Grail War to begin... With her servant Archer, Rin enters the Holy Grail War as the sole heir to the prestigious Tohsaka family after her father''s death. But when Shirou Emiya, a boy from Rin''s school, unwittingly becomes a Master and is fatally wounded in battle, she has no choice but to save him. With Shirou and his servant Saber, Rin sets out to strike down the conspiracies surrounding the Holy Grail War. Will the Holy Grail bless Rin and Shirou''s path toward victory or will they be cursed with defeat? (Source: Aniplex of America) Notes: - Includes Prologue. - The first, second and last episodes aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', '/uploads/images/s_19603.jpg', 'Magic,Battle Royale,Death Game,Super Power,Urban Fantasy,Mythology,Spearplay,Swordplay', 'https://anilist.co/anime/19603'),
('游戏人生', 'ノーゲーム・ノーライフ', 'TV', 'MADHOUSE', '2014-01-01', '12', '7.7', 'Bored with life and considering the real world to be just a “crappy game,” savvy sibling shut-ins Sora and Shiro have withdrawn into their own fantasy world filled with video games. However, one day they find themselves summoned to another world by a boy who calls himself “God,” their abilities are about to be put to the ultimate test! Now not only their fates — but the fate of all of humanity — will be decided by a series of games that may just be the hardest these super-geniuses have ever faced! (Source: Sentai Filmworks, edited)', '/uploads/images/s_19815.jpg', 'Isekai,Gambling,Alternate Universe,Video Games,Hikikomori,Magic,Male Protagonist,Primarily Female Cast', 'https://anilist.co/anime/19815'),
('野良神', 'ノラガミ', 'TV', 'bones', '2014-01-01', '12', '7.8', 'Minor god Yato is down on his luck. Fed up with his slacker lifestyle, his partner abruptly quits. He has no money, no worshippers, and no shrine to call home. But just when things are starting to seem hopeless, a bus accident forces him to cross paths with Hiyori Iki, a sweet and perky high school girl. After the accident, Hiyori''s soul has a bad habit of slipping out of her body, and after enlisting Yato''s help to get her back to normal, she begins to fall into the world of spirits and gods. But Hiyori''s not the only one who''s keeping tabs on Yato. A god from Yato''s past is back, and he''s not interested in a friendly reunion. (Source: Funimation)', '/uploads/images/s_20447.jpg', 'Gods,Youkai,Urban Fantasy,Female Protagonist,Shounen,Mythology,Urban,Male Protagonist', 'https://anilist.co/anime/20447'),
('魔法科高校的劣等生 第三季', '魔法科高校の劣等生', 'TV', 'MADHOUSE', '2014-01-01', '26', '7.0', 'Magic is a product of neither legends nor fairy tales, but instead has become a technology of reality since a time unknown to people. Supernatural power became a technology systematized through magic, while magic became a technical skill. A "Supernatural Power User" became a "Magic Technician." Magic Technicians (in short, Magicians) are nurtured through Magic High Schools and Universities. This is a story about: Tatsuya, a defective elder brother low achiever. Miyuki, a perfect, flawless younger sister high achiever. After both siblings entered a Magic High School, The stage of daily turbulence was unveiled—.', '/uploads/images/s_20458.jpg', 'Magic,School,Male Protagonist,Military,Terrorism,Incest,Guns,Primarily Teen Cast', 'https://anilist.co/anime/20458'),
('排球少年!!', 'ハイキュー!!', 'TV', 'Production I.G', '2014-01-01', '25', '8.4', 'Inspired after watching a volleyball ace nicknamed "Little Giant" in action, small-statured Shouyou Hinata revives the volleyball club at his middle school. The newly-formed team even makes it to a tournament; however, their first match turns out to be their last when they are brutally squashed by the "King of the Court," Tobio Kageyama. Hinata vows to surpass Kageyama, and so after graduating from middle school, he joins Karasuno High School''s volleyball team—only to find that his sworn rival, Kageyama, is now his teammate. Thanks to his short height, Hinata struggles to find his role on the team, even with his superior jumping power. Surprisingly, Kageyama has his own problems that only Hinata can help with, and learning to work together appears to be the only way for the team to be successful. Based on Haruichi Furudate''s popular shounen manga of the same name, Haikyuu!! is an exhilarating and emotional sports comedy following two determined athletes as they attempt to patch a heated rivalry in order to make their high school volleyball team the best in Japan. [Written by MAL Rewrite]', '/uploads/images/s_20464.jpg', 'Volleyball,School Club,Male Protagonist,Primarily Male Cast,Shounen,Ensemble Cast,Primarily Teen Cast,School', 'https://anilist.co/anime/20464'),
('JOJO的奇妙冒险 星尘斗士 埃及篇', 'ジョジョの奇妙な冒険 スターダストクルセイダース', 'TV', 'david production', '2014-01-01', '24', '7.9', 'In a Japanese jail sits 17-year-old Jotaro Kujo: punk, fighter, delinquent...and possessed by a force beyond his control! Around the world, evil spirits are awakening: "Stands," monstrous invisible creatures which give their bearers incredible powers. To save his mother''s life, Jotaro must tame his dark forces and travel around the world to Cairo, Egypt, where a hundred-year-old vampire thirsts for the blood of his family. But the road is long, and an army of evil Stand Users waits to kill JoJo and his friends... (Source: VIZ Media)', '/uploads/images/s_20474.jpg', 'Super Power,Foreign,Primarily Male Cast,Travel,Shounen,Male Protagonist,Urban Fantasy,Episodic', 'https://anilist.co/anime/20474'),
('刀剑神域 第二季', 'ソードアート・オンライン II', 'TV', 'A-1 Pictures', '2014-01-01', '24', '6.6', 'One year after the SAO incident, Kirito is approached by Seijiro Kikuoka from Japan''s Ministry of Internal Affairs and Communications Department "VR Division" with a rather peculiar request. That was an investigation on the "Death Gun" incident that occurred in the gun and steel filled VRMMO called Gun Gale Online (GGO). "Players who are shot by a mysterious avatar with a jet black gun lose their lives even in the real world..." Failing to turn down Kikuoka''s bizarre request, Kirito logs in to GGO even though he is not completely convinced that the virtual world could physically affect the real world. Kirito wanders in an unfamiliar world in order to gain any clues about the "Death Gun." Then, a female sniper named Sinon who owns a gigantic "Hecate II" rifle extends Kirito a helping hand. With Sinon''s help, Kirito decides to enter the "Bullet of Bullets," a large tournament to choose the most powerful gunner within the realm of GGO, in hopes to become the target of the "Death Gun" and make direct contact with the mysterious avatar. (Source: Crunchyroll)', '/uploads/images/s_20594.jpg', 'Virtual World,Video Games,Male Protagonist,Battle Royale,Primarily Female Cast,Guns,Isekai,Primarily Teen Cast', 'https://anilist.co/anime/20594'),
('东京喰种', '東京喰種 トーキョーグール', 'TV', 'Studio Pierrot', '2014-01-01', '12', '7.6', 'The suspense horror/dark fantasy story is set in Tokyo, which is haunted by mysterious "ghouls" who are devouring humans. People are gripped by the fear of these ghouls whose identities are masked in mystery. An ordinary college student named Kaneki encounters Rize, a girl who is an avid reader like him, at the café he frequents. Little does he realize that his fate will change overnight. (Source: Anime News Network)', '/uploads/images/s_20605.jpg', 'Gore,Urban Fantasy,Tragedy,Survival,Body Horror,Human Experimentation,Male Protagonist,Torture', 'https://anilist.co/anime/20605'),
('斩·赤红之瞳！', 'アカメが斬る！', 'TV', 'WHITE FOX', '2014-01-01', '24', '7.3', 'In a land where corruption rules and a ruthless Prime Minister has turned the puppet Emperor''s armies of soldiers, assassins and secret police against the people, only one force dares to stand against them: Night Raid, an elite team of relentless killers, each equipped with an Imperial Arm - legendary weapons with unique and incredible powers created in the distant past. Rescued from a fate worse than death by Night Raid, young Tatsumi is offered the chance to join their lethal ranks… but it''s a deadly choice, as few can master an Imperial Arm and even fewer survive when two Arms go against each other in combat. The battle is on, and only the strongest will make it out alive. (Source: Sentai Filmworks)', '/uploads/images/s_20613.jpg', 'Assassins,Politics,Tragedy,Shounen,Gore,Crime,Henshin,Swordplay', 'https://anilist.co/anime/20613'),
('寄生兽 生命的准则', '寄生獣 セイの格率', 'TV', 'MADHOUSE', '2014-01-01', '24', '8.1', 'They arrive in silence and darkness. They descend from the skies. They have a hunger for human flesh. They are everywhere. They are parasites, alien creatures who must invade–and take control of–a human host to survive. And once they have infected their victims, they can assume any deadly form they choose: monsters with giant teeth, winged demons, creatures with blades for hands. But most have chosen to conceal their lethal purpose behind ordinary human faces. So no one knows their secret–except an ordinary high school student. Shin is battling for control of his own body against an alien parasite, but can he find a way to warn humanity of the horrors to come? (Source: Del Rey)', '/uploads/images/s_20623.jpg', 'Body Horror,Shapeshifting,Survival,Philosophy,Male Protagonist,Seinen,Anthropomorphism,Aliens', 'https://anilist.co/anime/20623'),
('东京残响', '残響のテロル', 'TV', 'MAPPA', '2014-01-01', '11', '7.8', 'Painted in red, the word "VON" is all that is left behind after a terrorist attack on a nuclear facility in Japan. The government is shattered by their inability to act, and the police are left frantically searching for ways to crack down the perpetrators. The public are clueless—until, six months later, a strange video makes its way onto the internet. In it, two teenage boys who identify themselves only as "Sphinx" directly challenge the police, threatening to cause destruction and mayhem across Tokyo. Unable to stop the mass panic quickly spreading through the city and desperate for any leads in their investigation, the police struggle to act effectively against these terrorists, with Detective Kenjirou Shibazaki caught in the middle of it all. Zankyou no Terror tells the story of Nine and Twelve, the two boys behind the masked figures of Sphinx. They should not exist, yet they stand strong in a world of deception and secrets while they make the city fall around them, all in the hopes of burying their own tragic truth. (Source: MAL Rewrite)', '/uploads/images/s_20661.png', 'Terrorism,Anti-Hero,Detective,Tragedy,Crime,Revenge,Male Protagonist,Orphan', 'https://anilist.co/anime/20661'),
('四月是你的谎言', '四月は君の嘘', 'TV', 'A-1 Pictures', '2014-01-01', '22', '8.4', 'Piano prodigy Arima Kousei dominated the competition and all child musicians knew his name. But after his mother, who was also his instructor, passed away, he had a mental breakdown while performing at a recital. This resulted in him no longer being able to hear the sound of his piano playing. Two years later, Kousei hasn’t touched the piano and views the world without any flair or color. He was content at living out his life with his good friends Tsubaki and Watari until, one day, a girl changed everything. Miyazono Kaori is a pretty, free spirited violinist whose playing style reflects her personality. Kaori helps Kousei return to the music world and show that it should be free and mold breaking unlike the structured and rigid style Kousei was used to.', '/uploads/images/s_20665.jpg', 'Classical Music,Tragedy,Primarily Teen Cast,Coming of Age,Disability,Rehabilitation,Male Protagonist,Female Protagonist', 'https://anilist.co/anime/20665'),
('我的青春恋爱物语果然有问题。续', 'やはり俺の青春ラブコメはまちがっている。続', 'TV', 'feel.', '2015-01-01', '13', '8.1', 'The second season of Yahari Ore no Seishun Love Come wa Machigatteiru. Yahari Ore no Seishun Love Comedy wa Machigatteiru. Zoku picks up immediately after the events of the first season, continuing the adventures of the Volunteer Service Club—the dispassionate Hachiman Hikigaya, the cheerful Yui Yuigahama, and the competitive Yukino Yukinoshita—as it dedicates itself to helping any student with issues that they may face. With the rift among his own group widening, Hachiman begins to realize that his knack for quickly getting to the root of other people''s troubles is a double-edged sword: sometimes the best solution is not necessarily the most appropriate one. (Source: MAL Rewrite)', '/uploads/images/s_20698.png', 'School,Male Protagonist,School Club,Love Triangle,Coming of Age,Kuudere,Philosophy,Primarily Teen Cast', 'https://anilist.co/anime/20698'),
('暗杀教室', '暗殺教室', 'TV', 'Lerche', '2015-01-01', '22', '7.9', 'The students of class 3-E have a mission: kill their teacher before graduation. He has already destroyed the moon, and has promised to destroy the Earth if he can not be killed within a year. But how can this class of misfits kill a tentacled monster, capable of reaching Mach 20 speed, who may be the best teacher any of them have ever had?', '/uploads/images/s_20755.jpg', 'Assassins,School,Teacher,Primarily Teen Cast,Shounen,Ensemble Cast,Tentacles,Aliens', 'https://anilist.co/anime/20755'),
('七大罪 戒律的复活', '七つの大罪', 'TV', 'A-1 Pictures', '2014-01-01', '24', '7.3', 'When they were accused of trying to overthrow the monarchy, the feared warriors the Seven Deadly Sins were sent into exile. Princess Elizabeth discovers the truth - the Sins were framed by the king''s guard, the Holy Knights - too late to prevent them from assassinating her father and seizing the throne! Now the princess is on the run, seeking the Sins to help her reclaim the kingdom. But the first Sin she meets, Meliodas, is a little innkeeper with a talking pig. He doesn''t even have a real sword! Have the legends of the Sins'' strength been exaggerated? (Source: Anime News Network)', '/uploads/images/s_20789.jpg', 'Ensemble Cast,Shounen,Magic,Demons,Male Protagonist,Age Gap,Heterosexual,Spearplay', 'https://anilist.co/anime/20789'),
('JOJO的奇妙冒险 星尘斗士 埃及篇', 'ジョジョの奇妙な冒険 スターダストクルセイダース エジプト編', 'TV', 'david production', '2015-01-01', '24', '8.3', 'After 30 days of travel across the world, plagued with countless battles, Jotaro and his companions have finally arrived in Egypt! Now only the strongest "Stand" users remain to rebuff our heroes'' final march on Cairo: The Nine Egyptian Gods, Dio''s most zealous servants. Will the Joestar line fall to the monstrous vampire, or can Jotaro defeat Dio and save his mother''s life? (Source: Crunchyroll)', '/uploads/images/s_20799.jpg', 'Super Power,Primarily Male Cast,Male Protagonist,Travel,Shounen,Foreign,Ensemble Cast,Tragedy', 'https://anilist.co/anime/20799'),
('终结的炽天使', '終わりのセラフ', 'TV', 'WIT STUDIO', '2015-01-01', '12', '7.3', 'The story takes place in a world where an unknown virus has killed the entire human population except for children under 13. Those children were then enslaved by vampires. The manga centers on Yuichiro Hyakuya, a human who dreams of becoming strong enough to kill all vampires. (Source: Anime News Network)', '/uploads/images/s_20829.jpg', 'Vampire,Post-Apocalyptic,Urban Fantasy,Male Protagonist,Shounen,Military,Time Skip,War', 'https://anilist.co/anime/20829'),
('不死者之王', 'オーバーロード', 'TV', 'MADHOUSE', '2015-01-01', '13', '7.7', 'The story takes place in the year 2138 when virtual reality gaming is booming. Yggdrasil, a popular online game is quietly shut down one day. However, the protagonist Momonga decides to not log out. Momonga is then transformed into the image of a skeleton as "the most powerful wizard." The world continues to change, with non-player characters (NPCs) beginning to feel emotion. Having no parents, friends, or place in society, this ordinary young man Momonga then strives to take over the new world the game has become. (Source: Anime News Network)', '/uploads/images/s_20832.jpg', 'Isekai,Anti-Hero,Skeleton,Ensemble Cast,Virtual World,Male Protagonist,Medieval,Magic', 'https://anilist.co/anime/20832'),
('东京喰种√A', '東京喰種[トーキョーグール]√A', 'TV', 'Studio Pierrot', '2015-01-01', '12', '6.7', 'The second season of Tokyo Ghoul. The ghouls of Anteiku invaded the Aogiri''s site in order to rescue Ken Kaneki who is being tortured. Due to provocation, he unleashed greater power enough to defeat Yamori. To become stronger, he decided to join Aogiri and left Anteiku. Ghoul investigators also making their moves by collecting information about the eye-patched ghoul - Ken Kaneki. (Source: Anime News Network)', '/uploads/images/s_20850.jpg', 'Anti-Hero,Body Horror,Super Power,Gore,Military,Detective,Police,Urban Fantasy', 'https://anilist.co/anime/20850'),
('可塑性记忆', 'プラスティックメモリーズ', 'TV', 'Doga Kobo', '2015-01-01', '13', '7.7', 'This story takes place in a future not too far away when androids that look exactly like humans begin to spread across the world. The android production company SA Corp. produced Giftia, a new kind of android that has the most amount of emotion and human-like qualities out of any other model ever seen. However, due to problems in technology, the androids have a service life, and once they pass that, they... Well, it gets pretty bad. For this reason, SA Corp. creates a terminal service in order to retrieve Giftia that have gone past their service life. A new employee at the terminal service named Tsukasa Mizugaki forms a team with the Giftia Isla to retrieve the other androids, but... (Source: Anime News Network)', '/uploads/images/s_20872.jpg', 'Robots,Tragedy,Artificial Intelligence,Male Protagonist,Female Protagonist,Memory Manipulation,Kuudere,Urban', 'https://anilist.co/anime/20872'),
('在地下城寻求邂逅是否搞错了什么 第四季 新章 迷宫篇', 'ダンジョンに出会いを求めるのは間違っているだろうか', 'TV', 'J.C.STAFF', '2015-01-01', '13', '7.3', 'Some adventurers delve into the sprawling labyrinths beneath the city of Orario to find fame and fortune. Others come to test their skills against the legions of monsters lurking in the darkness below. However, Bell Cranel’s grandfather told him a different reason: it’s a great place to rescue (and subsequently meet) girls! Now that Bell’s a dungeon delver himself, the ladies he’s encountering aren’t the helpless damsels in distress he’d imagined, and one of them, the beautiful swordswoman Ais Wallenstein, keeps rescuing Bell instead. As embarrassing as that is, it’s nothing compared to what happens when goddesses get involved. Freya, Hephaistos, and Loki, with their powerful Familias, are intimidating enough, but there’s one goddess whose relationship with Bell is certain to spark trouble. (Source: Sentai Filmworks)', '/uploads/images/s_20920.jpg', 'Dungeon,Male Protagonist,Gods,Medieval,Magic,Ensemble Cast,Mythology,Primarily Female Cast', 'https://anilist.co/anime/20920'),
('食戟之灵', '食戟のソーマ', 'TV', 'J.C.STAFF', '2015-01-01', '24', '7.8', 'Ever since he was little, Souma Yukihira’s main goals have been to beat his father in a cooking contest and take over the family diner. That’s why, when his dad suddenly announces that he’s shutting the restaurant down and sending Souma to cooking school, Souma is shocked. However, Totsuki Academy is no ordinary cooking school. This elite institution is filled with culinary giants like Erina “God Tongue” Nakiri, who does her best to keep a lowly short-order like Souma from even making it inside the door. However, if the snobs can dish it out, Souma can serve it up, and when he learns that only a handful of the students manage to graduate every year, he swears that the only way he’ll leave is as number one! (Source: Sentai Filmworks)', '/uploads/images/s_20923.jpg', 'Food,Male Protagonist,Primarily Teen Cast,School,Shounen,Nudity,Tsundere,Educational', 'https://anilist.co/anime/20923'),
('死亡游行', 'デス・パレード', 'TV', 'MADHOUSE', '2015-01-01', '12', '8.0', 'When two people die at the same time, they’re sent to a place that’s neither heaven nor hell—a lavish bar between worlds where the stakes are high and the rules are simple: if you win you live again, if you die… you’re gone for good. Decim is the bartender charged with serving the souls who enter Quindecim. He may make a mean cocktail, but his true profession is to play the role of arbiter—a judge who determines whether or not a soul is worthy of reincarnation. To aid in his judgment, the bar’s patrons are forced to play simple games laced with sadistic twists designed to bring their true natures to light. To Decim, judgment has always been black and white—that is—until he meets a mysterious young woman whose fate seems impossible to decide. His indecision shakes the very foundation of the games and raises the biggest question of all: Who is fit to judge the dead? (Source: Funimation)', '/uploads/images/s_20931.jpg', 'Afterlife,Death Game,Philosophy,Tragedy,Amnesia,Memory Manipulation,Reincarnation,Bar', 'https://anilist.co/anime/20931'),
('声之形', '聲の形', '剧场版', 'Kyoto Animation', '2016-01-01', '1', '8.8', 'After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends. (Source: Eleven Arts)', '/uploads/images/s_20954.jpg', 'Disability,Bullying,Rehabilitation,Language Barrier,Coming of Age,Suicide,Male Protagonist,Tragedy', 'https://anilist.co/anime/20954'),
('进击的巨人 第二季', '進撃の巨人 Season２', 'TV', 'WIT STUDIO', '2017-01-01', '12', '8.5', 'Eren Jaeger swore to wipe out every last Titan, but in a battle for his life he wound up becoming the thing he hates most. With his new powers, he fights for humanity''s freedom facing the monsters that threaten his home. After a bittersweet victory against the Female Titan, Eren finds no time to rest—a horde of Titans is approaching Wall Rose and the battle for humanity continues! (Source: Funimation)', '/uploads/images/s_20958.jpg', 'Survival,Shapeshifting,Post-Apocalyptic,Tragedy,Espionage,Military,Primarily Teen Cast,Kaiju', 'https://anilist.co/anime/20958'),
('排球少年!! 第二季', 'ハイキュー!! セカンドシーズン', 'TV', 'Production I.G', '2015-01-01', '25', '8.6', 'Following their participation at the Inter-High, the Karasuno High School volleyball team attempts to refocus their efforts, aiming to conquer the Spring tournament instead. When they receive an invitation from long-standing rival Nekoma High, Karasuno agrees to take part in a large training camp alongside many notable volleyball teams in Tokyo and even some national level players. By playing with some of the toughest teams in Japan, they hope not only to sharpen their skills, but also come up with new attacks that would strengthen them. Moreover, Hinata and Kageyama attempt to devise a more powerful weapon, one that could possibly break the sturdiest of blocks. Facing what may be their last chance at victory before the senior players graduate, the members of Karasuno''s volleyball team must learn to settle their differences and train harder than ever if they hope to overcome formidable opponents old and new—including their archrival Aoba Jousai and its world-class setter Tooru Oikawa. [Written by MAL Rewrite]', '/uploads/images/s_20992.jpg', 'Volleyball,School Club,Ensemble Cast,Primarily Teen Cast,Primarily Male Cast,Shounen,Male Protagonist,Coming of Age', 'https://anilist.co/anime/20992'),
('夏洛特', 'Charlotte(シャーロット)', 'TV', 'P.A.WORKS', '2015-01-01', '13', '7.5', 'The story centers around the special abilities that occur among a small percentage of boys and girls in puberty. Yuu Otosaka uses his power without others knowing, and lives a fairly normal, average school life. Before him suddenly appears a girl, Nao Tomori. Due to his meeting with her, the fate of special power-users will be exposed. (Source: Anime News Network)', '/uploads/images/s_20997.jpg', 'Super Power,Time Manipulation,Tragedy,Urban Fantasy,Primarily Teen Cast,Male Protagonist,Urban,School Club', 'https://anilist.co/anime/20997'),
('ReLIFE 完结篇', 'ReLIFE', '网络动画', 'TMS Entertainment', '2016-01-01', '13', '7.8', 'The story follows Kaizaki Arata, a 27-year-old jobless man, who fails at every job interview he had after quitting his last company. His life changes after he met Yoake Ryou of the ReLife Research Institute, who offered him a drug that can change his appearance to 17-years-old and to become a subject in an experiment for one year. Thus, he begins his life as a high school student once more.', '/uploads/images/s_21049.jpg', 'Rehabilitation,Age Regression,School,Memory Manipulation,Male Protagonist,Heterosexual,Primarily Teen Cast,Coming of Age', 'https://anilist.co/anime/21049'),
('一拳超人', 'ワンパンマン', 'TV', 'MADHOUSE', '2015-01-01', '12', '8.3', 'Saitama has a rather peculiar hobby, being a superhero, but despite his heroic deeds and superhuman abilities, a shadow looms over his life. He''s become much too powerful, to the point that every opponent ends up defeated with a single punch. The lack of challenge has driven him into a state of apathy, as he watches his life pass by having lost all enthusiasm, at least until he''s unwillingly thrust in the role of being a mentor to the young and revenge-driven Genos.', '/uploads/images/s_21087.jpg', 'Superhero,Super Power,Parody,Male Protagonist,Satire,Surreal Comedy,Urban Fantasy,Urban', 'https://anilist.co/anime/21087'),
('野良神 ARAGOTO', 'ノラガミ ARAGOTO', 'TV', 'bones', '2015-01-01', '13', '8.0', 'The second season of Noragami. Life for minor god Yato isn''t getting any easier. He''s still broke, shrineless, and his partner-slash-sword-regalia has zero respect for him. Worse yet, Bishamon, one of the deadliest war gods, is after his life. Blaming him for the death of her past regalia, she won''t stop until she kills him. But there''s more to that story than she could ever realize. And as if that''s not bad enough, there''s someone working against her behind the scenes! Can Yato take on a god as powerful as Bishamon? Or will things take a more dangerous turn? Between all of this godly drama and even more dangerous battles, Yato still needs to figure out how to help Hiyori. But all options lead to losing her, and he''s not willing to make that choice – no matter what. Five yen doesn''t even begin to cover his trouble! (Source: Funimation)', '/uploads/images/s_21128.jpg', 'Gods,Mythology,Female Protagonist,Shounen,Urban Fantasy,Youkai,Found Family,Urban', 'https://anilist.co/anime/21128'),
('暗杀教室 第二季', '暗殺教室 第２期', 'TV', 'Lerche', '2016-01-01', '25', '8.3', 'The second season of Ansatsu Kyoushitsu. The students return as school is back in session for the second semester. Following their exploits on the island during summer vacation, Class 3-E continues to sharpen their blades with their sights set on their teacher, the slippery Koro-sensei. They have more to worry about than just their teacher, however, as enemy assassins, both old and new, are out for the increased bounty on the octopus'' head. Moreover, their rivals in Class A, as well as Kunugigaoka Junior High''s fearsome principal, stand to block Class E from achieving academic excellence. With all of these obstacles opposing them, the group must continue to work together in order to overcome their foes and accomplish their goal of successfully assassinating their teacher.', '/uploads/images/s_21170.jpg', 'Assassins,School,Teacher,Primarily Teen Cast,Coming of Age,Ensemble Cast,Tragedy,Super Power', 'https://anilist.co/anime/21170'),
('为美好的世界献上祝福！', 'この素晴らしい世界に祝福を！', 'TV', 'Studio DEEN', '2016-01-01', '10', '7.9', 'Kazuma Satou decides that today is the day to get out of the house for a bit. Since he dies, pointlessly, it''s clearly a bad choice. The goddess who greets him in the afterlife, however, offers him a chance to be reborn in a world not unlike that of a video game, and as a bonus she''ll even throw in a cool item or power! Can''t possibly be a bad choice, right? Except he arrives with no money at all, dead average skills, and his "bonus" isn''t useful at all--since he picked the goddess, Aqua, herself. How are the two of them supposed to defeat the evil Devil King and live happily ever after? Well, for them, it probably starts with day laboring rather than adventuring. And it''s only going to get more disappointing from there! (Source: Crunchyroll)', '/uploads/images/s_21202.jpg', 'Isekai,Satire,Parody,Primarily Female Cast,Male Protagonist,Ensemble Cast,Slapstick,Magic', 'https://anilist.co/anime/21202'),
('只有我不存在的城市', '僕だけがいない街', 'TV', 'A-1 Pictures', '2016-01-01', '12', '8.1', 'Satoru Fujinuma is a 29 year old manga artist struggling to make a name for himself following his debut. But, that was not the only thing in his life that Satoru was feeling frustrated about… He has a unique supernatural ability of being forced to prevent deaths and catastrophes by being sent back in time before the incident occurred, repeating time until the accident is prevented. One day, he gets involved in an accident that has him framed as a murderer. Desperate to save the victim, he sends himself back in time only to find himself as a grade-schooler one month before fellow classmate Kayo Hinazuki went missing. Satoru now embarks on a new quest: to save Kayo and solve the mystery behind her disappearance.', '/uploads/images/s_21234.jpg', 'Age Regression,Time Manipulation,Crime,Urban Fantasy,Tragedy,Time Skip,Male Protagonist,Primarily Child Cast', 'https://anilist.co/anime/21234'),
('文豪野犬 第二季', '文豪ストレイドッグス', 'TV', 'bones', '2016-01-01', '12', '7.7', 'Stalked by a beastly white tiger, Atsushi Nakajima has no idea that the menace lives inside him—a power that catches the attention of the Armed Detective Agency. Using inhuman abilities to combat crime, this team takes Atsushi under the wing of their most eccentric member, Dazai. Together, they tear through mafia-muddled mysteries while enemies keep an eye on the tiger’s lofty bounty. (Source: Funimation)', '/uploads/images/s_21311.jpg', 'Super Power,Crime,Detective,Mafia,Urban Fantasy,Male Protagonist,Classic Literature,Yakuza', 'https://anilist.co/anime/21311'),
('Re：从零开始的异世界生活 第三季 袭击篇', 'Re:ゼロから始める異世界生活', 'TV', 'WHITE FOX', '2016-01-01', '25', '8.1', 'In the story, Subaru Natsuki is an ordinary high school student who is lost in an alternate world, where he is rescued by a beautiful, silver-haired girl. He stays near her to return the favor, but the destiny she is burdened with is more than Subaru can imagine. Enemies attack one by one, and both of them are killed. He then finds out he has the power to rewind death, back to the time he first came to this world. But only he remembers what has happened since. (Source: Anime News Network) Notes: - The first episode aired with a runtime of ~50 minutes as opposed to the standard 25 minute long episode. - In the Winter 2020 season, Re:ZERO was rebroadcast and re-edited to fit into an hour time-slot. This edit included the first OVA and added slight modifications to certain scenes throughout. It also added an additional scene at the end of the final episode.', '/uploads/images/s_21355.jpg', 'Time Manipulation,Isekai,Time Loop,Tragedy,Male Protagonist,Alternate Universe,Curses,Witch', 'https://anilist.co/anime/21355'),
('JOJO的奇妙冒险 不灭钻石', 'ジョジョの奇妙な冒険 ダイヤモンドは砕けない', 'TV', 'david production', '2016-01-01', '39', '8.4', 'JoJo no Kimyou na Bouken: Diamond wa Kudakenai adapts the fourth part of the JoJo no Kimyou na Bouken manga series. It''s the year 1999, 11 years after Jotaro Kujo''s desperate fight against DIO in Egypt. Jotaro meets with Josuke Higashikata, the illegitimate son of his grandfather Joseph Joestar. He discovers that Josuke also has the same "Stand" power and that a new threat is surfacing in Morioh City. (Source: Anime News Network)', '/uploads/images/s_21450.jpg', 'Super Power,Urban Fantasy,Urban,Surreal Comedy,Shounen,Male Protagonist,Primarily Male Cast,Time Loop', 'https://anilist.co/anime/21450'),
('我的英雄学院', '僕のヒーローアカデミア', 'TV', 'bones', '2016-01-01', '13', '7.7', 'What would the world be like if 80 percent of the population manifested extraordinary superpowers called “Quirks” at age four? Heroes and villains would be battling it out everywhere! Becoming a hero would mean learning to use your power, but where would you go to study? U.A. High''s Hero Program of course! But what would you do if you were one of the 20 percent who were born Quirkless? Middle school student Izuku Midoriya wants to be a hero more than anything, but he hasn''t got an ounce of power in him. With no chance of ever getting into the prestigious U.A. High School for budding heroes, his life is looking more and more like a dead end. Then an encounter with All Might, the greatest hero of them all gives him a chance to change his destiny… (Source: VIZ Media)', '/uploads/images/s_21459.jpg', 'Super Power,Superhero,Shounen,Primarily Teen Cast,Male Protagonist,Crime,School,Rescue', 'https://anilist.co/anime/21459'),
('灵能百分百 第三季', 'モブサイコ100', 'TV', 'bones', '2016-01-01', '12', '8.4', 'The story revolves around "Mob," a boy who will explode if his emotional capacity reaches 100%. This boy with psychic powers earned his nickname "Mob" because he does not stand out among other people. He keeps his psychic powers bottled up so he can live normally, but if his emotional level reaches 100, something will overwhelm his entire body. (Source: Anime News Network)', '/uploads/images/s_21507.jpg', 'Super Power,Coming of Age,Urban Fantasy,Philosophy,Ghost,Surreal Comedy,Primarily Teen Cast,Male Protagonist', 'https://anilist.co/anime/21507'),
('食戟之灵 贰之皿', '食戟のソーマ 弍ノ皿', 'TV', 'J.C.STAFF', '2016-01-01', '13', '7.9', 'The second season of Shokugeki no Souma. At the Totsuki Culinary Academy, the first rule is survival of the fittest, and if you don''t have what it takes to become a master chef, you need to get out of the kitchen before you get burned. With the wheat of first-year students separated from the chaff, cocky former diner cook Yukihira Souma is one of the handful of kitchen whizzes still standing. As the next round of the Autumn Elections gets underway, can he survive a brutal bento boxing match with the chemistry-obsessed granddaughter of the Academy''s director? And which of the other contenders; Megumi, Ryou, Akira, Hisako, Takumi or sinister dark-horse Subaru; will advance to fight for the gold medal? (Source: Sentai Filmworks))', '/uploads/images/s_21518.jpg', 'Food,Male Protagonist,School,Shounen,Educational,Nudity,Tsundere,Tanned Skin', 'https://anilist.co/anime/21518'),
('你的名字。', '君の名は。', '剧场版', 'CoMix Wave', '2016-01-01', '1', '8.6', 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture. One day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another. Kimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance. (Source: MAL Rewrite)', '/uploads/images/s_21519.jpg', 'Body Swapping,Time Manipulation,Urban Fantasy,Coming of Age,Memory Manipulation,Environmental,Tragedy,Urban', 'https://anilist.co/anime/21519'),
('幼女战记', '幼女戦記', 'TV', 'NUT', '2017-01-01', '12', '7.8', 'The novel series centers on a young girl who fights on the frontlines in war. She has blonde hair, blue eyes, and nearly transparent white skin, and she flies through the air and mercilessly strikes down her opponents. Her name is Tanya Degurechaff, and she speaks with a young girl''s lisp and commands the army. Tanya used to be one of Japan''s elite office workers, but because of a wrathful god, was reborn as a little girl. Tanya prioritizes optimization and career advancement above all, and she will become the most dangerous entity among the Imperial Army''s sorcerers. (Source: Anime News Network)', '/uploads/images/s_21613.png', 'Military,War,Anti-Hero,Female Protagonist,Revenge,Reincarnation,Isekai,Gods', 'https://anilist.co/anime/21613'),
('排球少年!! 乌野高中 VS 白鸟泽学园高中', 'ハイキュー!! 烏野高校 VS 白鳥沢学園高校', 'TV', 'Production I.G', '2016-01-01', '10', '8.7', 'After the victory against Aoba Jousai High, Karasuno High School, once called “a fallen powerhouse, a crow that can’t fly,” has finally reached the climax of the heated Spring tournament. Now, to advance to nationals, the Karasuno team has to defeat the powerhouse Shiratorizawa Academy. Karasuno’s greatest hurdle is their adversary’s ace, Wakatoshi Ushijima, the number one player in the Miyagi Prefecture, and one of the country’s top three aces. Only the strongest team will make it to the national tournament. Since this match is the third-year players’ last chance to qualify for nationals, Karasuno has to use everything they learned during the training camp and prior matches to attain victory. Filled with restlessness and excitement, both teams are determined to come out on top in the third season of Haikyuu!!. [Written by MAL Rewrite]', '/uploads/images/s_21698.jpg', 'Volleyball,School Club,Shounen,Male Protagonist,Primarily Male Cast,Primarily Teen Cast,Ensemble Cast,School', 'https://anilist.co/anime/21698'),
('为美好的世界献上祝福！2', 'この素晴らしい世界に祝福を！2', 'TV', 'Studio DEEN', '2017-01-01', '10', '8.1', 'When Kazuma Satou died, he was given two choices: pass on to heaven or be revived in a fantasy world. After choosing the new world, the goddess Aqua tasked him with defeating the Demon King, and let him choose any weapon to aid him. Unfortunately, Kazuma chose to bring Aqua herself and has regretted the decision ever since then. Not only is he stuck with a useless deity turned party archpriest, the pair also has to make enough money for living expenses. To add to their problems, their group continued to grow as more problematic adventurers joined their ranks. Their token spellcaster, Megumin, is an explosion magic specialist who can only cast one spell once per day and refuses to learn anything else. There is also their stalwart crusader, Lalatina "Darkness" Dustiness Ford, a helpless masochist who makes Kazuma look pure in comparison. Kono Subarashii Sekai ni Shukufuku wo! 2 continues to follow Kazuma and the rest of his party through countless more adventures as they struggle to earn money and have to deal with one another''s problematic personalities. However, things rarely go as planned, and they are often sidetracked by their own idiotic tendencies.', '/uploads/images/s_21699.jpg', 'Isekai,Satire,Parody,Magic,Male Protagonist,Anti-Hero,Slapstick,Primarily Female Cast', 'https://anilist.co/anime/21699'),
('小林家的龙女仆S', '小林さんちのメイドラゴン', 'TV', 'Kyoto Animation', '2017-01-01', '13', '7.7', 'What happens when a drunken promise leads to living with a dragon? That’s Miss Kobayashi’s new reality when Tohru appears in her life. With a maid-slash-dragon in her home, she’s experiencing a whole new level of domestic bliss! But the dragons don’t stop there. On a mission to find Tohru appears Kanna, a little dragon with a big attitude. Before she knows it, Kobayashi’s got a house full of dragons—one serving tail and the other serving serious moe! Together, they live side by side with only the occasional disaster…well, maybe. But nothing beats coming home to the warm welcome of a dragon maid! (Source: Funimation)', '/uploads/images/s_21776.jpg', 'Found Family,Dragons,Anthropomorphism,Monster Girl,Family Life,Cute Girls Doing Cute Things,Female Protagonist,Primarily Female Cast', 'https://anilist.co/anime/21776'),
('紫罗兰永恒花园', 'ヴァイオレット・エヴァーガーデン', 'TV', 'Kyoto Animation', '2018-01-01', '13', '8.5', 'A certain point in time, in the continent of Telesis. The great war which divided the continent into North and South has ended after four years, and the people are welcoming a new generation. Violet Evergarden, a young girl formerly known as “the weapon”, has left the battlefield to start a new life at CH Postal Service. There, she is deeply moved by the work of “Auto Memories Dolls”, who carry people''s thoughts and convert them into words. Violet begins her journey as an Auto Memories Doll, and comes face to face with various people''s emotions and differing shapes of love. There are words Violet heard on the battlefield, which she cannot forget. These words were given to her by someone she holds dear, more than anyone else. She does not yet know their meaning but she searches to find it. (Source: Anime News Network)', '/uploads/images/s_21827.jpg', 'Rehabilitation,Writing,Tragedy,Female Protagonist,Coming of Age,Kuudere,War,Work', 'https://anilist.co/anime/21827'),
('我的英雄学院 第二季', '僕のヒーローアカデミア２', 'TV', 'bones', '2017-01-01', '25', '7.9', 'Taking off right after the last episode of the first season. The school is temporarily closed due to security. When U.A. restarts, it is announced that the highly anticipated School Sports Festival will soon be taking place. All classes: Hero, Support, General and Business will be participating. Tournaments all round will decide who is the top Hero in training. (Source: Anime News Network)', '/uploads/images/s_21856.jpg', 'Super Power,Superhero,Shounen,Primarily Teen Cast,School,Male Protagonist,Ensemble Cast,Urban Fantasy', 'https://anilist.co/anime/21856'),
('一拳超人 第二季', 'ワンパンマン 2', 'TV', 'J.C.STAFF', '2019-01-01', '12', '7.4', 'Saitama is a hero who only became a hero for fun. After three years of “special training,” he’s become so strong that he’s practically invincible. In fact, he’s too strong—even his mightiest opponents are taken out with a single punch. Now, the great seer Madame Shibabawa’s prediction about the Earth being doomed seems to be coming true as the frequency of monster incidents escalates. Alongside Genos, his faithful disciple, Saitama begins his official hero duties as a member of the Hero Association, while Garou, a man utterly fascinated by monsters, makes his appearance.', '/uploads/images/s_97668.jpg', 'Superhero,Urban,Super Power,Male Protagonist,Parody,Satire,Cyborg,Primarily Male Cast', 'https://anilist.co/anime/97668'),
('电影 黑色五叶草 魔法帝之剑', 'ブラッククローバー', 'TV', 'Studio Pierrot', '2017-01-01', '170', '7.9', 'In a world where magic is everything, Asta and Yuno are both found abandoned at a church on the same day. While Yuno is gifted with exceptional magical powers, Asta is the only one in this world without any. At the age of fifteen, both receive grimoires, magic books that amplify their holder’s magic. Asta’s is a rare Grimoire of Anti-Magic that negates and repels his opponent’s spells. Being opposite but good rivals, Yuno and Asta are ready for the hardest of challenges to achieve their common dream: to be the Wizard King. Giving up is never an option! (Source: Crunchyroll)', '/uploads/images/s_97940.jpg', 'Magic,Shounen,Found Family,Male Protagonist,Super Power,Ensemble Cast,Medieval,Revenge', 'https://anilist.co/anime/97940'),
('来自深渊 深沉灵魂的黎明', 'メイドインアビス', 'TV', 'Kinema Citrus', '2017-01-01', '13', '8.4', 'The "Abyss" is the last unexplored place in the world. Strange and wonderful creatures roam within, and it is full of precious relics that present humans can''t recreate. Those that dare to explore the depths are known as "Cave Raiders." An orphan girl named Riko lives on the rim. Her dream is to become a Cave Raider like her mother and solve the mysteries of the cave system. One day, Riko starts exploring the caves and discovers a robot who resembles a human boy. (Source: Anime News Network, edited) Note: The last episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', '/uploads/images/s_97986.jpg', 'Survival,Outdoor Activities,Primarily Child Cast,Environmental,Travel,Cosmic Horror,Body Horror,Curses', 'https://anilist.co/anime/97986'),
('狂赌之渊 双', '賭ケグルイ', 'TV', 'MAPPA', '2017-01-01', '12', '7.0', 'During daylight hours, an exclusive, elite private school prepares its illustrious students for careers in business, politics, and high society. But when darkness falls, the halls of this esteemed establishment transform into an underground gambling den where bright-eyed youngsters learn the timeless art of bluffing, backdoor dealings and social manipulation. In this school for the rich and elite, money is power, and the tyrant of the betting books rules with an iron fist. So when the beautiful Yumeko Jabami upsets the academy hierarchy with her voracious appetite for the thrill of the gamble, the entire student body mobilizes to send her house of cards tumbling down. (Source: Sentai Filmworks)', '/uploads/images/s_98314.jpg', 'Gambling,Female Protagonist,School,Primarily Female Cast,Masochism,Primarily Teen Cast,Ojou-sama,Poker', 'https://anilist.co/anime/98314'),
('不死者之王 II', 'オーバーロードⅡ', 'TV', 'MADHOUSE', '2018-01-01', '13', '7.6', 'The second season of Overlord. Continuing his quest to rule this new world, Ains begins to put the pieces in place for his conquest. But between a Lizard Man tribe uprising, and performing missions as adamantite adventurer Lord Momon, Ains has his work cut out for him! Thankfully he has his most loyal and willing subordinates to do his bidding. Nothing and no one can stop the supreme and mighty Overlord in his quest to rule all! (Source: Manga Entertainment)', '/uploads/images/s_98437.jpg', 'Isekai,Anti-Hero,Skeleton,Male Protagonist,Magic,Butler,Ensemble Cast,Super Power', 'https://anilist.co/anime/98437'),
('恶魔人 crybaby', 'DEVILMAN crybaby', '网络动画', 'Science SARU', '2018-01-01', '10', '7.6', 'New Devilman project marking Go Nagai''s 50th anniversary as a creator. The protagonist Akira Fudou learns from his best friend, Ryou Asuka, that an ancient race of demons has returned to take back the world from humans. Ryou tells Akira that the only way to defeat the demons is to incorporate their supernatural powers, and suggests that he unite with a demon himself. Akira succeeds in transforming into Devilman, who possesses both the powers of a demon and the soul of a human. The battle of Devilman and Akira Fudou begins. (Source: Netflix)', '/uploads/images/s_98460.jpg', 'Demons,Tragedy,Body Horror,Psychosexual,Gore,Urban Fantasy,Gods,Shapeshifting', 'https://anilist.co/anime/98460'),
('欢迎来到实力至上主义的教室 第二季', 'ようこそ実力至上主義の教室へ', 'TV', 'Lerche', '2017-01-01', '12', '7.6', 'Koudo Ikusei Senior High School is a leading school with state-of-the-art facilities. The students there have the freedom to wear any hairstyle and bring any personal effects they desire. Koudo Ikusei is like a utopia, but the truth is that only the most superior students receive favorable treatment. Kiyotaka Ayanokouji is a student of D-class, which is where the school dumps its "inferior" students in order to ridicule them. For a certain reason, Kiyotaka was careless on his entrance examination, and was put in D-class. After meeting Suzune Horikita and Kikyou Kushida, two other students in his class, Kiyotaka''s situation begins to change. (Source: Anime News Network, edited)', '/uploads/images/s_98659.jpg', 'School,Primarily Teen Cast,Ensemble Cast,Male Protagonist,Anti-Hero,Survival,Blackmail,Human Experimentation', 'https://anilist.co/anime/98659'),
('进击的巨人 第三季', '進撃の巨人 Season３', 'TV', 'WIT STUDIO', '2018-01-01', '12', '8.6', 'Eren and his companions in the 104th are assigned to the newly-formed Levi Squad, whose assignment is to keep Eren and Historia safe given Eren''s newly-discovered power and Historia''s knowledge and pedigree. Levi and Erwin have good reason to be concerned, because the priest of the Church that Hanji had hidden away was found tortured to death, making it clear that the Military Police are involved with the cover-up. Things get more harrowing when the MPs make a move on Erwin and the Levi Squad narrowly avoids capture. Eren is also having problems with his Titan transformation, and a deadly killer has been hired to secure Eren and Historia, one Levi knows all too well from his youth. (Source: Anime News Network)', '/uploads/images/s_99147.jpg', 'Conspiracy,Military,Tragedy,Shapeshifting,Politics,Memory Manipulation,Dystopian,Fugitive', 'https://anilist.co/anime/99147'),
('盾之勇者成名录', '盾の勇者の成り上がり', 'TV', 'Kinema Citrus', '2019-01-01', '25', '7.6', 'Naofumi Iwatani, an uncharismatic Otaku who spends his days on games and manga, suddenly finds himself summoned to a parallel universe! He discovers he is one of four heroes equipped with legendary weapons and tasked with saving the world from its prophesied destruction. As the Shield Hero, the weakest of the heroes, all is not as it seems. Naofumi is soon alone, penniless, and betrayed. With no one to turn to, and nowhere to run, he is left with only his shield. Now, Naofumi must rise to become the legendary Shield Hero and save the world! Note: - The first episode was pre-aired on December 27th, 2018. Regular broadcast began on January 9th, 2019. - The first episode aired with a runtime of ~47 minutes as opposed to the standard 24 minute long episode.', '/uploads/images/s_99263.jpg', 'Isekai,Male Protagonist,Conspiracy,Travel,Medieval,Revenge,Magic,Crime', 'https://anilist.co/anime/99263'),
('DARLING in the FRANXX', 'ダーリン・イン・ザ・フランキス', 'TV', 'TRIGGER', '2018-01-01', '24', '7.0', 'The distant future: Humanity established the mobile fort city, Plantation, upon the ruined wasteland. Within the city were pilot quarters, Mistilteinn, otherwise known as the “Birdcage.” That is where the children live... Their only mission in life was the fight. Their enemies are the mysterious giant organisms known as Kyoryu. The children operate robots known as FRANXX in order to face these still unseen enemies. Among them was a boy who was once called a child prodigy: Code number 016, Hiro. One day, a mysterious girl called Zero Two appears in front of Hiro. “I’ve found you, my Darling.” (Source: Crunchyroll)', '/uploads/images/s_99423.jpg', 'Cohabitation,Psychosexual,Super Robot,Orphan,Post-Apocalyptic,Primarily Teen Cast,Dystopian,Coming of Age', 'https://anilist.co/anime/99423'),
('七大罪 戒律的复活', '七つの大罪 戒めの復活', 'TV', 'A-1 Pictures', '2018-01-01', '24', '7.3', 'Melodias, Hawk, and Elizabeth retook the Kingdom of Leones from the Holy Knights. The festival went off without a hitch and the crew enjoyed their well-earned peace. And yet, another threat looms on the horizon. The Ten Commandments, a group of elite demon clan warriors, have their sights set on the kingdom. (Source: Anime News Network)', '/uploads/images/s_99539.jpg', 'Demons,Shounen,Magic,Super Power,Fairy,Gods,Archery,Swordplay', 'https://anilist.co/anime/99539'),
('宅男腐女恋爱真难 OAD', 'ヲタクに恋は難しい', 'TV', 'A-1 Pictures', '2018-01-01', '11', '7.8', 'Having slept through all four of her alarms, the energetic Narumi Momose finds herself running late for her first day of work at a new office. As she races to catch her train, she makes a promise to herself that none of her coworkers will find out about her dark secret: that she is an otaku and a fujoshi. Her plan goes instantly awry, though, when she runs into Hirotaka Nifuji, an old friend from middle school. Although she tries to keep her secret by inviting him out for drinks after work, her cover is blown when he casually asks her whether or not she will be attending the upcoming Summer Comiket. Luckily for her, the only witnesses—Hanako Koyanagi and Tarou Kabakura—are otaku as well. Later that night, the pair go out for drinks so that they can catch up after all the years apart. After Narumi complains about her previous boyfriend breaking up with her because he refused to date a fujoshi, Hirotaka suggests that she try dating a fellow otaku, specifically himself. He makes a solemn promise to always be there for her, to support her, and to help her farm for rare drops in Monster Hunter. Blown away by the proposal, Narumi agrees immediately. Thus the two otaku start dating, and their adorably awkward romance begins. (Source: MAL Rewrite)', '/uploads/images/s_99578.jpg', 'Otaku Culture,Primarily Adult Cast,Josei,Office Lady,Female Protagonist,Video Games,Work,Episodic', 'https://anilist.co/anime/99578'),
('我想吃掉你的胰脏', '君の膵臓をたべたい', '剧场版', 'Studio VOLN', '2018-01-01', '1', '8.4', 'Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: "Living with Dying." He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret. Trying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change. (Source: Aniplex USA)', '/uploads/images/s_99750.jpg', 'Tragedy,Coming of Age,Male Protagonist,Philosophy,Female Protagonist,Heterosexual,Primarily Teen Cast,Classic Literature', 'https://anilist.co/anime/99750'),
('我的英雄学院 第三季', '僕のヒーローアカデミア３', 'TV', 'bones', '2018-01-01', '25', '7.9', 'Summer is here, and the heroes of Class 1-A and 1-B are in for the toughest training camp of their lives! A group of seasoned pros pushes everyone''s Quirks to new heights as the students face one overwhelming challenge after another. Braving the elements in this secret location becomes the least of their worries when routine training turns into a critical struggle for survival. (Source: Crunchyroll)', '/uploads/images/s_100166.jpg', 'Superhero,Super Power,Shounen,Primarily Teen Cast,Boarding School,Cultivation,Urban Fantasy,School', 'https://anilist.co/anime/100166'),
('刀剑神域 爱丽丝篇 异界战争', 'ソードアート・オンライン アリシゼーション', 'TV', 'A-1 Pictures', '2018-01-01', '24', '7.5', 'Kirito awakens in a vast, fantastical forest filled with towering trees. In his search for clues to the truth of his surroundings, he encounters a young boy who seems to know him. He ought to be a simple NPC, but the depth of his emotions seem no different than a human. As they search for the boy''s parents, Kirito finds a peculiar memory returning to him. A memory from his own childhood, of this boy and a girl, too, with golden hair, and a name he should have never forgotten - Alice. (Source: Yen Press) Note: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', '/uploads/images/s_100182.jpg', 'Virtual World,Male Protagonist,Tragedy,Swordplay,Artificial Intelligence,Memory Manipulation,Isekai,Time Skip', 'https://anilist.co/anime/100182'),
('东京喰种:re', '東京喰種-トーキョーグール-:re', 'TV', 'Studio Pierrot', '2018-01-01', '12', '6.2', 'Two years have passed since the CCG’s raid on Anteiku. Although the atmosphere in Tokyo has changed drastically due to the increased influence of the CCG, ghouls continue to pose a problem as they have begun taking caution, especially the terrorist organization Aogiri Tree, who acknowledge the CCG’s growing threat to their existence. The creation of a special team, known as the Quinx Squad, may provide the CCG with the push they need to exterminate Tokyo’s unwanted residents. As humans who have undergone surgery in order to make use of the special abilities of ghouls, they participate in operations to eradicate the dangerous creatures. The leader of this group, Haise Sasaki, is a half-ghoul, half-human who has been trained by famed special class investigator, Kishou Arima. However, there’s more to this young man than meets the eye, as unknown memories claw at his mind, slowly reminding him of the person he used to be.', '/uploads/images/s_100240.jpg', 'Detective,Amnesia,Tragedy,Dissociative Identities,Male Protagonist,Time Skip,Urban Fantasy,Police', 'https://anilist.co/anime/100240'),
('战栗杀机', 'BANANA FISH', 'TV', 'MAPPA', '2018-01-01', '24', '8.4', 'Nature made Ash Lynx beautiful; nurture made him a cold ruthless killer. A runaway brought up as the adopted heir and sex toy of "Papa" Dino Golzine, Ash, now at the rebellious age of seventeen, forsakes the kingdom held out by the devil who raised him. But the hideous secret that drove Ash''s older brother mad in Vietnam has suddenly fallen into Papa''s insatiably ambitious hands—and it''s exactly the wrong time for Eiji Okamura, a pure-hearted young photographer from Japan, to make Ash Lynx''s acquaintance... (Source: VIZ Media)', '/uploads/images/s_100388.jpg', 'Gangs,Mafia,Tragedy,Crime,Conspiracy,Drugs,Male Protagonist,Primarily Male Cast', 'https://anilist.co/anime/100388'),
('哥布林杀手 哥布林的王冠', 'ゴブリンスレイヤー', 'TV', 'WHITE FOX', '2018-01-01', '12', '7.1', 'A young priestess has formed her first adventuring party, but almost immediately they find themselves in distress. It''s the Goblin Slayer who comes to their rescue--a man who''s dedicated his life to the extermination of all goblins, by any means necessary. And when rumors of his feats begin to circulate, there''s no telling who might come calling next... (Source: Yen Press)', '/uploads/images/s_101165.jpg', 'Goblin,Revenge,Gore,Male Protagonist,Tragedy,Nudity,Primarily Adult Cast,Female Harem', 'https://anilist.co/anime/101165'),
('关于我转生变成史莱姆这档事 第二季', '転生したらスライムだった件', 'TV', '8-bit', '2018-01-01', '24', '8.0', 'Lonely thirty-seven-year-old Satoru Mikami is stuck in a dead-end job, unhappy with his mundane life, but after dying at the hands of a robber, he awakens to a fresh start in a fantasy realm...as a slime monster! As he acclimates to his goopy new existence, his exploits with the other monsters set off a chain of events that will change his new world forever! (Source: Yen Press)', '/uploads/images/s_101280.jpg', 'Isekai,Reincarnation,Magic,Found Family,Kingdom Management,Super Power,Shapeshifting,Economics', 'https://anilist.co/anime/101280'),
('青春猪头少年不会梦到兔女郎学姐', '青春ブタ野郎はバニーガール先輩の夢を見ない', 'TV', 'CloverWorks', '2018-01-01', '13', '8.1', 'There''s a rumor about a mysterious phenomenon called "puberty syndrome." For example, Sakuta Azusagawa is a high school student who suddenly sees a bunny girl appear in front of him. The girl is actually a girl named Mai Sakurajima, who is Sakuta''s upperclassman who is also a famous actress who has gone on hiatus from the entertainment industry. For some reason, the people around Mai cannot see her bunny-girl figure. Sakuta sets out to solve this mystery, and as he spends time with Mai, he learns her secret feelings. Other heroines who have "puberty syndrome" start to appear in front of Sakuta. (Source: Anime News Network)', '/uploads/images/s_101291.jpg', 'Urban Fantasy,Primarily Teen Cast,Heterosexual,Male Protagonist,Coming of Age,Kuudere,Primarily Female Cast,Memory Manipulation', 'https://anilist.co/anime/101291'),
('灵能百分百 第二季', 'モブサイコ100 II', 'TV', 'bones', '2019-01-01', '13', '8.7', 'The second season of Mob Psycho 100. Kageyama is an ordinary 8th grader who just wants to live a normal life. Although he can disappear in the crowd in a flash, he was actually the most powerful psychic. The lives of those around Mob and his numerous feelings that softly piles up for the eventual explosion. The mysterious group "Claw" stands before him once again. In the midst of his youthful days, where will his roaring heart take him!? (Source: Crunchyroll)', '/uploads/images/s_101338.jpg', 'Super Power,Coming of Age,Urban Fantasy,Male Protagonist,Philosophy,Shounen,Primarily Teen Cast,Satire', 'https://anilist.co/anime/101338'),
('多罗罗', 'どろろ', 'TV', 'MAPPA', '2019-01-01', '24', '8.1', 'Dororo, a young orphan thief, meets Hyakkimaru, a powerful ronin. Hyakkimaru''s father, a greedy feudal lord, had made a pact with 12 demons, offering his yet-unborn son''s body parts in exchange for great power. Thus, Hyakkimaru - who was born without arms, legs, eyes, ears, a nose or a mouth - was abandoned in a river as a baby. Rescued and raised by Dr. Honma, who equips him with artificial limbs and teaches him sword-fighting techniques, Hyakkimaru discovers that each time he slays a demon, a piece of his body is restored. Now, he roams the war-torn countryside in search of demons.', '/uploads/images/s_101347.jpg', 'Demons,Revenge,Disability,Curses,Swordplay,Tragedy,Samurai,Estranged Family', 'https://anilist.co/anime/101347'),
('冰海战记', 'ヴィンランド・サガ', 'TV', 'WIT STUDIO', '2019-01-01', '24', '8.7', 'Thorfinn is son to one of the Vikings'' greatest warriors, but when his father is killed in battle by the mercenary leader Askeladd, he swears to have his revenge. Thorfinn joins Askeladd''s band in order to challenge him to a duel, and ends up caught in the middle of a war for the crown of England. (Source: Kodansha USA)', '/uploads/images/s_101348.jpg', 'Vikings,Revenge,Foreign,War,Historical,Male Protagonist,Philosophy,Coming of Age', 'https://anilist.co/anime/101348'),
('约定的梦幻岛', '約束のネバーランド', 'TV', 'CloverWorks', '2019-01-01', '12', '8.3', 'Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing. (Source: VIZ Media)', '/uploads/images/s_101759.jpg', 'Dystopian,Survival,Primarily Child Cast,Orphan,Tragedy,Found Family,Prison,Demons', 'https://anilist.co/anime/101759'),
('辉夜大小姐想让我告白', 'かぐや様は告らせたい～天才たちの恋愛頭脳戦～', 'TV', 'A-1 Pictures', '2019-01-01', '12', '8.3', 'Known for being both brilliant and powerful, Miyuki Shirogane and Kaguya Shinomiya lead the illustrious Shuchiin Academy as near equals. And everyone thinks they’d make a great couple. Pride and arrogance are in ample supply, so the only logical move is to trick the other into instigating a date! Who will come out on top in this psychological war where the first move is the only one that matters? (Source: Aniplex)', '/uploads/images/s_101921.jpg', 'School,Heterosexual,Tsundere,Primarily Teen Cast,School Club,Surreal Comedy,Ojou-sama,Episodic', 'https://anilist.co/anime/101921'),
('剧场版 鬼灭之刃 无限城篇 第一章 猗窝座再袭', '鬼滅の刃', 'TV', 'ufotable', '2019-01-01', '26', '8.3', 'It is the Taisho Period in Japan. Tanjiro, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. To make matters worse, his younger sister Nezuko, the sole survivor, has been transformed into a demon herself. Though devastated by this grim reality, Tanjiro resolves to become a “demon slayer” so that he can turn his sister back into a human, and kill the demon that massacred his family. (Source: Crunchyroll)', '/uploads/images/s_101922.jpg', 'Demons,Shounen,Swordplay,Male Protagonist,Vampire,Tragedy,Primarily Teen Cast,Travel', 'https://anilist.co/anime/101922'),
('JOJO的奇妙冒险 黄金之风', 'ジョジョの奇妙な冒険 黄金の風', 'TV', 'david production', '2018-01-01', '39', '8.5', 'The fifth story arc of the long-running JoJo''s Bizarre Adventure series. Giorno Giovanna, a young man living in Naples, has the blood of DIO -- the eternal enemy of the Joestar clan -- running in his veins. Giorno becomes a delinquent due to being persecuted since childhood. However, he''s led back onto the right path thanks to a gangster who saved him and taught him to believe in others. Bizarrely enough, this gang of people who didn''t forget honor, gratitude, and respect made him reform. This is how Giorno came to admire gangsters. In the backstreets of Italy, Giorno causes trouble alongside his gang "Passione," and ends up being targeted... (Source: Anime News Network)', '/uploads/images/s_102883.png', 'Criminal Organization,Super Power,Mafia,Gangs,Urban Fantasy,Male Protagonist,Primarily Male Cast,Foreign', 'https://anilist.co/anime/102883'),
('五等分的新娘∬', '五等分の花嫁', 'TV', 'Tezuka Productions', '2019-01-01', '12', '7.6', 'Uesugi Fuutarou, a high school second-year from a poor family, receives a highly appealing offer to work part-time as a tutor... but his students turn out to be girls from his own class! What''s more, they''re quintuplets... and all five are beautiful, but happen to be problem students who have borderline grades and hate studying! Looks like his first assignment will be to win all the sisters'' trust?! Every day is a wild party in this rom-com centering around the quintuplet sisters of the Nakano household! (Source: Crunchyroll)', '/uploads/images/s_103572.jpg', 'Twins,Female Harem,Heterosexual,Primarily Teen Cast,Male Protagonist,Primarily Female Cast,School,Ensemble Cast', 'https://anilist.co/anime/103572'),
('青春猪头少年不会梦到怀梦美少女', '青春ブタ野郎はゆめみる少女の夢を見ない', '剧场版', 'CloverWorks', '2019-01-01', '1', '8.4', 'In Fujisawa, where the skies are bright and the seas glisten, Sakuta Azusagawa is in his second year of high school. His blissful days with his girlfriend and upperclassman, Mai Sakurajima, are interrupted with the appearance of his first crush, Shouko Makinohara. For reasons unknown, he encounters two Shouko''s: one in middle school and another who has become an adult. As Sakuta finds himself helplessly living with the Shouko''s, the adult Shouko leads him around by the nose, causing a huge rift in his relationship with Mai. In the midst of all of this, he discovers that the middle school Shouko is suffering from a grave illness and his scar begins to throb... (Source: Aniplex USA)', '/uploads/images/s_104157.jpg', 'Time Manipulation,Coming of Age,Male Protagonist,Tragedy,Urban Fantasy,Female Protagonist,Heterosexual,Alternate Universe', 'https://anilist.co/anime/104157'),
('我的英雄学院 第四季', '僕のヒーローアカデミア４', 'TV', 'bones', '2019-01-01', '25', '7.9', 'The villain world teeters on the brink of war now that All For One is out of the picture. Shigaraki of the League of Villains squares off with Overhaul of the yakuza, vying for total control of the shadows. Meanwhile, Deku gets tangled in another dangerous internship as he struggles to keep pace with his upperclassman—Mirio. (Source: Crunchyroll)', '/uploads/images/s_104276.jpg', 'Superhero,Super Power,Shounen,Male Protagonist,School,Primarily Teen Cast,Crime,Ensemble Cast', 'https://anilist.co/anime/104276'),
('进击的巨人 第三季 Part.2', '進撃の巨人 Season３ Part.2', 'TV', 'WIT STUDIO', '2019-01-01', '10', '9.0', 'The battle to retake Wall Maria begins now! With Eren’s new hardening ability, the Scouts are confident they can seal the wall and take back Shiganshina District. If they succeed, Eren can finally unlock the secrets of the basement—and the world. But danger lies in wait as Reiner, Bertholdt, and the Beast Titan have plans of their own. Could this be humanity’s final battle for survival? (Source: Funimation)', '/uploads/images/s_104578.jpg', 'Dystopian,Military,Conspiracy,Tragedy,Survival,Memory Manipulation,Shapeshifting,Super Power', 'https://anilist.co/anime/104578'),
('炎炎消防队 叁之章 第2部分', '炎炎ノ消防隊', 'TV', 'david production', '2019-01-01', '24', '7.6', 'Year 198 of the Solar Era in Tokyo, special fire brigades are fighting against a phenomenon called spontaneous human combustion where human beings are turned into living infernos called "Infernals.” While the Infernals are first-generation cases of spontaneous human combustion, later generations possess the ability to manipulate flames while retaining human form. Shinra Kusakabe, a youth who gained the nickname Devil’s Footprints for his ability to ignite his feet at will, joins the Special Fire Force Company 8 which composes of other flames users as they work to extinguish any Infernals they encounter. As a faction that is creating Infernals appears, Shinra begins to uncover the truth behind a mysterious fire that caused the death of his family twelve years ago. (Source: Official Website)', '/uploads/images/s_105310.jpg', 'Firefighters,Urban Fantasy,Super Power,Shounen,Conspiracy,Demons,Cult,Urban', 'https://anilist.co/anime/105310'),
('石纪元', 'Dr.STONE', 'TV', 'TMS Entertainment', '2019-01-01', '24', '8.1', 'After five years of harboring unspoken feelings, high-schooler Taiju Ooki is finally ready to confess his love to Yuzuriha Ogawa. Just when Taiju begins his confession however, a blinding green light strikes the Earth and petrifies mankind around the world— turning every single human into stone. Several millennia later, Taiju awakens to find the modern world completely nonexistent, as nature has flourished in the years humanity stood still. Among a stone world of statues, Taiju encounters one other living human: his science-loving friend Senkuu, who has been active for a few months. Taiju learns that Senkuu has developed a grand scheme—to launch the complete revival of civilization with science. Taiju''s brawn and Senkuu''s brains combine to forge a formidable partnership, and they soon uncover a method to revive those petrified. However, Senkuu''s master plan is threatened when his ideologies are challenged by those who awaken. All the while, the reason for mankind''s petrification remains unknown. (Source: MAL Rewrite)', '/uploads/images/s_105333.jpg', 'Post-Apocalyptic,Survival,Lost Civilization,Educational,Time Skip,Male Protagonist,Shounen,Urban Fantasy', 'https://anilist.co/anime/105333'),
('水果篮子 第一季', 'フルーツバスケット 1st Season', 'TV', 'TMS Entertainment', '2019-01-01', '25', '8.2', 'Tohru Honda thought her life was headed for misfortune when a family tragedy left her living in a tent. When her small home is discovered by the mysterious Soma clan, she suddenly finds herself living with Yuki, Kyo, and Shigure Soma. But she quickly learns their family has a bizarre secret of their own: when hugged by the opposite sex, they turn into the animals of the Zodiac! (Source: Crunchyroll)', '/uploads/images/s_105334.jpg', 'Found Family,Female Protagonist,Urban Fantasy,Family Life,Shoujo,Mythology,Coming of Age,Shapeshifting', 'https://anilist.co/anime/105334'),
('天气之子', '天気の子', '剧场版', 'CoMix Wave', '2019-01-01', '1', '8.1', 'High school student Hodaka leaves his home on an isolated island and moves to Tokyo, but he immediately becomes broke. He lives his days in isolation, but finally finds a job as a writer for a shady occult magazine. After he starts his job, the weather has been rainy day after day. In a corner of the crowded and busy city, Hodaka meets a young woman named Hina. Due to certain circumstances, Hina and her younger brother live together, but have a cheerful and sturdy life. Hina also has a certain power: the power to stop the rain and clear the sky. (Source: Anime News Network)', '/uploads/images/s_106286.jpg', 'Urban Fantasy,Urban,Environmental,Orphan,Female Protagonist,Male Protagonist,Fugitive,Found Family', 'https://anilist.co/anime/106286'),
('排球少年!! TO THE TOP', 'ハイキュー!! TO THE TOP', 'TV', 'Production I.G', '2020-01-01', '13', '8.3', 'The fourth season of Haikyuu!! The Karasuno High School Volleyball Club finally won their way into the nationals after an intense battle for the Miyagi Prefecture Spring Tournament qualifiers. As they were preparing for the nationals, Kageyama is invited to go to All-Japan Youth Training Camp. At the same time, Tsukishima is invited to go to a special rookie select training camp for first-years in Miyagi Prefecture. Hinata feels panic that he’s being left behind as one of the first-years and then decides to show up at the Miyagi Prefecture rookie select training camp anyway... (Source: Crunchyroll)', '/uploads/images/s_106625.png', 'Volleyball,Male Protagonist,Shounen,School Club,Primarily Male Cast,Ensemble Cast,School,Primarily Teen Cast', 'https://anilist.co/anime/106625'),
('动物狂想曲', 'BEASTARS', 'TV', 'Orange', '2019-01-01', '12', '7.7', 'In a world populated by anthropomorphic animals, herbivores and carnivores coexist with each other. For the adolescents of Cherryton Academy, school life is filled with hope, romance, distrust, and uneasiness. The main character is Legoshi the wolf, a member of the drama club. Despite his menacing appearance, he has a very gentle heart. Throughout most of his life, he has always been an object of fear and hatred by other animals, and he’s been quite accustomed to that lifestyle. But soon, he finds himself becoming more involved with his fellow classmates who have their own share of insecurities and finds his life in school changing slowly. (Source: moetron)', '/uploads/images/s_107660.jpg', 'Anthropomorphism,Coming of Age,Animals,Primarily Teen Cast,Full CGI,Cannibalism,School,Male Protagonist', 'https://anilist.co/anime/107660'),
('无职转生～到了异世界就拿出真本事～ 第2部分', '無職転生 ～異世界行ったら本気だす～', 'TV', 'Studio Bind', '2021-01-01', '11', '8.2', 'When a 34-year-old underachiever gets run over by a bus, his story doesn’t end there. Reincarnated in a new world as an infant, Rudeus will seize every opportunity to live the life he’s always wanted. Armed with new friends, some freshly acquired magical abilities, and the courage to do the things he’s always dreamed of, he’s embarking on an epic adventure—with all of his past experience intact! (Source: Funimation, edited) Note: The anime pre-screened its 1st and 2nd episode starting on the 27th of December on the Nico Nico Live Broadcasting and D Anime Store services', '/uploads/images/s_108465.jpg', 'Isekai,Reincarnation,Magic,Male Protagonist,Rehabilitation,Coming of Age,Virginity,Travel', 'https://anilist.co/anime/108465'),
('关于我转生变成史莱姆这档事 第二季', '転生したらスライムだった件 第2期', 'TV', '8-bit', '2021-01-01', '12', '8.3', 'The second season of Tensei Shitara Slime Datta Ken. Now that the Jura Tempest Alliance is growing even further, they will now be meeting the animal kingdom of Eurazania, reuniting with King Gazel, rising tensions between monsters and humans, and Rimuru encountering the strongest enemy he’s ever faced. (Source: Funimation)', '/uploads/images/s_108511.jpg', 'Kingdom Management,Reincarnation,Isekai,Magic,War,Creature Taming,Demons,Politics', 'https://anilist.co/anime/108511'),
('Re：从零开始的异世界生活 第二季', 'Re:ゼロから始める異世界生活 2nd Season', 'TV', 'WHITE FOX', '2020-01-01', '13', '8.3', 'Even after dying countless times, Subaru finally ended the threat of the White Whale and defeated the Witch Cult''s Sin Archbishop representing sloth, Petelgeuse Romaneeconti. But only shortly after overcoming a tragic ending and reuniting with his beloved Emilia, Subaru learns that Rem has been erased from this world, having fallen victim to the White Whale''s Fog of Elimination in the midst of Subaru''s death loop. With the White Whale now gone, Subaru and Emilia are forced to confront a reality they never dreamed would happen. (Source: Crunchyroll)', '/uploads/images/s_108632.jpg', 'Isekai,Time Manipulation,Tragedy,Time Loop,Alternate Universe,Male Protagonist,Witch,Memory Manipulation', 'https://anilist.co/anime/108632'),
('约定的梦幻岛 第二季', '約束のネバーランド2', 'TV', 'CloverWorks', '2021-01-01', '11', '5.2', 'The second season of Yakusoku no Neverland. Fifteen children escape Grace Field House, a false paradise, hoping for a chance at freedom. Instead, they encounter plants and animals they have never before seen, and are chased by demons. The outside world is so beautiful, and yet is almost too cruel to face. Even so, the children refuse to give up. They are guided in their search for better lives only by a message from Minerva and a pen Norman left behind in order to fulfill their promise to return to the House to save those of their family who are still trapped within. (Source: Aniplex of America) Note: Episode 1 streamed early on Amazon Prime on Jan 7, 2021. The regular TV broadcast started on Jan 8, 2021.', '/uploads/images/s_108725.jpg', 'Survival,Primarily Child Cast,Demons,Dystopian,Fugitive,Ensemble Cast,Orphan,Kaiju', 'https://anilist.co/anime/108725'),
('进击的巨人 最终季', '進撃の巨人 The Final Season', 'TV', 'MAPPA', '2021-01-01', '16', '8.7', 'It’s been four years since the Scout Regiment reached the shoreline, and the world looks different now. Things are heating up as the fate of the Scout Regiment—and the people of Paradis—are determined at last. However, Eren is missing. Will he reappear before age-old tensions between Marleyans and Eldians result in the war of all wars? (Source: Crunchyroll)', '/uploads/images/s_110277.jpg', 'War,Tragedy,Military,Kaiju,Anti-Hero,Revenge,Politics,Dystopian', 'https://anilist.co/anime/110277'),
('鬼灭之刃 无限列车篇', '鬼滅の刃 無限列車編', '剧场版', 'ufotable', '2020-01-01', '1', '8.4', 'This Demon Slayer movie sees Tanjiro Kamado and friends from the Demon Slayer corps board the Infinity Train on a new mission to investigate a mysterious series of disappearances, perpetrated by a demon who has been tormenting people and killing the demon slayers who oppose it.', '/uploads/images/s_112151.jpg', 'Demons,Swordplay,Shounen,Tragedy,Trains,Curses,Male Protagonist,Body Horror', 'https://anilist.co/anime/112151'),
('魔王学院的不适任者～史上最强的魔王始祖，转生就读子孙们的学校～', '魔王学院の不適合者 ～史上最強の魔王の始祖、転生して子孫たちの学校へ通う～', 'TV', 'SILVER LINK.', '2020-01-01', '13', '7.2', 'Anos, the Demon King of Tyranny, has defeated humans, spirits, and gods alike. But even demon kings get tired of all the fighting sometimes! Hoping for a more peaceful life, Anos decides to reincarnate himself. When he wakes two thousand years later, though, he finds the world has become too peaceful--his descendants have grown weak and magic is in serious decline. Intending to reclaim his rightful place, he enrolls in Demon King Academy, where he finds that his magical power is off the charts. Literally. And because they can''t measure his power, the faculty and other students regard Anos as a misfit. With the support of Misha, the one student he manages to befriend, the misfit (Demon King) begins his climb up the demon ranks! (Source: Square Enix)', '/uploads/images/s_112301.jpg', 'Demons,Magic,Reincarnation,Male Protagonist,School,Super Power,Conspiracy,Memory Manipulation', 'https://anilist.co/anime/112301'),
('辉夜大小姐想让我告白？', 'かぐや様は告らせたい？～天才たちの恋愛頭脳戦～', 'TV', 'A-1 Pictures', '2020-01-01', '12', '8.5', 'After a slow but eventful summer vacation, Shuchiin Academy''s second term is now starting in full force. As August transitions into September, Miyuki Shirogane''s birthday looms ever closer, leaving Kaguya Shinomiya in a serious predicament as to how to celebrate it. Furthermore, the tenure of the school''s 67th student council is coming to an end. Due to the council members being in different classes, the only time Kaguya and Miyuki have to be together will soon disappear, putting all of their cunning plans at risk. A long and difficult election that will decide the fate of the new student council awaits, as multiple challengers fight for the coveted title of president. (Source: MAL Rewrite)', '/uploads/images/s_112641.jpg', 'School,School Club,Ensemble Cast,Tsundere,Female Protagonist,Male Protagonist,Primarily Teen Cast,Episodic', 'https://anilist.co/anime/112641'),
('咒术回战 怀玉･玉折 / 涩谷事变', '呪術廻戦', 'TV', 'MAPPA', '2020-01-01', '24', '8.4', 'A boy fights... for "the right death." Hardship, regret, shame: the negative feelings that humans feel become Curses that lurk in our everyday lives. The Curses run rampant throughout the world, capable of leading people to terrible misfortune and even death. What''s more, the Curses can only be exorcised by another Curse. Itadori Yuji is a boy with tremendous physical strength, though he lives a completely ordinary high school life. One day, to save a friend who has been attacked by Curses, he eats the finger of the Double-Faced Specter, taking the Curse into his own soul. From then on, he shares one body with the Double-Faced Specter. Guided by the most powerful of sorcerers, Gojou Satoru, Itadori is admitted to the Tokyo Metropolitan Technical High School of Sorcery, an organization that fights the Curses... and thus begins the heroic tale of a boy who became a Curse to exorcise a Curse, a life from which he could never turn back. (Source: Crunchyroll) Note: The first episode received an early web premiere on September 19th, 2020. The regular TV broadcast started on October 3rd, 2020.', '/uploads/images/s_113415.jpg', 'Urban Fantasy,Shounen,Curses,Super Power,Youkai,Male Protagonist,Exorcism,Primarily Teen Cast', 'https://anilist.co/anime/113415'),
('排球少年!! TO THE TOP 2', 'ハイキュー!! TO THE TOP 2', 'TV', 'Production I.G', '2020-01-01', '12', '8.5', 'The second half of Haikyuu!! 4th season kicks-off where the first part ended. Karasuno High won their first match of The Spring Nationals against Tsubakihara Academy. Karasuno High is excited to be back in the Spring Nationals after many years of not making it, so can they handle the pressure of playing against the best teams in Japan? Will they make it to the top?', '/uploads/images/s_113538.jpg', 'Primarily Teen Cast,Volleyball,Male Protagonist,Ensemble Cast,Primarily Male Cast,School Club,Shounen,Coming of Age', 'https://anilist.co/anime/113538'),
('租借女友 第三季', '彼女、お借りします', 'TV', 'TMS Entertainment', '2020-01-01', '12', '6.5', 'Kinoshita Kazuya is a 20-year-old failure of a college student. He managed to kiss his girlfriend once, but was dumped after a month. "Ugh... Damn it. I never want to go through that again." Completely spiteful, Kazuya uses a certain method to date a girl. He goes to their meeting place and suddenly hears, "You''re Kazuya-kun, right?" A beautiful girl brushing her long, black hair behind her ear was there, smiling at him. Her name was Mizuhara Chizuru. Something real is born after just a single rental! A reckless rom-com filled with love and excitement is about to begin! (Source: Crunchyroll)', '/uploads/images/s_113813.jpg', 'Prostitution,Love Triangle,Male Protagonist,Fake Relationship,Female Harem,Heterosexual,Unrequited Love,Slapstick', 'https://anilist.co/anime/113813'),
('石纪元 石之战争', 'Dr.STONE STONE WARS', 'TV', 'TMS Entertainment', '2021-01-01', '11', '8.1', 'The second season of Dr. STONE Armed with the power of science and a genius intellect, Senkuu is determined to save humanity. However, Tsukasa’s empire goes on the offensive to halt the progress of science. Bolder choices are made as these two start a war that rocks the Stone World. (Source: Crunchyroll)', '/uploads/images/s_113936.jpg', 'Post-Apocalyptic,Survival,Educational,Male Protagonist,War,Lost Civilization,Shounen,Environmental', 'https://anilist.co/anime/113936'),
('钢铁侠 第二季', '炎炎ノ消防隊 弐ノ章', 'TV', 'david production', '2020-01-01', '24', '7.8', 'Shinra and Company 8 have figured out the Evangelist’s goal: to gather Adolla Bursts from Shinra and Shou. After learning more about his past from Captain Burns, Shinra becomes more motivated to discover the truth about his mother and save Shou again. But a mysterious girl known as the “First Pillar” reveals the Evangelist’s master plan to start another Great Cataclysm! (Source: Funimation)', '/uploads/images/s_114236.png', 'Firefighters,Shounen,Super Power,Male Protagonist,Urban Fantasy,Ensemble Cast,Conspiracy,Post-Apocalyptic', 'https://anilist.co/anime/114236'),
('致不灭的你', '不滅のあなたへ', 'TV', 'Brain''s Base', '2021-01-01', '20', '8.1', 'In the beginning, an "orb" is cast unto Earth. "It" can do two things: change into the form of the thing that stimulates "it"; and come back to life after death. "It" morphs from orb to rock, then to wolf, and finally to boy, but roams about like a newborn who knows nothing. As a boy, "it" becomes Fushi. Through encounters with human kindness, Fushi not only gains survival skills but grows as a "person". But his journey is darkened by the inexplicable and destructive enemy Nokker and cruel partings with the people he loves. (Source: Crunchyroll)', '/uploads/images/s_114535.jpg', 'Shapeshifting,Tragedy,Coming of Age,Travel,Philosophy,Agender,Rural,Ensemble Cast', 'https://anilist.co/anime/114535'),
('神之塔 第二季', '神之塔 -Tower of God-', 'TV', 'Telecom Animation Film', '2020-01-01', '13', '7.4', 'There is a tower that summons chosen people called "Regulars" with the promise of granting their deepest desires. Whether it be wealth, fame, authority, or something that surpasses them all—everything awaits those who reach the top. Twenty-Fifth Bam is a boy who had only known a dark cave, a dirty cloth, and an unreachable light his entire life. So when a girl named Rachel came to him through the light, his entire world changed. Becoming close friends with Rachel, he learned various things about the outside world from her. But when Rachel says she must leave him to climb the Tower, his world shatters around him. Vowing to follow after her no matter what it takes, he sets his sight on the tower, and a miracle occurs. Thus begins the journey of Bam, a young boy who was not chosen by the Tower but opened its gates by himself. They call his kind "Irregulars"—beings that have shaken the very foundation of the Tower each time they set foot inside it.', '/uploads/images/s_115230.jpg', 'Super Power,Tragedy,Male Protagonist,Survival,Conspiracy,Magic,Ensemble Cast,Cultivation', 'https://anilist.co/anime/115230'),
('高校之神', 'THE GOD OF HIGH SCHOOL ゴッド・オブ・ハイスクール', 'TV', 'MAPPA', '2020-01-01', '13', '7.0', 'It all began as a fighting tournament to seek out for the best fighter among all high school students in Korea. Mori Jin, a Taekwondo specialist and a high school student, soon learns that there is something much greater beneath the stage of the tournament. (Source: WEBTOON)', '/uploads/images/s_116006.png', 'Martial Arts,Urban Fantasy,Gods,Super Power,Shounen,Male Protagonist,Rotoscoping,Cult', 'https://anilist.co/anime/116006'),
('86 -不存在的战区- 第2部分', '86－エイティシックス－', 'TV', 'A-1 Pictures', '2021-01-01', '11', '8.3', 'Called “Juggernaut,” these are the unmanned combat drones developed by the Republic of San Magnolia in answer to the attacks by the autonomous unmanned drones of the neighboring Empire of Giad, the “Legion”. But they’re only unmanned in name. In reality, they are piloted by the Eighty-sixers—those considered to be less than human and treated as mere tools. Determined to achieve his own mysterious ends, Shin, the captain of Spearhead Squadron, which is comprised of Eighty-sixers, continues to fight a hopeless war on a battlefield where only death awaits him. (Source: Crunchyroll)', '/uploads/images/s_116589.jpg', 'War,Class Struggle,Military,Tragedy,Dystopian,Survival,Ensemble Cast,Seinen', 'https://anilist.co/anime/116589'),
('关于我转生变成史莱姆这档事 第二季 第2部分', '転生したらスライムだった件 第2期 第2クール', 'TV', '8-bit', '2021-01-01', '12', '8.2', 'The second cour of Tensei Shitara Slime Datta Ken 2nd Season. The nation of Tempest is in a festive mood after successfully overcoming the surprise attack from the Falmuth Army and the Western Holy Church. Beyond the festivities lies a meeting between Tempest and its allies to decide the future of the Nation of Monsters. The aftermath of the Falmuth invasion, Milim Nava''s suspicious behavior, and the disappearance of Demon Lord Carrion—the problems seem to keep on piling up. Rimuru Tempest, now awakened as a "True Demon Lord," decides to go on the offensive against Clayman. With the fully revived "Storm Dragon" Veldora, "Ultimate Skill" Raphael, and other powerful comrades, the ruler of the Tempest is confident in taking down his enemies one by one until he can face the man pulling the strings.', '/uploads/images/s_116742.jpg', 'Kingdom Management,Isekai,Reincarnation,Super Power,Magic,Demons,Politics,War', 'https://anilist.co/anime/116742'),
('我的英雄学院 第五季', '僕のヒーローアカデミア５', 'TV', 'bones', '2021-01-01', '25', '7.3', 'The rivalry between Class 1-A and Class 1-B heats up in a joint training battle. Eager to be a part of the hero course, brainwashing buff Shinso is tasked with competing on both sides. But as each team faces their own weaknesses and discovers new strengths, this showdown might just become a toss-up. (Source: Funimation)', '/uploads/images/s_117193.jpg', 'Superhero,Super Power,Shounen,Male Protagonist,School,Cultivation,Primarily Teen Cast,Primarily Male Cast', 'https://anilist.co/anime/117193'),
('Re：从零开始的异世界生活 第二季 Part 2', 'Re:ゼロから始める異世界生活 2nd Season Part 2', 'TV', 'WHITE FOX', '2021-01-01', '12', '8.4', 'After learning more behind the Death Loop and Witches of Sin, Subaru vows to save Emilia and his friends from further doom. (Source: Crunchyroll)', '/uploads/images/s_119661.png', 'Isekai,Tragedy,Time Manipulation,Male Protagonist,Witch,Magic,Memory Manipulation,Ensemble Cast', 'https://anilist.co/anime/119661'),
('东京复仇者', '東京リベンジャーズ', 'TV', 'LIDENFILMS', '2021-01-01', '24', '7.7', 'Takemichi Hanagaki is a freelancer that''s reached the absolute pits of despair in his life. He finds out that the only girlfriend he ever had in his life that he dated in middle school, Hinata Tachibana, had been killed by the ruthless Tokyo Manji Gang. The day after hearing about her death, he''s standing on the station platform and ends up being pushed over onto the tracks by a herd of people. He closes his eyes thinking he''s about to die, but when he opens his eyes back up, he somehow had gone back in time 12 years. Now that he''s back living the best days of his life, Takemichi decides to get revenge on his life by saving his girlfriend and changing himself that he''d been running away from. (Source: Crunchyroll)', '/uploads/images/s_120120.jpg', 'Gangs,Delinquents,Time Manipulation,Age Regression,Male Protagonist,Primarily Male Cast,Tragedy,Urban', 'https://anilist.co/anime/120120'),
('赛博浪客', 'サイバーパンク エッジランナーズ', '网络动画', 'TRIGGER', '2022-01-01', '10', '8.5', 'An original anime series set in in the universe of Cyberpunk 2077. Cyberpunk: Edgerunners tells a standalone, 10-episode story about a street kid trying to survive in a technology and body modification-obsessed city of the future. Having everything to lose, he chooses to stay alive by becoming an edgerunner—a mercenary outlaw also known as a cyberpunk. (Source: CD PROJEKT RED) Note: The first episode received a pre-screening at Anime Expo on July 2, 2022. The first 3 dubbed episodes were streamed on Twitch as part of a co-stream promotion on September 12, a day before the show’s premiere.', '/uploads/images/s_120377.jpg', 'Cyberpunk,Tragedy,Crime,Dystopian,Cyborg,Male Protagonist,Class Struggle,Gangs', 'https://anilist.co/anime/120377'),
('不要欺负我，长瀞同学', 'イジらないで、長瀞さん', 'TV', 'Telecom Animation Film', '2021-01-01', '12', '6.9', '"A girl in a lower grade just made me cry!" One day, Senpai visits the library after school and becomes the target of a super sadistic junior! The name of the girl who teases, torments, and tantalizes Senpai is "Nagatoro!" She''s annoying yet adorable. It''s painful, but you still want to be by her side. This is a story about an extremely sadistic and temperamental girl and you''ll feel something awaken inside of you. (Source: Crunchyroll)', '/uploads/images/s_120697.jpg', 'Male Protagonist,Slapstick,Bullying,School,Heterosexual,Tsundere,Episodic,Primarily Teen Cast', 'https://anilist.co/anime/120697'),
('堀与宫村 -piece-', 'ホリミヤ', 'TV', 'CloverWorks', '2021-01-01', '13', '8.1', 'A secret life is the one thing they have in common. At school, Hori is a prim and perfect social butterfly, but the truth is she''s a brash homebody. Meanwhile, under a gloomy facade, Miyamura hides a gentle heart, along with piercings and tattoos. In a chance meeting, they both reveal a side they''ve never shown. Could this blossom into something new? (Source: Funimation)', '/uploads/images/s_124080.jpg', 'School,Female Protagonist,Family Life,Male Protagonist,Heterosexual,Ensemble Cast,Coming of Age,Primarily Teen Cast', 'https://anilist.co/anime/124080'),
('奇蛋物语', 'ワンダーエッグ・プライオリティ', 'TV', 'CloverWorks', '2021-01-01', '12', '7.4', 'This is the story of Ai, an introverted girl whose fate is forever changed when she acquires a mysterious “Wonder Egg” from a deserted arcade. That night, her dreams blend into reality, and as other girls obtain their own Wonder Eggs, Ai discovers new friends—and the magic within herself. (Source: Funimation)', '/uploads/images/s_124845.jpg', 'Tragedy,Female Protagonist,Primarily Female Cast,Urban Fantasy,Suicide,Bullying,Coming of Age,Alternate Universe', 'https://anilist.co/anime/124845'),
('辉夜大小姐想让我告白-超级浪漫-', 'かぐや様は告らせたい-ウルトラロマンティック-', 'TV', 'A-1 Pictures', '2022-01-01', '13', '8.9', 'The elite members of Shuchiin Academy''s student council continue their competitive day-to-day antics. Council president Miyuki Shirogane clashes daily against vice-president Kaguya Shinomiya, each fighting tooth and nail to trick the other into confessing their romantic love. Kaguya struggles within the strict confines of her wealthy, uptight family, rebelling against her cold default demeanor as she warms to Shirogane and the rest of her friends. Meanwhile, council treasurer Yuu Ishigami suffers under the weight of his hopeless crush on Tsubame Koyasu, a popular upperclassman who helps to instill a new confidence in him. Miko Iino, the newest student council member, grows closer to the rule-breaking Ishigami while striving to overcome her own authoritarian moral code. As love further blooms at Shuchiin Academy, the student council officers drag their outsider friends into increasingly comedic conflicts. (Source: MAL Rewrite) Note: The first episode had an advanced screening on April 2, in both New York & Los Angeles.', '/uploads/images/s_125367.png', 'School,Heterosexual,School Club,Primarily Teen Cast,Slapstick,Ensemble Cast,Coming of Age,Tsundere', 'https://anilist.co/anime/125367'),
('剧场版 链锯人 蕾塞篇', 'チェンソーマン', 'TV', 'MAPPA', '2022-01-01', '12', '8.3', 'Denji is a teenage boy living with a Chainsaw Devil named Pochita. Due to the debt his father left behind, he has been living a rock-bottom life while repaying his debt by harvesting devil corpses with Pochita. One day, Denji is betrayed and killed. As his consciousness fades, he makes a contract with Pochita and gets revived as "Chainsaw Man" — a man with a devil''s heart. (Source: Crunchyroll)', '/uploads/images/s_127230.jpg', 'Demons,Monster Boy,Urban Fantasy,Male Protagonist,Gore,Tragedy,Shapeshifting,Body Horror', 'https://anilist.co/anime/127230'),
('无职转生～到了异世界就拿出真本事～ 第2部分', '無職転生 ～異世界行ったら本気だす～ 第2クール', 'TV', 'Studio Bind', '2021-01-01', '12', '8.5', 'After the mysterious mana calamity, Rudeus Greyrat and his fierce student Eris Boreas Greyrat are teleported to the Demon Continent. There, they team up with their newfound companion Ruijerd Supardia—the former leader of the Superd''s Warrior group—to form "Dead End," a successful adventurer party. Making a name for themselves, the trio journeys across the continent to make their way back home to Fittoa. Following the advice he received from the faceless god Hitogami, Rudeus saves Kishirika Kishirisu, the Great Emperor of the Demon World, who rewards him by granting him a strange power. Now, as Rudeus masters the powerful ability that offers a number of new opportunities, it might prove to be more than what he bargained for when unexpected dangers threaten to hinder their travels. (Source: MAL Rewrite)', '/uploads/images/s_127720.jpg', 'Isekai,Reincarnation,Magic,Travel,Coming of Age,Male Protagonist,Rehabilitation,Tragedy', 'https://anilist.co/anime/127720'),
('地狱乐 第二季', '地獄楽', 'TV', 'MAPPA', '2023-01-01', '13', '8.0', 'The Edo period is nearing its end. Gabimaru, a shinobi formerly known as the strongest in Iwagakure who is now a death row convict, is told that he will be acquitted and set free if he can bring back the Elixir of Life from an island that is rumored to be the Buddhist pure land Sukhavati. In hopes of reuniting with his beloved wife, Gabimaru heads to the island along with the executioner Yamada Asaemon Sagiri. Upon arriving there, they encounter other death row convicts in search of the Elixir of Life... as well as a host of unknown creatures, eerie manmade statues, and the hermits who rule the island. Can Gabimaru find the Elixir of Life on this mysterious island and make it back home alive? (Source: Crunchyroll)', '/uploads/images/s_128893.jpg', 'Survival,Swordplay,Gore,Shounen,Body Horror,Ninja,Samurai,Battle Royale', 'https://anilist.co/anime/128893'),
('鬼灭之刃 无限列车篇 (TV)', '鬼滅の刃 無限列車編 (TV)', 'TV', 'ufotable', '2021-01-01', '7', '8.2', 'In Demon Slayer: Kimetsu no Yaiba Mugen Train Arc, Tanjiro Kamado and his fellow Demon Slayer members embark on a mission aboard the Infinity Train. Their new mission is to investigate a series of mysterious disappearances, carried out by a demon that has been terrorizing passengers and killing the demon slayers who oppose it. Note: The first episode is entirely anime original. Episodes 2-7 are a re-edited version of the movie featuring new scenes and music.', '/uploads/images/s_129874.jpg', 'Demons,Swordplay,Shounen,Tragedy,Male Protagonist,Curses,Gore,Trains', 'https://anilist.co/anime/129874'),
('孤独摇滚！', 'ぼっち・ざ・ろっく！', 'TV', 'CloverWorks', '2022-01-01', '12', '8.7', 'Hitori Gotou, “Bocchi-chan,” is a girl who’s so introverted and shy around people that she’d always start her conversations with “Ah...” During her middle school years, she started playing the guitar, wanting to join a band because she thought it could be an opportunity for even someone shy like her to also shine. But because she had no friends, she ended up practicing guitar for six hours every day all by herself. After becoming a skilled guitar player, she uploaded videos of herself playing the guitar to the internet under the name “Guitar Hero” and fantasized about performing at her school’s cultural festival concert. But not only could she not find any bandmates, before she knew it, she was in high school and still wasn’t able to make a single friend! She was really close to becoming a shut-in, but one day, Nijika Ijichi, the drummer in Kessoku Band, reached out to her. And because of that, her everyday life started to change little by little... (Source: Crunchyroll)', '/uploads/images/s_130003.png', 'Band,Female Protagonist,Primarily Female Cast,Primarily Teen Cast,Rock Music,Cute Girls Doing Cute Things,Coming of Age,Hikikomori', 'https://anilist.co/anime/130003'),
('想要成为影之实力者！', '陰の実力者になりたくて！', 'TV', 'Nexus', '2022-01-01', '20', '8.1', 'Some people just aren’t suited to playing the part of the flashy, in-your-face hero or the dastardly, mustache-twirling villain with larger-than-life panache. Instead, they operate in the shadows and pull the strings of society through wit and cleverness. That’s the role Cid wants to play when he’s transported to another world. Cid spins a yarn or three and becomes the unlikely leader of the underground Shadow Garden organization that fights against a menacing cult (which he totally made up). However, there’s a catch even his wild imagination didn’t see coming: the cult he concocted actually exists, and they’re beyond displeased that his power fantasy just got in the way of their evil plans! (Source: HIDIVE)', '/uploads/images/s_130298.jpg', 'Isekai,Chuunibyou,Male Protagonist,Parody,Anti-Hero,Magic,Cult,Acting', 'https://anilist.co/anime/130298'),
('剧场版 咒术回战 0', '呪術廻戦 0', '剧场版', 'MAPPA', '2021-01-01', '1', '8.3', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him? (Source: VIZ Media)', '/uploads/images/s_131573.jpg', 'Curses,Demons,Male Protagonist,Shounen,Tragedy,Urban Fantasy,Super Power,Urban', 'https://anilist.co/anime/131573'),
('进击的巨人 最终季 Part.2', '進撃の巨人 The Final Season Part 2', 'TV', 'MAPPA', '2022-01-01', '12', '8.7', 'The war for Paradis zeroes in on Shiganshina just as Jaegerists have seized control. After taking a huge blow from a surprise attack led by Eren, Marley swiftly acts to return the favor. With Zeke’s true plan revealed and a military forced under new rule, this battle might be fought on two fronts. Does Eren intend on fulfilling his half-brother’s wishes or does he have a plan of his own? (Source: Funimation)', '/uploads/images/s_131681.jpg', 'War,Tragedy,Revenge,Anti-Hero,Military,Survival,Memory Manipulation,Kaiju', 'https://anilist.co/anime/131681'),
('更衣人偶坠入爱河', 'その着せ替え人形は恋をする', 'TV', 'CloverWorks', '2022-01-01', '12', '8.0', 'High schooler Wakana Gojou cares about one thing: making Hina dolls. With nobody to share his obsession, he has trouble finding friends—or even holding conversation. But after the school’s most popular girl, Marin Kitagawa, reveals a secret of her own, he discovers a new purpose for his sewing skills. Together, they’ll make her cosplay dreams come true! (Source: Funimation)', '/uploads/images/s_132405.jpg', 'Cosplay,Otaku Culture,Fashion,Male Protagonist,Heterosexual,Primarily Teen Cast,Female Protagonist,Gyaru', 'https://anilist.co/anime/132405'),
('古见同学有交流障碍症', '古見さんは、コミュ症です。', 'TV', 'OLM', '2021-01-01', '12', '7.6', 'Timid Tadano is a total wallflower, and that’s just the way he likes it. But all that changes when he finds himself alone in a classroom on the first day of high school with the legendary Komi. He quickly realizes she isn’t aloof—she’s just super awkward. Now he’s made it his mission to help her on her quest to make 100 friends! (Source: VIZ Media)', '/uploads/images/s_133965.jpg', 'School,Kuudere,Disability,Female Protagonist,Episodic,Slapstick,Primarily Teen Cast,Male Protagonist', 'https://anilist.co/anime/133965'),
('冰海战记 第二季', 'ヴィンランド・サガ SEASON2', 'TV', 'MAPPA', '2023-01-01', '24', '8.8', 'The second season of Vinland Saga. After his father''s death and the destruction of his village at the hands of English raiders, Einar wishes for a peaceful life with his family on their newly rebuilt farms. However, fate has other plans: his village is invaded once again. Einar watches helplessly as the marauding Danes burn his lands and slaughter his family. The invaders capture Einar and take him back to Denmark as a slave. Einar clings to his mother''s final words to survive. He is purchased by Ketil, a kind slave owner and landlord who promises that Einar can regain his freedom in return for working in the fields. Soon, Einar encounters his new partner in farm cultivation—Thorfinn, a dejected and melancholic slave. As Einar and Thorfinn work together toward their freedom, they are haunted by both sins of the past and the ploys of the present. Yet they carry on, grasping for a glimmer of hope, redemption, and peace in a world that is nothing but unjust and unforgiving. (Source: MAL Rewrite)', '/uploads/images/s_136430.jpg', 'Rehabilitation,Seinen,Slavery,Tragedy,Vikings,Philosophy,Historical,Coming of Age', 'https://anilist.co/anime/136430'),
('蓝色监狱', 'ブルーロック', 'TV', '8-bit', '2022-01-01', '24', '8.0', 'Japan’s desire for World Cup glory leads the Japanese Football Association to launch a new rigorous training program to find the national team’s next striker. Three hundred high school players are pitted against each other for the position, but only one will come out on top. Who among them will be the striker to usher in a new era of Japanese soccer? (Source: Crunchyroll)', '/uploads/images/s_137822.jpg', 'Football,Male Protagonist,Shounen,Athletics,Primarily Male Cast,Battle Royale,Primarily Teen Cast,Ensemble Cast', 'https://anilist.co/anime/137822'),
('我的英雄学院 第六季', '僕のヒーローアカデミア６', 'TV', 'bones', '2022-01-01', '25', '8.2', 'With Tomura Shigaraki at its helm, the former Liberation Army is now known as the Paranormal Liberation Front. This organized criminal group poses an immense threat to the Hero Association, not only because of its sheer size and strength, but also the overpowering quirks of Jin "Twice" Bubaigawara and Gigantomachia. As new intel from the covert hero Keigo "Hawks" Takami confirms that Shigaraki is nowhere to be seen, the Hero Association decides to strike the enemy headquarters with a surprise attack using the entirety of its assets—and the UA students find themselves on the battlefield once again. As the fight rages on, the unsuspecting villains must regroup and push back, but the brave heroes are determined to eradicate every last one of them. (Source: MAL Rewrite)', '/uploads/images/s_139630.jpg', 'Super Power,Superhero,Shounen,Male Protagonist,Tragedy,War,Terrorism,Urban Fantasy', 'https://anilist.co/anime/139630'),
('灵能百分百 第三季', 'モブサイコ100 Ⅲ', 'TV', 'bones', '2022-01-01', '12', '8.7', 'The third season of Mob Psycho 100. The appearance of a divine tree and new religion turns Mob and Reigen''s city upside down! (Source: Crunchyroll)', '/uploads/images/s_140439.jpg', 'Coming of Age,Super Power,Urban Fantasy,Philosophy,Dissociative Identities,Surreal Comedy,Shounen,Cult', 'https://anilist.co/anime/140439'),
('间谍过家家', 'SPY×FAMILY', 'TV', 'CloverWorks', '2022-01-01', '12', '8.3', 'Everyone has a part of themselves they cannot show to anyone else. At a time when all nations of the world were involved in a fierce war of information happening behind closed doors, Ostania and Westalis had been in a state of cold war against one another for decades. The Westalis Intelligence Services'' Eastern-Focused Division (WISE) sends their most talented spy, "Twilight," on a top-secret mission to investigate the movements of Donovan Desmond, the chairman of Ostania''s National Unity Party, who is threatening peace efforts between the two nations. This mission is known as "Operation Strix." It consists of "putting together a family in one week in order to infiltrate social gatherings organized by the elite school that Desmond''s son attends." "Twilight" takes on the identity of psychiatrist Loid Forger and starts looking for family members. But Anya, the daughter he adopts, turns out to have the ability to read people''s minds, while his wife, Yor, is an assassin! With it being in each of their own interests to keep these facts hidden, they start living together while concealing their true identities from one another. World peace is now in the hands of this brand-new family as they embark on an adventure full of surprises. (Source: Crunchyroll)', '/uploads/images/s_140960.jpg', 'Espionage,Family Life,Found Family,Fake Relationship,Parenthood,Assassins,Adoption,Conspiracy', 'https://anilist.co/anime/140960'),
('彻夜之歌', 'よふかしのうた', 'TV', 'LIDENFILMS', '2022-01-01', '13', '7.9', 'Wracked by insomnia and wanderlust, Kou Yamori is driven onto the moonlit streets every night in an aimless search for something he can’t seem to name. His nightly ritual is marked by purposeless introspection — until he meets Nazuna, who might just be a vampire! Kou’s new companion could offer him dark gifts and a vampire’s immortality. But there are conditions that must be met before Kou can sink his teeth into vampirism, and he’ll have to discover just how far he’s willing to go to satisfy his desires before he can heed the Call of the Night! (Source: Sentai Filmworks)', '/uploads/images/s_141391.jpg', 'Vampire,Femdom,Urban Fantasy,Urban,Female Protagonist,Male Protagonist,Aromantic,Heterosexual', 'https://anilist.co/anime/141391'),
('鬼灭之刃 游郭篇', '鬼滅の刃 遊郭編', 'TV', 'ufotable', '2022-01-01', '11', '8.6', 'After visiting the Rengoku residence, Tanjirou and his comrades volunteer for a mission within the Entertainment District, a place where desires are sold and demons dwell. They journey alongside the flashy Sound Hashira, Tengen Uzui, in search of a monstrous foe terrorizing the town. Sworn to slay creatures of the night, the hunt continues. (Source: Funimation) Note: - The first episode aired with a runtime of ~47 minutes. - The last episode aired with a runtime of ~33 minutes.', '/uploads/images/s_142329.jpg', 'Demons,Swordplay,Shounen,Male Protagonist,Oiran,Revenge,Curses,Primarily Teen Cast', 'https://anilist.co/anime/142329'),
('间谍过家家 第2部分', 'SPY×FAMILY 第2クール', 'TV', 'WIT STUDIO', '2022-01-01', '13', '8.1', 'The second half of SPYxFAMILY. With Anya Forger successfully enrolled at the renowned Eden Academy, Operation Strix advances to its second phase. To investigate Ostanian politician Donovan Desmond, Anya must either befriend his son Damian or collect eight Stella Stars to become an Imperial Scholar. Fortunately, Anya has already acquired her first star. In celebration, her adoptive father, Loid, decides to fulfill her wish to adopt a dog. During their canine search, Loid receives new orders from his superiors, who have found that a band of Berlint University students is plotting to assassinate Westalis'' Minister Brantz using bombs worn by trained dogs. While Loid tries to stop their plans, Anya stumbles upon the terrorists'' base of operations. There, she befriends a kindhearted, clairvoyant dog who the family later names Bond. Although the Forgers continue to lead their individual lives in secrecy, the family—with a new fluffy addition—remains united through all of the unusual obstacles thrown their way. (Source: MAL Rewrite)', '/uploads/images/s_142838.jpg', 'Family Life,Found Family,Episodic,Espionage,Urban,Ensemble Cast,Urban Fantasy,Assassins', 'https://anilist.co/anime/142838'),
('咒术回战 怀玉･玉折 / 涩谷事变', '呪術廻戦 第2期', 'TV', 'MAPPA', '2023-01-01', '23', '8.6', 'The second season of Jujutsu Kaisen. The past comes to light when second-year students Satoru Gojou and Suguru Getou are tasked with escorting young Riko Amanai to Master Tengen. But when a non-sorcerer user tries to kill them, their mission to protect the Star Plasma Vessel threatens to turn them into bitter enemies and cement their destinies—one as the world’s strongest sorcerer, and the other its most twisted curse user! (Source: Crunchyroll)', '/uploads/images/s_145064.jpg', 'Curses,Urban,Tragedy,Super Power,Shounen,Exorcism,Urban Fantasy,Male Protagonist', 'https://anilist.co/anime/145064'),
('鬼灭之刃 刀匠村篇', '鬼滅の刃 刀鍛冶の里編', 'TV', 'ufotable', '2023-01-01', '11', '8.1', 'Adaptation of the Swordsmith Village Arc. Tanjiro’s journey leads him to the Swordsmith Village, where he reunites with two Hashira, members of the Demon Slayer Corps’ highest-ranking swordsmen - Mist Hashira Muichiro Tokito and Love Hashira Mitsuri Kanroji. With the shadows of demons lurking near, a new battle begins for Tanjiro and his comrades. Notes: • The first episode has a runtime of ~49 minutes, and received an early premiere in cinemas worldwide as part of a special screening alongside the final two episodes of Kimetsu no Yaiba: Yuukaku-hen. • The final episode has a runtime of ~52 minutes.', '/uploads/images/s_145139.jpg', 'Demons,Shounen,Swordplay,Male Protagonist,Super Power,Curses,Gore,Monster Girl', 'https://anilist.co/anime/145139'),
('欢迎来到实力至上主义的教室 第二季', 'ようこそ実力至上主義の教室へ 2nd Season', 'TV', 'Lerche', '2022-01-01', '13', '7.9', 'The second season of Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e. Tokyo Metropolitan Advanced Nurturing High School seems like a paradise, but in reality, it is an extreme meritocracy. In the class of underachievers, Kiyotaka has begun working with Suzune, who seeks to ascend higher. After a survival test on an uninhabited island, they get to enjoy a luxury liner, but a new class-scrambling test will begin. (Source: Anime News Network)', '/uploads/images/s_145545.png', 'School,Male Protagonist,Primarily Teen Cast,Anti-Hero,Revenge,Ensemble Cast,Fugitive,Battle Royale', 'https://anilist.co/anime/145545'),
('无职转生 第二季 ～到了异世界就拿出真本事～ 第2部分', '無職転生Ⅱ ～異世界行ったら本気だす～', 'TV', 'Studio Bind', '2023-01-01', '13', '8.1', 'After his relationship with Eris Boreas Greyrat reaches new heights, Rudeus Greyrat is ecstatic. Unfortunately, his joy is short-lived, as Eris suddenly abandons him to embark on her own journey. Believing that Eris has lost all interest in him, a heartbroken and depressed Rudeus sets forth to the Northern Territories. With his sole goal being to locate his mother on the vast continent, Rudeus wonders if persisting through daily life is worth the pain, falling into a robotic routine as he endlessly ruminates on his lost love. However, the dangers of the North soon prove that one cannot survive with a dulled mind. While on a quest with the party Counter Arrow, with whom he recently became acquainted, Rudeus has a brush with death—an experience that forces him to finally snap out of his despair. With his newfound teammates, Rudeus rediscovers the pleasure of daily adventuring and moves forward with his original goal of living his second lease on life to the fullest. (Source: MAL Rewrite) Note: Includes episode 0, Shugo Jutsushi Fitz.', '/uploads/images/s_146065.png', 'Isekai,Reincarnation,Rehabilitation,Male Protagonist,Magic,Coming of Age,Medieval,Boarding School', 'https://anilist.co/anime/146065'),
('【我推的孩子】 第三季', '【推しの子】', 'TV', 'Doga Kobo', '2023-01-01', '11', '8.4', 'When a pregnant young starlet appears in Gorou Amemiya’s countryside medical clinic, the doctor takes it upon himself to safely (and secretly) deliver Ai Hoshino’s child so she can make a scandal-free return to the stage. But no good deed goes unpunished, and on the eve of her delivery, he finds himself slain at the hands of Ai’s deluded stalker — and subsequently reborn as Ai’s child, Aquamarine Hoshino! The glitz and glamor of showbiz hide the dark underbelly of the entertainment industry, threatening to dull the shine of his favorite star. Can he help his new mother rise to the top of the charts? And what will he do when unthinkable disaster strikes? (Source: HIDIVE) Note: Episode 1【推しの子】Mother and Children was pre-screened in advance in Japanese theaters on March 17, 2023. The regular TV broadcast began on April 12, 2023. The first episode has an extended runtime of ~82 minutes.', '/uploads/images/s_150672.jpg', 'Acting,Tragedy,Idol,Revenge,Twins,Male Protagonist,Urban,Reincarnation', 'https://anilist.co/anime/150672'),
('物理魔法使马修', 'マッシュル-MASHLE-', 'TV', 'A-1 Pictures', '2023-01-01', '12', '7.6', 'This is a world of magic. This is a world in which magic is casually used by everyone. In a deep, dark forest in this world of magic, there is a boy who is singlemindedly working out. His name is Mash Burnedead, and he has a secret. He can’t use magic. All he wanted was to live a quiet life with his family, but people suddenly start trying to kill him one day and he somehow finds himself enrolled in Magic School. There, he sets his sights on becoming a “Divine Visionary,” the elite of the elite. Will his ripped muscles work against the best and brightest of the wizarding world? The curtain rises on this off-kilter magical fantasy in which the power of being jacked crushes any spell! (Source: Crunchyroll)', '/uploads/images/s_151801.png', 'Magic,Male Protagonist,Shounen,Parody,School,Fitness,Slapstick,Primarily Teen Cast', 'https://anilist.co/anime/151801'),
('我独自升级', '俺だけレベルアップな件', 'TV', 'A-1 Pictures', '2024-01-01', '12', '8.1', 'They say whatever doesn’t kill you makes you stronger, but that’s not the case for the world’s weakest hunter Seong Jin-U. After being brutally slaughtered by monsters in a high-ranking dungeon, Jin-U came back with the System, a program only he could see, that’s leveling him up in every way. Now, he’s inspired to discover the secrets behind his powers and the dungeon that spawned them. (Source: Crunchyroll)', '/uploads/images/s_151807.jpg', 'Dungeon,Male Protagonist,Urban Fantasy,Super Power,Magic,Necromancy,Cultivation,Survival', 'https://anilist.co/anime/151807'),
('怪兽8号 第二季', '怪獣８号', 'TV', 'Production I.G', '2024-01-01', '12', '8.1', 'With the highest kaiju-emergence rates in the world, Japan is no stranger to attack by deadly monsters. Enter the Japan Defense Force, a military organization tasked with the neutralization of kaiju. Kafka Hibino, a kaiju-corpse cleanup man, has always dreamed of joining the force. But when he gets another shot at achieving his childhood dream, he undergoes an unexpected transformation. How can he fight kaiju now that he’s become one himself?! (Source: VIZ Media)', '/uploads/images/s_153288.jpg', 'Kaiju,Monster Boy,Shapeshifting,Male Protagonist,Super Power,Shounen,Henshin,Urban Fantasy', 'https://anilist.co/anime/153288'),
('葬送的芙莉莲 第二季', '葬送のフリーレン', 'TV', 'MADHOUSE', '2023-01-01', '28', '9.1', 'The adventure is over but life goes on for an elf mage just beginning to learn what living is all about. Elf mage Frieren and her courageous fellow adventurers have defeated the Demon King and brought peace to the land. But Frieren will long outlive the rest of her former party. How will she come to understand what life means to the people around her? Decades after their victory, the funeral of one her friends confronts Frieren with her own near immortality. Frieren sets out to fulfill the last wishes of her comrades and finds herself beginning a new adventure… (Source: Crunchyroll)', '/uploads/images/s_154587.jpg', 'Travel,Magic,Elf,Female Protagonist,Philosophy,Time Skip,Medieval,Found Family', 'https://anilist.co/anime/154587'),
('药屋少女的呢喃 第二季', '薬屋のひとりごと', 'TV', 'OLM', '2023-01-01', '24', '8.8', 'Maomao lived a peaceful life with her apothecary father. Until one day, she’s sold as a lowly servant to the emperor’s palace. But she wasn’t meant for a compliant life among royalty. So when imperial heirs fall ill, she decides to step in and find a cure! This catches the eye of Jinshi, a handsome palace official who promotes her. Now, she’s making a name for herself solving medical mysteries! (Source: Crunchyroll)', '/uploads/images/s_161645.jpg', 'Female Protagonist,Medicine,Ancient China,Drugs,Historical,Detective,Conspiracy,Politics', 'https://anilist.co/anime/161645'),
('鬼灭之刃 柱训练篇', '鬼滅の刃 柱稽古編', 'TV', 'ufotable', '2024-01-01', '8', '7.9', 'Adaptation of the Hashira Training Arc. The Hashira, the Demon Slayer Corps'' highest ranking swordsmen and members. The Hashira Training has begun in order to face the forthcoming battle against Muzan Kibutsuji. Each with their own thoughts and hopes held in their hearts, a new story for Tanjiro and the Hashira begins. (Source: Aniplex USA) Note: The first episode received an early premiere in cinemas as part of a special screening alongside the final episode of Kimetsu no Yaiba: Katanakaji no Sato-hen.', '/uploads/images/s_166240.jpg', 'Demons,Shounen,Swordplay,Cultivation,Male Protagonist,Tragedy,Curses,Suicide', 'https://anilist.co/anime/166240'),
('胆大党 第二季', 'ダンダダン', 'TV', 'Science SARU', '2024-01-01', '12', '8.3', 'This is a story about Momo, a high school girl who comes from a family of spirit mediums, and her classmate Okarun, an occult fanatic. After Momo rescues Okarun from being bullied, they begin talking. However, an argument ensues between them since Momo believes in ghosts but denies aliens exist, and Okarun believes in aliens but denies ghosts exist. To prove to each other what they believe in is real, Momo goes to an abandoned hospital where a UFO has been spotted and Okarun goes to a tunnel rumored to be haunted. To their surprise, they each encounter overwhelming paranormal activities that transcend comprehension. Amid these predicaments, Momo awakens her hidden power and Okarun gains the power of a curse to overcome these new dangers! Their fateful love begins as well!? The story of the occult battle and adolescence starts! (Source: Crunchyroll) Notes: - Worldwide premiere of Episode 1 before the Japanese television premiere occurred at Anime Expo July 6, 2024. - Episodes 1-3 titled as DAN DA DAN: FIRST ENCOUNTER was pre-screened in advance in theaters on August 31, 2024 in Asia, September 7, 2024 in Europe and September 13, 2024 in North America. The regular TV broadcast began October 4, 2024.', '/uploads/images/s_171018.jpg', 'Urban Fantasy,Youkai,Ghost,Aliens,Super Power,Primarily Teen Cast,Surreal Comedy,Henshin', 'https://anilist.co/anime/171018'),
('咒术回战 死灭回游 前篇', '呪術廻戦 死滅回游 前編', 'TV', 'MAPPA', '2026-01-01', '12', '8.6', 'The third season of Jujutsu Kaisen. After the Shibuya Incident, a deadly jujutsu battle known as the Culling Game orchestrated by Noritoshi Kamo erupts across ten colonies in Japan. Haunted by guilt over the mass killings in Shibuya and wary of Sukuna’s interest in Fushiguro, Itadori chooses not to return to Jujutsu High. Instead, he teams up with Choso to exorcise the countless cursed spirits unleashed by Noritoshi Kamo. Amid this chaos, the Jujutsu Headquarters revokes Yuji Itadori’s suspended death sentence and appoints special-grade sorcerer Yuta Okkotsu as his executioner. Newly awakened modern sorcerers and resurrected ancient ones, now fighting as players in the Culling Game, collide with conflicting motives, driving the world once more toward an age ruled by jujutsu. (Source: TOHO Animation)', '/uploads/images/s_172463.jpg', 'Urban Fantasy,Curses,Urban,Shounen,Death Game,Tragedy,Super Power,Battle Royale', 'https://anilist.co/anime/172463'),
('我独自升级 第二季', '俺だけレベルアップな件 Season 2 -Arise from the Shadow-', 'TV', 'A-1 Pictures', '2025-01-01', '13', '8.4', 'The second season of Solo Leveling. Mastering his new abilities in secret, Jin-U must battle humanity''s toughest foes to save his mother. (Source: Crunchyroll News)', '/uploads/images/s_176496.png', 'Urban Fantasy,Dungeon,Male Protagonist,Necromancy,Magic,Super Power,Cultivation,Creature Taming', 'https://anilist.co/anime/176496')
;
INSERT INTO sekai_dataobject_anime_character (series_id, name, original_name, role, voice_actor, description, image_url) VALUES
(1, 'Spike Spiegel', 'スパイク・スピーゲル', '主角', 'Kouichi Yamadera', '__Height:__ 185 cm Spike Spiegel is a tall and lean 27-year-old bounty hunter born on Mars.', '/uploads/images/c_1.jpg'),
(1, 'Faye Valentine', 'フェイ・バレンタイン', '主角', 'Megumi Hayashibara', 'One of the members of the bounty hunting crew in the anime series Cowboy Bebop. Although appearing to be no more than her 23 years alive suggests, Faye is actually upwards of 74-years-old, having been put into cryogenic freeze after a space shuttle accident. During the course of the series (set in 2071), Faye manages to cross paths with [Spike](https://anilist.co/character/1) and [Jet](https://anilist.co/character/3) twice before she finally makes herself at home aboard their ship the second time, much to the consternation and disapproval of the two men, both of whom have their own reservations about women in general. Faye herself is brash, egotistical, and quite lazy, despite taking plenty of time to pamper and care for her own appearance. Faye has also been placed under arrest several times in the series and spends much time in handcuffs on the ship. She, at times, expects the boys to take care of bounties for her, while she sits by idly to reap the benefits and eat all their food, another source of conflict. Seemingly little more than a thorn in her partners’ sides, Faye is actually a well-rounded member of the team. She can handle herself exceptionally well for a woman of her slight appearance, displaying at least once in the series that she packs quite a mean punch. Adept at flying, Faye has stood her ground just as well as Spike has in an aerial dogfight in her ship Red Tail, at times even against Spike in an aerial dogfight. She also excels with guns, and is first seen', '/uploads/images/c_2.jpg'),
(1, 'Jet Black', 'ジェット・ブラック', '主角', 'Unshou Ishizuka', 'Jet, known on his home satellite as the "Black Dog" for his tenacity, is a 36-year-old former cop from Ganymede (a Jovian satellite) and acts as [Spike](https://anilist.co/character/1/Spiegel-Spike)''s foil during the series. Physically, Jet is very tall with a muscular build. He wears a beard with no mustache, and is completely bald save for the back of his head. Spike acts lazy and uninterested, whereas Jet is hard working and a jack-of-all-trades. Jet was once an investigator in the Inter Solar System Police (ISSP) for many years until he lost his arm in an investigation that went awry when his corrupt partner (and friend at the time) betrayed him. His arm was replaced with a cybernetic limb (later revealed to be by choice, as biological replacements were possible, he wanted the fake arm as a reminder of what happened), yet his loss of limb coupled with the general corruption of the police force prompted Jet to quit the ISSP in disgust and become a freelance bounty hunter. Jet also considers himself something of a renaissance man: he cultivates bonsai trees, cooks, enjoys jazz/blues music (he named his ship the Bebop, referring to a type of jazz), especially Charlie Parker, and even has interest in Goethe. As a character, Jet is the quintessential oyaji or "dad" even though he often wishes people would view him as a more brotherly figure (so as not to seem old). Jet is skilled with handguns, typically carrying a pre-2004 Walther P99, as well as the use of the netgun. He is ', '/uploads/images/c_3.jpg'),
(1, 'Ein', 'アイン', '配角', 'Kouichi Yamadera', 'Ein is a Pembroke Welsh Corgi brought aboard the Bebop by Spike after a failed attempt to capture a bounty. Ein is a "data dog": while the televised series only briefly hints on the fact that this means Ein''s brain was somehow enhanced drastically, the manga shows Ed accessing data stored in Ein''s brain via a virtual reality-type interface with which she has a conversation with a human proprietor. It is obvious that Ein is abnormally intelligent, as he is able to answer the telephone, drive a car (just the wheel), use the SSW, play shōgi, and generally do a number of other things that an average canine should not be able to do, but he never talks in a human language during the show. He does, however, speak in Session 18 "Speak Like A Child" after the credits Ein tells Spike "Next Episode: Wild Horses". He is able to "speak" to other species, as demonstrated in Session 17, "Mushroom Samba" (he spoke to a cow with a subtitled bark of "Thanks", to which the cow has a subtitled moo back of "No problem"). It is likely that Ed is the only crew member with any idea of Ein''s capabilities, as the other crew members are quick to dismiss Ein, and never seem to acknowledge him as more than a pet. Ein initially takes a shine to Jet, but when Ed joins the crew, he comes around to her as well. Frequently the two trade roles, with Ein expressing very human sentiments via facial expression and Ed regressing to a feral state. He went with Ed after she left the crew, probably because of his att', '/uploads/images/c_4.jpg'),
(1, 'Edward Wong Hau Pepelu Tivrusky IV', 'エドワード・ウォン・ハウ・ペペル・チブルスキー4世', '主角', 'Aoi Tada', 'Ed is an eccentric, resourceful, childlike, tomboyish, and intelligent teenager. Ed first encounters the Bebop and its crew when she hacks the ship on its way to Earth. After Ed helps the Bebop crew cash in the Earth hacker bounty, she insists on joining the crew. When [Faye](https://anilist.co/character/2/Valentine-Faye) tries to leave Earth without her, Ed hacks the Bebop and holds it hostage until she is permitted to join. ~!Later in the story when the Bebop is back on Earth, the crew stumbles across an orphanage that Ed used to live in. After seeing some old friends there, Ed is informed that her father has come looking for her recently. Ed decides to make up a bounty on her father to convince [Spike](https://anilist.co/character/1/Spiegel-Spike) to find him. When Spike finds him, Ed decides to leave the Bebop with [Ein](https://anilist.co/character/4/Ein) to live with her father on Earth.!~', '/uploads/images/c_16.jpg'),
(1, 'Vicious', 'ビシャス', '配角', 'Norio Wakamoto', 'It''s all in the name with Vicious: he is ruthless, bloodthirsty, cunning and ambitious, willing to do anything in order to secure a position of power. He is a member of the Red Dragon Crime Syndicate in Tharsis, and is often referred to or depicted as a venomous snake. His weapon of choice is not a firearm, but a katana which he wields skillfully, even against gun-wielders. ~!After [Spike](https://anilist.co/character/1/Spiegel-Spike)''s supposed death, Vicious also leaves the Red Dragons briefly to fight in the Titan War of 2068 although his precise motivations for enlisting are debated.!~', '/uploads/images/c_2734.jpg'),
(1, 'Julia', 'ジュリア', '配角', 'Gara Takashima', 'Julia is a beautiful and mysterious woman from both Spike and Vicious'' pasts. A love triangle among the three caused Spike to leave the syndicate rather than challenge Vicious. Spike had wanted to take her with him when he left the syndicate, but she was blackmailed by Vicious into almost shooting Spike. Vicious found out they were planning to run away together and confronted Julia, telling her that she would have to kill Spike, or both of them would be killed. To protect not only herself but also the man she loved, she ran away, never meeting Spike at the cemetery as both of them had planned. (from Wikipedia)', '/uploads/images/c_2735.jpg'),
(1, 'Grencia Mars Elijah Guo Eckener', 'グレン', '配角', 'Kenyuu Horiuchi', 'Gren was once a soldier for the war on Titan, and appears in the two-part episodes of ''Jupiter Jazz''. On Titan he fought beside Vicious, who he admired and found encouragement in, during the war. After the war, Gren came back hoping to be a jazz musician, but that plan was cut short when he was arrested on the pretense of being a spy. In prison, Gren heard that Vicious testified against him; this and the isolation drove him mad. The prison used prisoners for drug experiments, and he was forced to become a test subject. (from Wikipedia) Height: 6ft 2 inches Age : 29 Weight : 172 pounds', '/uploads/images/c_2736.jpg'),
(1, 'Punch', 'パンチ', '配角', 'Tsutomu Tareki', 'Co-hosts the TV show Big Shot along with Judy. The show features the duo in western attire and provides information on popular Bounty Heads throughout the star system. Punch speaks with a faked western/Mexican accent, and tends to spout out various old-West sayings.', '/uploads/images/c_6693.jpg'),
(1, 'Judy', 'ジュディ', '配角', 'Miki Nagasawa', 'Co-hosts the TV show Big Shot along with Punch. The show features the duo in western attire and provides information on popular Bounty Heads throughout the star system. Judy acts like a stereotypical dumb-blonde, and wears a very revealing outfit. After Punch announces that the show has been cancelled, Judy reacts violently and exclaims that "The station will hear from her agent about this!" Later, it is revealed that she is engaged to be married to her agent.', '/uploads/images/c_6694.jpg'),
(1, 'Appledelhi Siniz Hesap Lütfen', 'アップルデリー・シニズ・ヘサップ・リュトフェン', '配角', 'Kenji Utsumi', '__Height:__ 6''0" __Birthplace:__ Earth Afedersiniz Hesap Lutfen (which means "excuse me, check please" in Turkish), is Ed''s father. He is a cartographer on Earth (a questionable occupation on a planet which undergoes changes to its landscape daily due to asteroid impacts). In episode 24 of Cowboy Bebop, Ed put a 50.000 000 Oolong bounty on him, which Jet and Spike saw as 50 million Oolongs (it is in fact only 50) and decided to collect his bounty. This allowed Edward to find her father, who asked her if she wanted to come along with her, but left without hearing her answer because a meteor struck.', '/uploads/images/c_13249.jpg'),
(1, 'Coffee', 'コフィ', '配角', 'Atsuko Tanaka', NULL, '/uploads/images/c_15713.jpg'),
(1, 'Dr. Londez', 'ロンデス', '配角', 'Chikao Ootsuka', NULL, '/uploads/images/c_18441.png'),
(1, 'Bob', 'ボブ', '配角', 'Yutaka Nakano', '"Bob" is an ISSP policeman based on Ganymede to whom Jet frequently goes to for inside information when looking for bounty heads. Throughout the series, and especially in the film, Bob provides (sometimes reluctantly) crucial information. (wikipedia)', '/uploads/images/c_19117.png'),
(1, 'Bull', 'ブル', '配角', 'Takehiro Koyama', 'A kind old shaman, apparently of Native American descent. Laughing Bull lives on Mars, and figures prominently in a number of Cowboy Bebop sessions. Spike goes to Laughing Bull for advice in Session 1 while looking for bounty head Asimov; in "The Real Folk Blues, Part 2", Jet goes to him for information on Spike''s whereabouts. Laughing Bull also succors Spike after his fight with Vincent in Cowboy Bebop: The Movie. Laughing Bull has a son, to whom he occasionally imparts his wisdom. Laughing Bull refers to Spike as "Swimming Bird", and calls Jet "Running Rock". (wikipedia)', '/uploads/images/c_19118.png'),
(1, 'Wen', 'ウェン', '配角', 'Yumi Touma', 'Wen was a victim of the Astral Gate accident that caused his body to stop aging. He was a gifted harmonica player that became jaded over time and held people hostage, like Zebra, in order to keep his condition a secret.', '/uploads/images/c_19119.jpg'),
(1, 'Udai Taxim', 'ウダイ', '配角', 'Kousei Hirota', 'Udai Taxim was an assassin and former member of the European syndicate. He was involved in a plot to kill or injure the former ISSP agent Jet Black, who was one of the few police officers not on the syndicate payroll. As a result Jet lost his arm and was forced to use a prosthetic one. In 2071 Udai was transferred on a transport prison ship to Pluto when an electrically short-circuiting allowed him and his fellow inmates to hijack the ship. Jet and his former partner at the ISSP, Fad, tracked the ship down and boarded it. Fad killed Udai after he revealed that his partner was the shooter that took Jet''s arm. He uses the same knives as Navajas, the knife thrower from Desperados (1995).', '/uploads/images/c_23611.png'),
(1, 'Roco Bonnaro', 'ロコ', '配角', 'Ryuusei Nakao', 'Rocco Bonnaro is a member of Piccaro Calvino''s gang. He is involved in organized crime in order to support his blind younger sister, Stella Bonnaro and does everything he can to help her regain her sight. Rocco sees Spike effortlessly take out several hijackers on a spaceliner and begs Spike to teach him how to fight. He befriends Spike although he does not tell him about the bounty on his head. Everything goes awry when Rocco gives Spike a package to hold onto, which contains a plant called "Grey Ash" that he stole from Calvino. This plant, worth millions upon millions of woolongs, is capable of curing "Venus Sickness", the disease which has blinded Stella. Rocco has a rendezvous with Spike and they fight against Calvino''s gang. ~!He ends up dead protecting the plant.!~', '/uploads/images/c_23686.png'),
(1, 'Rhint Celonias', 'リンド', '配角', 'Kappei Yamaguchi', 'Rhint is the boyfriend of Jet''s old girlfriend that killed an loan shark in Jet''s hometown. He has an bounty on his head and he ends up caught by Jet and goes to jail.', '/uploads/images/c_23687.png'),
(1, 'Andy Von de Oniyate', 'アンディ・フォン・デ・オニアテ', '配角', 'Masashi Ebara', 'Andy is a hunter who went after a criminal called Teddy Bomber whom he thought to be Spike. He is always with his mare, Onyx. He''s a member of YMCA, Young Man''s Cowboy Association. After fighting and losing he gives his cowboy title to Spike and turns into a samurai.', '/uploads/images/c_23740.png'),
(1, 'Tongpu', '東風', '配角', 'Banjou Ginga', 'Mad "Tongpu" Pierrot is an assassin who targets high ranking syndicate officials. He is highly skilled with all manner of firearms and is armed with an armory equal to a military platoon under his large coat. He takes a child-like enjoyment in killing and causing destruction, always arriving and leaving with a smile, always laughing when "working". ~!Mad Pierrot was a patient in a program to develop a super soldier. The process was, however, too much for him to handle, and his mental state degraded to an almost vegetative state. As he was transported to his permanent holding cell after being removed from the program, he freed himself and killed everybody he encountered in the facility - all while smiling. Since the experiment made him bulletproof, Pierrot has never felt pain, and thus his mind collapsed when Spike made him suffer a minor leg wound. Pierrot died in a theme park, squashed by a giant robotic dog''s foot. !~', '/uploads/images/c_29313.png'),
(1, 'Abdul Hakim', 'ハキム', '配角', 'Ryuuzaburou Ootomo', 'The notorious serial pet thief who went after Ein. His appearance and fighting style were modeled after the NBA star Kareem Abdul-Jabbar. source: http://cowboybebop.wikia.com/wiki/Abdul_Hakim', '/uploads/images/c_29559.png'),
(1, 'Katerina Solensan', 'カテリーナ', '配角', 'Yurika Hino', 'Katerina Solensan was a drug smuggler and woman of the criminal Asimov Solensan. She dreamed of leaving the Tijuana asteroid for a better life on Mars, but died in her escape attempt alongside Asimov.', '/uploads/images/c_30572.png'),
(1, 'Shin', 'シン', '配角', 'Nobuyuki Hiyama', 'Shin is Lin''s brother who proves to be more loyal to his friends than to the Red Dragon Crime Syndicate. He appeared in Session 25: The Real Folk Blues (Part One), where he assists Spike in a duel against members of the Syndicate. He is the one who informs Spike that Vicious has tried to seize control of the organization and was sentenced to death. Shin also states that everyone close to Spike is being hunted down.', '/uploads/images/c_35870.jpg'),
(1, 'Meifa Puzi', 'メイファ', '配角', 'Arisa Ogasawara', NULL, '/uploads/images/c_36364.png'),
(1, 'Miles', 'マイルズ', '配角', 'Yoku Shioya', NULL, '/uploads/images/c_37186.png'),
(1, 'Teddy Bomber', 'テディ・ボマー', '配角', 'Takaya Hashi', 'Ted Bower, more commonly known as the "Teddy Bomber," was a terrorist who used explosive teddy bears to destroy what he viewed as symbols of capitalism. He viewed himself as an activist, trying to warn the public about the dangers of unchecked capitalism. He sees the tallest skyscrapers of Mars as symbols of these capitalistic dangers and has resolved to destroy them, starting with the tallest. (Source: Cowboy Bebop Fandom)', '/uploads/images/c_38884.png'),
(1, 'Fad', 'ファド', '配角', 'Daisuke Gouri', '[Jet Black](https://anilist.co/character/3/)''s former ISSP partner.', '/uploads/images/c_42425.jpg'),
(1, 'Victoria Terpsichore', 'ブイティー', '配角', 'Tomie Kataoka', 'Victoria Terpsichore is a tough-talking, and widowed space trucker, whose deceased husband, Ural Terpsichore, is a man that fellow bounty hunters regard as a "legendary bounty hunter." Always with her cat, Zeros, she appears in the episode "Heavy Metal Queen".', '/uploads/images/c_70753.jpg'),
(1, 'Whitney Hagas Matsumoto', 'ウィットニー・ハガス・マツモト', '配角', 'Akio Ootsuka', NULL, '/uploads/images/c_72255.png'),
(1, 'Asimov Solensan', 'アシモフ・ソーレンサン', '配角', 'Rintarou Nishi', NULL, '/uploads/images/c_78693.png'),
(1, 'Pet Shop no Owner', 'ペットショップのオーナー', '配角', 'Ako Mayama', NULL, '/uploads/images/c_79667.png'),
(1, 'MPU', 'んぴゅー', '配角', 'Jouji Nakata', 'Artificial Intelligence of abandoned satellite appeared in episode 9.', '/uploads/images/c_83271.jpg'),
(1, 'Stella Bonnaro', 'ステラ・ボナーロ', '配角', 'Maaya Sakamoto', NULL, '/uploads/images/c_85271.jpg'),
(1, 'Iresumi Otoko', 'イレズミ男', '配角', 'Keiji Fujiwara', NULL, '/uploads/images/c_165883.png'),
(1, 'Videomania', 'ビデオマニア', '配角', 'Shigeru Chiba', 'A clerk in a video store on Mars who Spike and Jet came to see about a beta cassette in episode 18. He was enthusiastic about antique technology and old 20th century television shows. He also thought that shows were not as good as they used to be.', '/uploads/images/c_170071.png'),
(1, 'Shaft', 'シャフト', '配角', 'Houchuu Ootsuka', 'The younger brother of the two Shaft Brothers. Shaft learned that his older brother bought some psychedelic mushrooms from a mushroom dealer called Domino Walker and, after eating one, he laughed himself to death, prompting Shaft to swear revenge on Walker.', '/uploads/images/c_175788.png'),
(1, 'Domino Walker', 'ドミノ・ウォーカー', '配角', 'Tesshou Genda', 'A dealer of hallucinogenic mushrooms and bounty head.', '/uploads/images/c_175789.png'),
(1, 'Alisa', 'アリサ', '配角', 'Mika Doi', 'Alisa is a business owner on Ganymede. Alisa had a relationship with Jet Black for a long time in the early 2060s when he worked for the ISSP. However, she became increasingly unsatisfied, as she felt she had no independence outside of their relationship. One day, she decided she had to end it and left Jet, leaving for him a watch and a note that simply said, "Farewell." Alisa started to run a bar called La Fin by 2071. However, business became slow as the area was much less trafficked than it used to be. Alisa decided to take out a loan with Law Rentzuo in order to keep the bar open. (Source: Cowboy Bebop Fandom Wikia)', '/uploads/images/c_213076.png'),
(1, 'Sally Yung', 'サリー', '配角', 'Ikuko Tani', 'Sally Yung was one of [Faye Valentine''s](https://anilist.co/character/2) high school classmates. Yung was a friend of Faye in the early 21st century. They made some videos which were recorded on beta cassette. Yung would later marry, have children, and eventually grandchildren including [a girl](https://anilist.co/character/214420). (Source: Cowboy Bebop Wikia)', '/uploads/images/c_214419.png'),
(1, 'Mago', '孫', '配角', 'Ruri Asano', NULL, '/uploads/images/c_214420.png'),
(1, 'McIntire', 'マッケンタイア', '配角', 'Shigeru Nakahara', NULL, '/uploads/images/c_214421.png'),
(1, 'Clara', 'クララ', '配角', 'Mami Horikoshi', NULL, '/uploads/images/c_214422.png'),
(1, 'Cain', 'カイン', '配角', 'Ayumi Kida', NULL, '/uploads/images/c_214423.png'),
(1, 'Sean', 'ショーン', '配角', 'Kazumi Okushima', NULL, '/uploads/images/c_214424.png'),
