(126, 'Daigakusei C', '大学生 C', '配角', 'Seiichirou Yamashita', NULL, '/uploads/images/c_135298.jpg'),
(126, 'Masashi Asagiri', '浅桐真史', '配角', 'Mitsuaki Hoshino', 'He is a businessman​ and the client who hired psychics to get rid of the spirit possessing his daughter Minori Asagiri.', '/uploads/images/c_135299.jpg'),
(126, 'Kokyaku', '顧客', '配角', 'Ryouta Takeuchi', NULL, '/uploads/images/c_135300.jpg'),
