(126, 'Satake', '佐竹', '配角', 'Uki Satake', NULL, '/uploads/images/c_137024.jpg'),
(126, 'Tamaki', '玉木', '配角', '', 'He is an esper and former leader of 1st Division of Claw.', '/uploads/images/c_137025.png'),
(126, 'Hitoshi', '人氏', '配角', '', 'He was a client of Arataka Reigen, he wanted to speak with his deceased father about a password to a safe. ~!He attempted to stab Reigen to get the combo but was knocked out by Reigen.!~', '/uploads/images/c_137026.jpg'),
(126, 'Ebiwara', '蛯原', '配角', '', 'He is an esper and former leader of actually disbanded terrorist organization Claw''s 3rd Division.', '/uploads/images/c_137027.png'),
(126, 'Fukuda', '福田', '配角', 'Tarou Kiuchi', 'He is an esper and one of Sho Suzuki''s subordinates.', '/uploads/images/c_137028.jpg'),
