(169, 'Kobun A', '子分A', '配角', 'Takayuki Ishii', NULL, '/uploads/images/c_293660.jpg'),
(169, 'Kobun B', '子分B', '配角', 'Yusaku Hiyama', NULL, '/uploads/images/c_293661.jpg'),
