(193, 'Bo-Ra Lee', '이보라', '配角', 'Riria Ito', 'A-Rank Mage from the Hunters Guild who specializes in summoning magic.⁣ She is straightforward, very meticulous, and believes that the only way to overcome difficulties is by laying out the known facts.', '/uploads/images/c_326616.png'),
(193, 'Chousa-ka', '調査課', '配角', 'Yukiko Motoyoshi', NULL, '/uploads/images/c_326618.png'),
(193, 'Shokuin', '職員', '配角', 'Ikuto Kanemasa', NULL, '/uploads/images/c_327117.png'),
(193, 'Monkasei', '門下生', '配角', 'Ikuto Kanemasa', NULL, '/uploads/images/c_328557.jpg'),
(193, 'Yuuka', 'ユウカ', '配角', 'Ayako Mitani', NULL, '/uploads/images/c_328558.png'),
(193, 'Mizuki no Haha', '観月の母', '配角', 'Misa Katou', NULL, '/uploads/images/c_328559.jpg'),
